INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0000', N'Cây Cảnh Để Bàn', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-canh-de-ban.jpg', N'Đặt thêm một chậu cây để bàn làm việc giúp mang lại cảm giác thoải mái, giảm áp lực, stress nên có thể chữa được bệnh trầm cảm.', CAST(N'2024-11-20T14:49:05.100' AS DateTime), CAST(N'2024-11-20T14:49:05.100' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0001', N'Cây Cảnh Văn Phòng', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-canh-van-phong.jpg', N'Việc trồng thêm cây xanh trong văn phòng là một cách bảo vệ sức khỏe thiết thực, bởi môi trường văn phòng thường kín và tồn tại nhiều chất khí độc hại. Hãy cùng MOW Garden xây dựng một môi trường làm việc lành mạnh để công việc luôn được thuận lợi.', CAST(N'2024-11-20T14:49:05.103' AS DateTime), CAST(N'2024-11-20T14:49:05.103' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0002', N'Cây Lọc Không Khí', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-loc-khong-khi.jpg', N'Khả năng hấp thụ các loại chất khí độc hại có trong không khí của cây xanh sẽ giúp bầu không khí trong nhà trở nên trong lành và an toàn hơn, giúp bảo vệ sức khỏe của các thành viên trong gia đình. Những loại chất khí độc hại như benzene, formaldehyde, trichloroethylene, xylene, and toluene.', CAST(N'2024-11-20T14:49:05.103' AS DateTime), CAST(N'2024-11-20T14:49:05.103' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0003', N'Cây Phong Thủy', N'https://mowgarden.com/wp-content/uploads/2023/04/cay-phong-thuy-de-trong-nha.jpg', N'Cây xanh luôn có vai trò quan trọng đối với đời sống hàng ngày. Do đó, việc lựa chọn loại cây và vị trí trồng được chú trọng và lựa chọn cẩn thận theo những quy luật của thuật phong thủy. Cây xanh được chia thành âm dương và ngũ hành, tùy vào mỗi gia chủ mà lựa chọn loại cây cảnh phù hợp với mình.', CAST(N'2024-11-20T14:49:05.103' AS DateTime), CAST(N'2024-11-20T14:49:05.103' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0004', N'Cây Trong Nhà', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-canh-trong-trong-nha.jpg', N'Giúp cho ngôi nhà của bạn thêm tươi mới và xanh với những sản phẩm cây trong nhà của MOW Garden. Thật tuyệt vời mang đến cho bạn những phút giây thư giãn bên canh nhữngsản phẩm cây xanh chất lượng.', CAST(N'2024-11-20T14:49:05.107' AS DateTime), CAST(N'2024-11-20T14:49:05.107' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0005', N'Cây Cần Ít Ánh Sáng', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-can-it-anh-sang.jpg', N'Đa phần các loài thực vật trong tự nhiên đều cần tới ánh sáng để chúng quang hợp, một số thì cần nhiều, và cũng có một số cần rất ít ánh sáng. Chúng ta lựa chọn các loại cây cần ít ánh sáng vì khi đặt trong nhà thì nguồn sáng sẽ bị hạn chế, không như ánh sáng ngoài trời.', CAST(N'2024-11-20T14:49:05.107' AS DateTime), CAST(N'2024-11-20T14:49:05.107' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0006', N'Cây Dễ Trồng Trong Nhà', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-de-trong-trong-nha.jpg', N'Đa phần các loại cây trồng được trong nhà đều thuộc loại dễ chăm sóc. Nếu như bạn không có nhiều thời gian thì hãy lựa chọn các loại cây có sức sống tốt, chúng có thể chịu được hạn, cần ít ánh sáng và không cần phải bón phân thường xuyên.', CAST(N'2024-11-20T14:49:05.107' AS DateTime), CAST(N'2024-11-20T14:49:05.107' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0007', N'Cây Trong Phòng Khách', N'', N'', CAST(N'2024-11-20T14:49:05.110' AS DateTime), CAST(N'2024-11-20T14:49:05.110' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0008', N'Cây Trong Bếp & Nhà Tắm', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-canh-trong-phong-bep.jpg', N'Với sắc xanh từ cây, không gian bí bức và nóng nực của những gian bếp như được làm dịu mát lại. Đây cũng là một giai pháp khử mùi và thanh lọc không khí rất hiệu quả, hơn nữa cây xanh còn giúp tăng tính thẩm mỹ cho khu vực bếp và phòng ăn', CAST(N'2024-11-20T14:49:05.110' AS DateTime), CAST(N'2024-11-20T14:49:05.110' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0009', N'Cây Trang Trí Nhà Cửa', N'', N'', CAST(N'2024-11-20T14:49:05.110' AS DateTime), CAST(N'2024-11-20T14:49:05.110' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0010', N'Cây Trước Cửa & Hành Lang', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-trang-tri-nha-cua.jpg', N'Khu vực ban công tuy không rộng nhưng nó vẫn có thể biến thành một khu vườn của riêng bạn. Thật tuyệt vời khi được thưởng thức một ly trà, ăn miếng bánh và đọc cuốn sách yêu thích, tại khu vườn nhỏ xanh mát này, sau một ngày làm việc mệt mỏi.', CAST(N'2024-11-20T14:49:05.110' AS DateTime), CAST(N'2024-11-20T14:49:05.110' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0011', N'Cây Cao & Lớn Trong Nhà', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-cao-lon-trong-nha.jpg', N'Nếu muốn tạo hiệu ứng không gian trải rộng hãy thử đặt một chậu cây cảnh cao và lớn tại góc tường. Với chiều cao của mình, cây cảnh sẽ thu hút mọi ánh nhìn vào đường thẳng kiến trúc.', CAST(N'2024-11-20T14:49:05.113' AS DateTime), CAST(N'2024-11-20T14:49:05.113' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0012', N'Cây Kiểng lá', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-kieng-la.jpg', N'Với vẻ đẹp tuyệt vời từ những cái cây kiểng lá giống như liều thuốc hữu hiệu cho chứng "đâu đầu" mỗi khi làm việc căng thẳng. Ngoài giá trị về mặt tinh thần thì kiểng lá là một sự lựa chọn rất tuyệt vời giúp gia tăng thẩm mỹ cho không gian sống.', CAST(N'2024-11-20T14:49:05.113' AS DateTime), CAST(N'2024-11-20T14:49:05.113' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0013', N'Cây Nhiệt Đới', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-nhiet-doi-cata.jpg', N'Thật tuyệt vời khi được sống giữa một khu rừng trong lành. Với mong muốn gần gũi với thiên nhiên thì việc phối những loại cây xanh vùng nhiệt đới sẽ giúp tô điểm thêm cho ngôi nhà của bạn.', CAST(N'2024-11-20T14:49:05.113' AS DateTime), CAST(N'2024-11-20T14:49:05.113' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0014', N'Cây Trồng Ban Công', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-trong-ban-cong.jpg', N'Khu vực ban công tuy không rộng nhưng nó vẫn có thể biến thành một khu vườn của riêng bạn. Thật tuyệt vời khi được thưởng thức một ly trà, ăn miếng bánh và đọc cuốn sách yêu thích, tại khu vườn nhỏ xanh mát này, sau một ngày làm việc mệt mỏi.', CAST(N'2024-11-20T14:49:05.117' AS DateTime), CAST(N'2024-11-20T14:49:05.117' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0015', N'Cây Treo Trong Nhà', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-canh-treo-trong-nha.jpg', N'Treo thêm vài chậu cây cảnh trong nhà là một ý tưởng rất tuyệt vời để bạn phủ xanh không gian sống của mình.', CAST(N'2024-11-20T14:49:05.117' AS DateTime), CAST(N'2024-11-20T14:49:05.117' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0016', N'Cây Thủy Sinh', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-thuy-sinh.jpg', N'Dạng cây thủy sinh vốn được trồng trong nước nên sẽ chẳng cần phải tưới thường xuyên, và nó sẽ giúp bạn tiết kiệm thời gian rất nhiều. Đặt một vài chậu cây cảnh thủy sinh trên bàn làm việc để giúp bạn cải thiện tâm trạng, cũng như giúp thanh lọc không khí rất tốt.', CAST(N'2024-11-20T14:49:05.117' AS DateTime), CAST(N'2024-11-20T14:49:05.117' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0017', N'Cây Cảnh Mini', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-canh-mini-de-ban.jpg', N'Với một vài chậu cây cảnh mini trên bàn làm việc, kệ sách có thể giúp bạn cải thiện cảm xúc, tăng cường tâm trạng rất tốt. Hãy để MOW Garden giúp bạn sở hữu những chậu cây cảnh mini thật chất lượng nhé.', CAST(N'2024-11-20T14:49:05.117' AS DateTime), CAST(N'2024-11-20T14:49:05.117' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0018', N'Cây Có Hoa', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-co-hoa-1.jpg', N'Được ngồi cùng với nhau trò chuyện dưới những tán cây xanh mát, xung quanh là hoa cỏ thơm ngát, có làn gió nhẹ nhàng thoáng qua. Hãy để MOW Garden giúp bạn tạo nên một khu vườn thật tuyệt vời nhé.', CAST(N'2024-11-20T14:49:05.120' AS DateTime), CAST(N'2024-11-20T14:49:05.120' AS DateTime))
GO
INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0019', N'Cây Ngoài Trời', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-ngoai-troi.jpg', N'Được ngồi cùng với nhau trò chuyện dưới những tán cây xanh mát, xung quanh là hoa cỏ thơm ngát, có làn gió nhẹ nhàng thoáng qua. Hãy để chúng tôi giúp bạn tạo nên một khu vườn thật tuyệt vời nhé.', CAST(N'2024-11-20T14:49:05.120' AS DateTime), CAST(N'2024-11-20T14:49:05.120' AS DateTime))
