INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0033', N'Cây Ăn Quả', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-an-trai.jpg', N'Được ngồi cùng với nhau trò chuyện dưới những tán cây xanh mát, xung quanh là hoa cỏ thơm ngát, có làn gió nhẹ nhàng thoáng qua. Hãy để chúng tôi giúp bạn tạo nên một khu vườn thật tuyệt vời nhé.', CAST(N'2024-11-20T14:49:05.133' AS DateTime), CAST(N'2024-11-20T14:49:05.133' AS DateTime))
