INSERT [dbo].[Categories] ([category_id], [name], [background_url], [description], [created_at], [updated_at]) VALUES (N'CCNCAT0034', N'Cây Che Phủ Nền', N'https://mowgarden.com/wp-content/uploads/2021/07/danh-muc-cay-trong-vien.jpg', N'Dạng cây thủy sinh vốn được trồng trong nước nên sẽ chẳng cần phải tưới thường xuyên, và nó sẽ giúp bạn tiết kiệm thời gian rất nhiều. Đặt một vài chậu cây cảnh thủy sinh trên bàn làm việc để giúp bạn cải thiện tâm trạng, cũng như giúp thanh lọc không khí rất tốt.', CAST(N'2024-11-20T14:49:05.133' AS DateTime), CAST(N'2024-11-20T14:49:05.133' AS DateTime))
