INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0000', 1, N'TUBO005', N'Cây tùng bồng lai', N'Cây tùng bồng lai tiểu cảnh chậu sứ thổ cẩm TUBO005', N'Cây Tùng Bông Lai là một loài cây mang vẻ đẹp trang nhã, với tán lá dầy xanh mướt trông giống như những đám mây và có kích thước nhỏ gọn nên rất thích hợp để bàn làm việc. Chúng là loài cây dễ trồng nên không cần phải tốn công chăm sóc, tuy nhiên cần đặt tại nơi có nhiều ánh sáng.
*Giá bao gồm chậu, đĩa lót và sỏi rải mặt', 500000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.657' AS DateTime), CAST(N'2024-11-20T14:49:05.657' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0001', 1, N'CPTK001', N'Phát tài bộ – Thiết Mộc lan', N'Cây phát tài bộ 5 – Cây thiết mộc lan CPTK001', N'Cây phát tài bộ còn được biết đến với tên gọi khác là cây thiết mộc lan. Loài cây nội thất được đánh giá là đem lại nhiều sinh khí, may mắn và thịnh vượng cho gia chủ, nhất là khi cây nở hoa là dấu hiệu tiền tài đang đến với bạn. Hơn nữa, nếu bạn đặt cây theo hướng Đông hay Đông Nam của ngôi nhà thì sẽ đem tới nhiều may mắn bởi cây là đại diện cho hành Mộc.', 750000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.657' AS DateTime), CAST(N'2024-11-20T14:49:05.657' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0002', 1, N'LONI040', N'Cây kim ngân', N'Cây kim ngân ba thân để bàn chậu sứ gấu BearBrick LONI040', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 280000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.660' AS DateTime), CAST(N'2024-11-20T14:49:05.660' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0003', 1, N'PHIG006', N'Trầu bà đế vương xanh', N'Cây trầu bà đế vương xanh chậu mặt cool ‘Imperial Green’ chậu sứ PHIG006', N'Trầu Bà Đế Vương Xanh (Philodendron Imperial Green) là một giống cây rất ưu chuộng để trồng với ý nghĩa phong thủy mà nó mang lại. Nên đặt cây tại các vị trí như trong phòng khách, phòng làm việc, văn phòng hoặc sảnh ra vào cơ quan.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.660' AS DateTime), CAST(N'2024-11-20T14:49:05.660' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0004', 1, N'', N'Cây cỏ lan chi / cây dây nhện', N'Cây cỏ lan chi để bàn chậu sứ mặt cười SPI004', N'Cỏ Lan Chi (hay còn gọi là Cỏ Nhện) là loại cây rất dễ sống với điều kiện khí hậu nóng tại Việt Nam. Đặc biệt, nó nằm trong top các loại cây lọc không khí rất hiệu quả, có thể đặt trong phòng ngủ giúp bạn có giấc ngủ trong lành hơn.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.660' AS DateTime), CAST(N'2024-11-20T14:49:05.660' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0005', 1, N'PHIR008', N'Trầu bà đế vương đỏ', N'Cây trầu bà đế vương đỏ để bàn ‘Red Rojo’ chậu sứ PHIR008', N'Thân dạng thảo lớn, trong tự nhiên cây có thể leo được, nhưng đa số khi trồng chậu thì thân vươn thẳng chắc chắn, cao khoảng dưới 1m5.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.660' AS DateTime), CAST(N'2024-11-20T14:49:05.660' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0006', 1, N'STBS001', N'Cây lưỡi hổ Thái xanh', N'Cây lưỡi hổ Bantel Sensation chậu ươm STBS001', N'Lưỡi hổ Thái xanh mini là dòng lưỡi hổ nhỏ để bàn, có chiều cao tối đa khoảng 20cm, không có nhiều vằn như những loại lưỡi hổ khác, nhưng nó lại sở hữu bộ lá màu xanh đậm ấn tượng, mang lại nét ‘cứng cáp’ tự nhiên cho không gian. Chúng rất thích hợp để trên bàn làm việc, kệ trang trí hoặc làm quà tặng.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.663' AS DateTime), CAST(N'2024-11-20T14:49:05.663' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0007', 1, N'RADE033', N'Cây hạnh phúc', N'Cây hạnh phúc để sàn 2 tầng lớn chậu đá mài RADE033', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa mang lại may mắn và hạnh phúc nên cây thường được chọn để làm cây trưng trong nhà hoặc làm quà tặng.', 1200000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.663' AS DateTime), CAST(N'2024-11-20T14:49:05.663' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0008', 1, N'CTBC007', N'Trầu bà xanh', N'Cây trầu bà cột chậu xi măng trụ vuông CTBC007', N'Có tác dụng thanh lọc không khí trong nhà mà còn chứa đựng ý nghĩa phong thủy rất tốt, mang dáng vẻ thanh lịch và sang trọng.', 1100000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.667' AS DateTime), CAST(N'2024-11-20T14:49:05.667' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0009', 1, N'ANTH010', N'Cây hồng môn', N'Cây hồng môn cỡ nhỏ chậu sứ trắng ANTH010', N'Cây hồng môn được biết tới là một loại cây cảnh mang lại điều tốt lành, có thể giúp điều hòa khí phong thủy trong nhà, có khả năng thu hút những dòng khí tích cực và làm tiêu bớt dòng khí tiêu cực cho môi trường xung quanh, trồng cây hồng môn trong nhà sẽ giúp không gian sống trở nên hài hòa và bình yên hơn.', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.667' AS DateTime), CAST(N'2024-11-20T14:49:05.667' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0010', 1, N'SCHE020', N'Ngũ gia bì cẩm thạch', N'Cây ngũ gia bì cẩm thạch nhỏ chậu ươm SCHE020', N'Ngũ gia bì là loại cây mang lại tài vận, thịnh vượng và may mắn, trồng trong nhà sẽ mang đến một không gian thư thái, trong lành cho gia đình.', 100000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.667' AS DateTime), CAST(N'2024-11-20T14:49:05.667' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0011', 1, N'LONI039', N'Cây kim ngân', N'Cây kim ngân một thân để bàn chậu sứ LONI039', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 480000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.670' AS DateTime), CAST(N'2024-11-20T14:49:05.670' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0012', 1, N'LIVI005', N'Cọ lá xẻ', N'Cây cọ lá xẻ mini để bàn chậu sứ hoa văn LIVI005', N'Cây cọ nhật là loại cây trong nhà có kiểu lá xòe rộng như những cánh quạt, giúp trang trí không gian thêm xanh mát. Nó còn là loại cây phong thủy tượng trưng cho sự giàu sang và tiền tài nên rất đáng trồng trên bàn làm việc.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.670' AS DateTime), CAST(N'2024-11-20T14:49:05.670' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0013', 1, N'RADE032', N'Cây hạnh phúc', N'Cây hạnh phúc để sàn 2 tầng chậu sứ hoa văn RADE032', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa mang lại may mắn và hạnh phúc nên cây thường được chọn để làm cây trưng trong nhà hoặc làm quà tặng.', 900000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.670' AS DateTime), CAST(N'2024-11-20T14:49:05.670' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0014', 1, N'RADE031', N'Cây hạnh phúc', N'Cây hạnh phúc để sàn chậu sứ RADE031', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa mang lại may mắn và hạnh phúc nên cây thường được chọn để làm cây trưng trong nhà hoặc làm quà tặng.', 600000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.670' AS DateTime), CAST(N'2024-11-20T14:49:05.670' AS DateTime))
