INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0016', 1, N'SHBG005', N'Cây lưỡi hổ Thái xanh', N'Cây lưỡi hổ xanh để bàn mini ‘Black Gold’ chậu sứ SHBG005', N'Lưỡi hổ Thái xanh mini là dòng lưỡi hổ nhỏ để bàn, có chiều cao tối đa khoảng 20cm, không có nhiều vằn như những loại lưỡi hổ khác, nhưng nó lại sở hữu bộ lá màu xanh đậm ấn tượng, mang lại nét ‘cứng cáp’ tự nhiên cho không gian. Chúng rất thích hợp để trên bàn làm việc, kệ trang trí hoặc làm quà tặng.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.673' AS DateTime), CAST(N'2024-11-20T14:49:05.673' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0017', 1, N'PEAC005', N'Lan ý', N'Cây Lan ý chậu cỡ lớn để bàn chậu sứ trắng PEAC005', N'Những bông hoa trắng tinh khiết vươn lên đầy kiêu hãnh,phần còn lại phải kể đến vẻ đẹp được tạo từ những chiếc lá xanh tươi, tràn đầy sức sống.', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.673' AS DateTime), CAST(N'2024-11-20T14:49:05.673' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0018', 1, N'AGLA104', N'Cây Phú Quý', N'Cây phú quý chậu sứ thổ cẩm để bàn AGLA104', N'Cây Phú Quý có ý nghĩa mang lại may mắn, phú quý, đại cát đại lợi, bình an cho chủ nhân. Để Trúc Phú Quý mang lại ý nghĩa trọn vẹn bạn lưu ý về vị trí đặt theo hướng hợp với bản mệnh của mình.', 320000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.677' AS DateTime), CAST(N'2024-11-20T14:49:05.677' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0019', 1, N'PHIG005', N'Trầu bà đế vương xanh', N'Cây trầu bà đế vương xanh ‘Imperial Green’ chậu sứ PHIG005', N'Trầu Bà Đế Vương Xanh (Philodendron Imperial Green) là một giống cây rất ưu chuộng để trồng với ý nghĩa phong thủy mà nó mang lại. Nên đặt cây tại các vị trí như trong phòng khách, phòng làm việc, văn phòng hoặc sảnh ra vào cơ quan.', 320000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.677' AS DateTime), CAST(N'2024-11-20T14:49:05.677' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0020', 1, N'AGSN010', N'Cây ngọc ngân', N'Cây ngọc ngân để bàn chậu sứ AGSN010', N'Cây ngọc ngân là là cây trong nhà được đánh giá cao về phong thuỷ, người ta quan niệm rằng cây Ngọc ngân mang đến tài lộc, may mắn khi đặt trên bàn làm việc hay trang trí trong văn phòng. Về mặt tinh thần cây Ngọc ngân rất thích hợp làm quà tặng tình yêu.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.677' AS DateTime), CAST(N'2024-11-20T14:49:05.677' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0021', 1, N'LONI037', N'Cây kim ngân', N'Cây kim ngân 3 thân để bàn chậu marle LONI037', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.680' AS DateTime), CAST(N'2024-11-20T14:49:05.680' AS DateTime))
