INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0022', 1, N'BUBU007', N'Bàng Đài Loan cẩm thạch', N'Cây bàng Đài Loan cẩm thạch chậu sứ BUBU007', N'Cây Bàng Đài Loan Cẩm Thạch có lá nhỏ xinh và sắc xanh, viền trắng hồng rất khác biệt và nổi bật, giúp không gian trở nên độc đáo và sang trọng', 1200000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.680' AS DateTime), CAST(N'2024-11-20T14:49:05.680' AS DateTime))
