INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0024', 1, N'LYRA048', N'Bàng Singapore / Sung tỳ bà', N'Cây bàng Singapore mini để bàn chậu sứ LYRA048', N'Cây Bàng Singapore Lớn có thể dễ dàng nhận ra ở những góc quán cafe, bàn làm việc công. Với những chiếc lá căng bóng hình đàn vĩ cầm rất lớn, nhiều gân là hình chân chim nổi bật.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.683' AS DateTime), CAST(N'2024-11-20T14:49:05.683' AS DateTime))
