INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0026', 1, N'', N'Cây kim tiền / Kim phát tài', N'Cây kim tiền mini để bàn chậu sứ ZAMI033', N'Cây kim tiền có lá hình xương cá màu xanh mướt. Loài này rất dễ sống phát triển mạnh ở những nơi có độ ẩm cao, thường được trồng để trang trí trong phòng khách, làm quà tặng tân gia, khai trương cửa hàng.', 150000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.683' AS DateTime), CAST(N'2024-11-20T14:49:05.683' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0027', 1, N'AGRA005', N'Cây hồng phát lộc', N'Cây vạn lộc son ‘Red Anjamani’ để bàn chậu gốm hoa AGRA005', N'Cô tòng đuôi lươn sở hữu bộ lá nhiều màu sắc rực rỡ, cùng những đường viền hoa văn độc đáo, chúngthường được trồng trang trí cho bồn hoa, ban công hoặc trước hiên nhà. Loại cây này đôi lúc được trồng trong nhà, nhưng đòi hỏi phải trồng nơi có nhiều ánh sáng, gần cửa sổ.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.687' AS DateTime), CAST(N'2024-11-20T14:49:05.687' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0028', 1, N'PEOB006', N'Cây trường sinh', N'Cây trường sinh xanh để bàn chậu sứ PEOB006', N'Cây trường sinh xanh là một loại cây cảnh trong nhà đẹp mắt, với bộ lá luôn xanh mát, sức sống mãnh liệt, dễ chăm sóc. Đây cũng là loại cây phong thủy với tác dụng mang đến sức khỏe, may mắn và tiền tài tới cho gia chủ. Người ta thường hay tặng cây trường sinh vào những dịp đặc biệt như là một lời chúc phúc tới người nhận.', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.687' AS DateTime), CAST(N'2024-11-20T14:49:05.687' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0029', 1, N'PHGO006', N'Cây trầu bà đế vương vàng', N'Cây trầu bà đế vương vàng chậu sứ họa tiết PHGO006', N'Trầu Bà Đế Vương Vàng có tên tiếng Anh là Philodendron Imperial Golden, là dòng cây thân thảo, có sức sống bền bỉ và rất dễ chăm sóc. Loài cây này có phần lá non màu vàng tươi tại trung tâm, khi già đi thì lá chuyển sang màu xanh trong tự nhiên rất bắt mắt. Đây là một loại cây trang trí nội thất rất tuyệt vời, nó giúp không gian sống có thêm điểm nhấn bởi phần lá màu vàng của mình.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.687' AS DateTime), CAST(N'2024-11-20T14:49:05.687' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0030', 1, N'AGRA004', N'Cây hồng phát lộc', N'Cây vạn lộc son ‘Red Anjamani’ để bàn chậu sứ AGRA004', N'Cô tòng đuôi lươn sở hữu bộ lá nhiều màu sắc rực rỡ, cùng những đường viền hoa văn độc đáo, chúngthường được trồng trang trí cho bồn hoa, ban công hoặc trước hiên nhà. Loại cây này đôi lúc được trồng trong nhà, nhưng đòi hỏi phải trồng nơi có nhiều ánh sáng, gần cửa sổ.', 220000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.687' AS DateTime), CAST(N'2024-11-20T14:49:05.687' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0031', 1, N'LONI036', N'Cây kim ngân', N'Cây kim ngân nơ để bàn chậu sứ trắng LONI036', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 150000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.690' AS DateTime), CAST(N'2024-11-20T14:49:05.690' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0032', 1, N'SAFS005', N'Cây lưỡi hổ thái', N'Cây lưỡi hổ Thái để bàn ‘Futura superba’ chậu sứ SAFS005', N'Lưỡi hổ là loại cây cảnh nội thất kinh điển nhất, bởi sức sống bền bỉ không cần tốn công chăm sóc, lại còn được NASA đánh giá là có khả năng thanh lọc không khí rất hiệu quả bằng một cơ chế hấp thu các loại chất khí độc hại trên bộ lá.', 360000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.690' AS DateTime), CAST(N'2024-11-20T14:49:05.690' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0033', 1, N'TBTX009-1', N'Cây trầu bà thanh xuân / Cây trầu bà tay Phật', N'Cây trầu bà thanh xuân chậu sứ họa tiết TBTX010', N'Trầu bà thanh xuân là loại cây trong nhà độc đáo được mọi người ưa thích và trưng bày trang trí. Trầu Bà Thanh Xuân có ý nghĩa về mặt phong thủy nó còn có ý nghĩa may mắn, đem lại tài lộc, gia tăng vận khí, thể hiện ý chí vươn lên của gia chủ.', 950000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.690' AS DateTime), CAST(N'2024-11-20T14:49:05.690' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0034', 1, N'SCHE019', N'Ngũ gia bì', N'Cây ngũ gia bì để bàn chậu sứ thổ cẩm SCHE019', N'Ngũ gia bì là loại cây mang lại tài vận, thịnh vượng và may mắn, trồng trong nhà sẽ mang đến một không gian thư thái, trong lành cho gia đình.', 220000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.690' AS DateTime), CAST(N'2024-11-20T14:49:05.690' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0035', 1, N'CPTN014', N'Phát tài núi', N'Cây phát tài núi 2 tầng dáng thấp chậu đá mài CPTN014', N'Cây phát tài núi rất thường được lựa chọn để làm quà tặng vào những dịp khai trương, lên nhà mới, văn phòng mới… với mong muốn đem lại nhiều tài lộc và may mắn cho người được tặng.', 1650000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.693' AS DateTime), CAST(N'2024-11-20T14:49:05.693' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0036', 1, N'TUBO004', N'Cây tùng bồng lai', N'Cây tùng bồng lai bonsai tiểu cảnh chậu sứ TUBO004', N'Cây Tùng Bông Lai là một loài cây mang vẻ đẹp trang nhã, với tán lá dầy xanh mướt trông giống như những đám mây và có kích thước nhỏ gọn nên rất thích hợp để bàn làm việc. Chúng là loài cây dễ trồng nên không cần phải tốn công chăm sóc, tuy nhiên cần đặt tại nơi có nhiều ánh sáng.', 2200000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.693' AS DateTime), CAST(N'2024-11-20T14:49:05.693' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0037', 1, N'PHIR007', N'Trầu bà đế vương đỏ', N'Cây trầu bà đế vương đỏ ‘Red Rojo’ chậu sứ PHIR007', N'Thân dạng thảo lớn, trong tự nhiên cây có thể leo được, nhưng đa số khi trồng chậu thì thân vươn thẳng chắc chắn, cao khoảng dưới 1m5.', 550000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.693' AS DateTime), CAST(N'2024-11-20T14:49:05.693' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0038', 1, N'LONI035', N'Cây kim ngân', N'Cây kim ngân thắt bính tiểu cảnh chậu đất nung LONI035', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 420000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.697' AS DateTime), CAST(N'2024-11-20T14:49:05.697' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0039', 1, N'HEDE002', N'Cây thường xuân cẩm thạch', N'Cây thường xuân cẩm thạch chậu nhựa HEDE002', N'Thường xuân là loài cây dây leo, chúng có thể sống trong nhà rất tốt và sinh trưởng khỏe mạnh vào mùa mát mẻ. Những cành dài buông rủ của chúng là gợi ý tuyệt vời trên bục cửa sổ, trên kệ sách hoặc treo lên cao. Chúng có sức sống khá bền bỉ nên điều kiện chăm sóc cũng không quá phức tạp.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.697' AS DateTime), CAST(N'2024-11-20T14:49:05.697' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0040', 1, N'PHBI005', N'Cây hồng hạc chân cam', N'Cây hồng hạc thân cam “Billietiae’ chậu banh PHBI005', N'Cây Hạc Cam đặc trưng bởi những chiếc lá thuôn dài, hình dây đeo có xẻ trái tim sâu, phần cuống cũng được tô điểm bởi màu da cam rất bắt mắt. Khi trưởng thành cây hạc Philodendron billietiae có kích thước rất khủng nên được nhiều người săn đón sưu tầm.', 550000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.697' AS DateTime), CAST(N'2024-11-20T14:49:05.697' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0041', 1, N'LYRA047', N'Bàng Singapore / Sung tỳ bà', N'Cây bàng Singapore 2 thân chậu đá mài LYRA047', N'Cây Bàng Singapore Lớn có thể dễ dàng nhận ra ở những góc quán cafe, bàn làm việc công. Với những chiếc lá căng bóng hình đàn vĩ cầm rất lớn, nhiều gân là hình chân chim nổi bật.', 680000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.700' AS DateTime), CAST(N'2024-11-20T14:49:05.700' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0042', 1, N'LYRA046', N'Bàng Singapore / Sung tỳ bà', N'Cây bàng Singapore nhiều thân chậu sứ trắng LYRA046', N'Cây Bàng Singapore Lớn có thể dễ dàng nhận ra ở những góc quán cafe, bàn làm việc công. Với những chiếc lá căng bóng hình đàn vĩ cầm rất lớn, nhiều gân là hình chân chim nổi bật.', 2250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.700' AS DateTime), CAST(N'2024-11-20T14:49:05.700' AS DateTime))
