INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0043', 1, N'BDCT006', N'Đa búp đỏ cẩm thạch', N'Cây đa búp đỏ cẩm thạch 1 thân lớn chậu sứ BDCT006', N'Từ lâu cây Đa luôn là biểu tượng của sự trường tồn, sức sống dẻo dai, nơi chứa đựng thần quyền và tâm linh của con người. Chính lẽ đó mà trong phong thủy, Đa Búp Đỏ cũng mang ý nghĩa của sự may mắn, an lành.', 570000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.700' AS DateTime), CAST(N'2024-11-20T14:49:05.700' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0044', 1, N'SCHE018', N'Ngũ gia bì', N'Cây ngũ gia bì để bàn chậu đất nung SCHE018', N'Ngũ gia bì là loại cây mang lại tài vận, thịnh vượng và may mắn, trồng trong nhà sẽ mang đến một không gian thư thái, trong lành cho gia đình.', 150000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.700' AS DateTime), CAST(N'2024-11-20T14:49:05.700' AS DateTime))
