INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0045', 1, N'DRCO004', N'Trúc mặt trời / Phát tài Nhật', N'Cây trúc mặt trời ‘Compacta’ chậu sứ họa tiết thổ DRCO004', N'Cây phát tài Nhật tượng trưng cho sức sống bền bỉ, mạnh mẽ. Cây có thể thích nghi với mọi điều kiện thời tiết, tán lá vẫn xanh vẫn vươn thêm nhiều tầng mới. Vì thế mà cây mang lại nguồn sinh khí dồi dào, một tinh thần tích cực, cùng niềm vui và sự may mắn cho mọi người.', 200000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.703' AS DateTime), CAST(N'2024-11-20T14:49:05.703' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0046', 1, N'ABDS004', N'Môn vảy rồng', N'Cây môn vảy rồng ‘Dragon Scale’ chậu sứ trắng ABDS004', N'Bạn không cần dành quá nhiều thời gian cho Rồng Bạc nhưng vẫn ngắm nhìn được vẻ đẹp của nó mỗi ngày.', 320000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.703' AS DateTime), CAST(N'2024-11-20T14:49:05.703' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0047', 1, N'PEOB005', N'Cây trường sinh', N'Cây trường sinh để bàn chậu đất nung Marble PEOB005', N'Cây trường sinh (Peperomia obtusifolia) là một loại cây cảnh trong nhà đẹp mắt, với bộ lá luôn xanh mát, sức sống mãnh liệt, dễ chăm sóc. Đây cũng là loại cây phong thủy với tác dụng mang đến sức khỏe, may mắn và tiền tài tới cho gia chủ. Người ta thường hay tặng cây trường sinh vào những dịp đặc biệt như là một lời chúc phúc tới người nhận.', 200000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.703' AS DateTime), CAST(N'2024-11-20T14:49:05.703' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0048', 1, N'LONI034', N'Cây kim ngân', N'Cây kim ngân thắt bính nhỏ để bàn chậu sứ LONI034', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.707' AS DateTime), CAST(N'2024-11-20T14:49:05.707' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0049', 1, N'RADE028', N'Cây hạnh phúc', N'Cây hạnh phúc để sàn chậu sứ RADE028', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa mang lại may mắn và hạnh phúc nên cây thường được chọn để làm cây trưng trong nhà hoặc làm quà tặng.', 560000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.707' AS DateTime), CAST(N'2024-11-20T14:49:05.707' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0050', 1, N'KIGI002', N'Cây kim giao', N'Cây kim giao để bàn chậu sứ trắng KIGI002', N'Kim giao là một cây thân gỗ có giá trị kinh tế lớn. Nhờ có sức sống mạnh mẽ, kiểu dáng đẹp, lá xum xuê và xanh mướt nên chúng cũng được nhân giống để làm cây cảnh để bàn, giúp tạo không gian xanh mát và thư giãn. Đồng thời đây cũng là một loại cây mang ý nghĩa phong thủy rất tốt. Rất thích hợp làm quà tặng.', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.707' AS DateTime), CAST(N'2024-11-20T14:49:05.707' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0051', 1, N'DRDO003-1', N'Cây phát tài xanh', N'Cây phát tài xanh lá lớn ‘Green Jewel’ chậu ươm DRGJ001', N'Phát tài xanh là loại cây trồng trong nhà dễ chăm sóc, với sức sống bền bỉ và khả năng chịu râm mát cực kì tốt. Loại cây này có bộ lá màu xanh đậm, dáng cuộn tròn tỏa ra xung quanh, giúp mang lại màu xanh cho không gian sống. Đồng thời đây là loại cây có khả năng thanh lọc không khí rất hiệu quả.', 560000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.710' AS DateTime), CAST(N'2024-11-20T14:49:05.710' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0052', 1, N'LONI033', N'Cây kim ngân', N'Cây kim ngân ‘Tay Phật’ để bàn chậu sứ LONI033', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.710' AS DateTime), CAST(N'2024-11-20T14:49:05.710' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0053', 1, N'RADE027', N'Cây hạnh phúc', N'Cây hạnh phúc để bàn chậu sứ trụ xanh RADE027', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa mang lại may mắn và hạnh phúc nên cây thường được chọn để làm cây trưng trong nhà hoặc làm quà tặng.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.710' AS DateTime), CAST(N'2024-11-20T14:49:05.710' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0054', 1, N'LONI032', N'Cây kim ngân', N'Cây kim ngân một thân để bàn chậu sứ LONI032', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 270000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.710' AS DateTime), CAST(N'2024-11-20T14:49:05.710' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0055', 1, N'STGF005', N'Cây lưỡi hổ hoàng kim', N'Cây lưỡi hổ Hoàng Kim ‘Gold Flame’ chậu sứ STGF005', N'Lưỡi hổ Gold Flame là dòng “cây cảnh quốc dân” được nhiều người lựa chọn để trồng trang trí trong nhà. Nó không những dễ sống đến mức “gần như bất tử” mà còn giúp mang lại vẻ đẹp tự nhiên, trên lá có những sọc vằn ấn tượng, lá cứng cáp và hình tượng rõ ràng, phù hợp để trồng trong mọi không gian nội thất. Bện cạnh đó, cây lưỡi hổ còn được xem là dòng cây phong thủy mang lại nhiều ý nghĩa cho gia chủ.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.710' AS DateTime), CAST(N'2024-11-20T14:49:05.710' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0056', 1, N'PHIG004', N'Trầu bà đế vương xanh', N'Cây trầu bà đế vương xanh ‘Imperial Green’ chậu sứ PHIG004', N'Trầu Bà Đế Vương Xanh (Philodendron Imperial Green) là một giống cây rất ưu chuộng để trồng với ý nghĩa phong thủy mà nó mang lại. Nên đặt cây tại các vị trí như trong phòng khách, phòng làm việc, văn phòng hoặc sảnh ra vào cơ quan.', 220000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.710' AS DateTime), CAST(N'2024-11-20T14:49:05.710' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0057', 1, N'PHBR006-1', N'Trầu bà đế vương kim cương', N'Cây trầu bà đế vương kim cương ‘Birkin’ chậu sứ PHBR007', N'Đế vương kim cương sở hữu bộ lá xanh khoẻ khoắn, xen kẽ vân sọc trắng hài hoà và đầy cuốn hút. Chắc chắn nó sẽ là điểm nhấm tuyệt vời cho không gian nội thất, bớt đi sự nhàm chán và giúp cải thiện chất lượng không khí hiệu quả.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.713' AS DateTime), CAST(N'2024-11-20T14:49:05.713' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0058', 1, N'DRDO003', N'Cây phát tài viền vàng', N'Cây phát tài viền vàng ‘Dorado’ thủy sinh DRDO003', N'Phát tài viền vàng là loại cây trồng trong nhà dễ chăm sóc, với sức sống bền bỉ và khả năng chịu râm mát cực kì tốt. Loại cây này có bộ lá màu xanh đậm, viền lá màu vàng và dáng cuộn tròn tỏa ra xung quanh, giúp mang lại màu xanh cho không gian sống. Đồng thời đây là loại cây có khả năng thanh lọc không khí rất hiệu quả.', 220000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.713' AS DateTime), CAST(N'2024-11-20T14:49:05.713' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0059', 1, N'LONI031', N'Cây kim ngân', N'Cây kim ngân ‘phát tài phát lộc’ để bàn chậu sứ LONI031', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 340000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.713' AS DateTime), CAST(N'2024-11-20T14:49:05.713' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0060', 1, N'LICU010', N'Cọ Nhật', N'Cây cọ Nhật nhỏ chậu sứ trắng LICU010', N'Cây cọ nhật là loại cây trong nhà có kiểu lá xòe rộng như những cánh quạt, giúp trang trí không gian thêm xanh mát. Nó còn là loại cây phong thủy tượng trưng cho sự giàu sang và tiền tài nên rất đáng trồng trên bàn làm việc.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.713' AS DateTime), CAST(N'2024-11-20T14:49:05.713' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0061', 1, N'LUCK002', N'Cỏ may mắn', N'Cây may mắn hình trái tim chậu sứ LUCK002', N'Cây cỏ may mắn là một loại cây đặc biệt, được ươm từ những hạt thanh long và tạo hình bởi bàn tay khéo léo của người nghệ nhân. Trên những quả cầu màu xanh xanh là hàng vạn cây non được ươm trổ trông rất bắt mắt và độc đáo. Chúng được xem là biểu tượng cho tình yêu, hy vọng và sự may mắn nên thường được lựa chọn để làm quà tặng vào dịp đặc biệt.', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.717' AS DateTime), CAST(N'2024-11-20T14:49:05.717' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0062', 1, N'LUCK001', N'Cỏ may mắn', N'Cây may mắn dáng tree chậu sứ chữ nhật LUCK001', N'Cây cỏ may mắn là một loại cây đặc biệt, được ươm từ những hạt thanh long và tạo hình bởi bàn tay khéo léo của người nghệ nhân. Trên những quả cầu màu xanh xanh là hàng vạn cây non được ươm trổ trông rất bắt mắt và độc đáo. Chúng được xem là biểu tượng cho tình yêu, hy vọng và sự may mắn nên thường được lựa chọn để làm quà tặng vào dịp đặc biệt.', 280000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.717' AS DateTime), CAST(N'2024-11-20T14:49:05.717' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0063', 1, N'CHAM005-2', N'Cau tiểu trâm', N'Cây cau tiểu trâm mini mèo đi học chậu đất nung CHAM006', N'Công việc đòi hỏi bạn phải tiếp xúc hằng ngày với các thiết bị hiện đại có nhiều bức xạ điện tử như máy tính, máy in, điện thoại khiến cho tình trạng sức khỏe bị ảnh hưởng, dẫn đến giảm chất lượng công việc. Hãy thử trồng một cây Cau Tiểu Trâm để bàn với tác dụng tuyệt vời đã được minh chứng.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.720' AS DateTime), CAST(N'2024-11-20T14:49:05.720' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0064', 1, N'LIVI003', N'Cọ lá xẻ / Kè ta', N'Cây cọ lá lẻ mini ‘Livistona’ chậu sứ LIVI003', N'', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.720' AS DateTime), CAST(N'2024-11-20T14:49:05.720' AS DateTime))
