INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0065', 1, N'PHXA004', N'Cây Trầu Bà Chân Vịt', N'Cây trầu bà thiên nga để bàn chậu sứ PHXA004', N'Trầu Bà Chân Vịt có thể còn lạ lẫm với nhiều người, không biết hình dạng của loài cây đó ra sao. Đó là một loài cây có đặc tính sinh trưởng mạnh mẽ, thường được mọi người dùng để tô điểm cho không gian sinh sống, trang trí nội thất.', 420000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.720' AS DateTime), CAST(N'2024-11-20T14:49:05.720' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0066', 1, N'STGH003', N'Cây lưỡi hổ Thái vàng mini', N'Cây lưỡi hổ vàng mini ‘Golden Hahnii’ chậu sứ STGH003', N'Lưỡi hổ Thái vàng “Golden Hahnii” là dòng cây cảnh mini với những chiếc lá nhỏ nhắn có màu vàng sáng sọc xanh đẹp mắt, rất phù hợp để trồng trên bàn làm việc, kệ sách hoặc trang trí tiểu cảnh. Cây lưỡi hổ cũng được trồng với tác dụng phong thủy như là sự may mắn cho gia chủ.', 220000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.720' AS DateTime), CAST(N'2024-11-20T14:49:05.720' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0067', 1, N'ANTH009', N'Cây hồng môn', N'Cây hồng môn cỡ nhỏ chậu đất nung ANTH009', N'Cây hồng môn được biết tới là một loại cây cảnh mang lại điều tốt lành, có thể giúp điều hòa khí phong thủy trong nhà, có khả năng thu hút những dòng khí tích cực và làm tiêu bớt dòng khí tiêu cực cho môi trường xung quanh, trồng cây hồng môn trong nhà sẽ giúp không gian sống trở nên hài hòa và bình yên hơn.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.720' AS DateTime), CAST(N'2024-11-20T14:49:05.720' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0068', 1, N'LONI030', N'Cây kim ngân bính', N'Cây kim ngân để bàn một thân chậu sứ LONI030', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 360000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.723' AS DateTime), CAST(N'2024-11-20T14:49:05.723' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0069', 1, N'PERE004', N'Cây trường sinh cẩm thạch', N'Cây trường sinh viền đỏ chậu sứ hoa văn PERE004', N'Cây trường sinh lá đỏ là một loại cây cảnh trong nhà đẹp mắt, với bộ lá luôn xanh mát, sức sống mãnh liệt, dễ chăm sóc. Đây cũng là loại cây phong thủy với tác dụng mang đến sức khỏe, may mắn và tiền tài tới cho gia chủ. Người ta thường hay tặng cây trường sinh vào những dịp đặc biệt như là một lời chúc phúc tới người nhận.', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.723' AS DateTime), CAST(N'2024-11-20T14:49:05.723' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0070', 1, N'LONI029', N'Cây kim ngân bính', N'Cây kim ngân để bàn một thân chậu sứ LONI029', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 300000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.723' AS DateTime), CAST(N'2024-11-20T14:49:05.723' AS DateTime))
