INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0071', 1, N'PHBR007', N'Trầu bà đế vương kim cương', N'Cây trầu bà đế vương kim cương ‘Birkin’ chậu sứ PHBR007', N'Đế vương kim cương sở hữu bộ lá xanh khoẻ khoắn, xen kẽ vân sọc trắng hài hoà và đầy cuốn hút. Chắc chắn nó sẽ là điểm nhấm tuyệt vời cho không gian nội thất, bớt đi sự nhàm chán và giúp cải thiện chất lượng không khí hiệu quả.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.727' AS DateTime), CAST(N'2024-11-20T14:49:05.727' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0072', 1, N'AGLE004', N'Cây cung điện vàng', N'Cây cung điện vàng ‘Pink Legacy’ chậu sứ AGLE004', N'Cây cung điện sở hữu bộ lá nhiều màu sắc rực rỡ như chốn “hoàng cung”, cùng với đó là những đường viền hoa văn độc đáo như tranh vẽ. Loại cây này rất dễ chăm sóc, thích hợp để trang trí không gian phòng khách, quầy tiếp tân, sảnh ra vào hoặc để bàn làm việc.', 280000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.727' AS DateTime), CAST(N'2024-11-20T14:49:05.727' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0073', 1, N'SHBG004', N'Cây lưỡi hổ Thái xanh', N'Cây lưỡi hổ xanh mini ‘Black Gold’ chậu sứ SHBG004', N'Lưỡi hổ Thái xanh mini là dòng lưỡi hổ nhỏ để bàn, có chiều cao tối đa khoảng 20cm, không có nhiều vằn như những loại lưỡi hổ khác, nhưng nó lại sở hữu bộ lá màu xanh đậm ấn tượng, mang lại nét ‘cứng cáp’ tự nhiên cho không gian. Chúng rất thích hợp để trên bàn làm việc, kệ trang trí hoặc làm quà tặng.', 150000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.730' AS DateTime), CAST(N'2024-11-20T14:49:05.730' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0074', 1, N'BDCT005', N'Đa búp đỏ cẩm thạch', N'Cây đa búp đỏ cẩm thạch 3 thân chậu sứ BDCT005', N'Từ lâu cây Đa luôn là biểu tượng của sự trường tồn, sức sống dẻo dai, nơi chứa đựng thần quyền và tâm linh của con người. Chính lẽ đó mà trong phong thủy, Đa Búp Đỏ cũng mang ý nghĩa của sự may mắn, an lành.', 340000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.730' AS DateTime), CAST(N'2024-11-20T14:49:05.730' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0075', 1, N'SAFS004', N'Cây lưỡi hổ thái', N'Cây lưỡi hổ Thái để bàn ‘Futura superba’ chậu đất nung SAFS004', N'Lưỡi hổ là loại cây cảnh nội thất kinh điển nhất, bởi sức sống bền bỉ không cần tốn công chăm sóc, lại còn được NASA đánh giá là có khả năng thanh lọc không khí rất hiệu quả bằng một cơ chế hấp thu các loại chất khí độc hại trên bộ lá.', 330000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.730' AS DateTime), CAST(N'2024-11-20T14:49:05.730' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0076', 1, N'SALA004', N'Lưỡi hổ vàng', N'Cây lưỡi hổ vàng dài ‘Laurentii’ chậu sứ trắng SALA004', N'Đây sẽ là món quà ý nghĩa để tặng đối tác, bạn bè, người thân vào những dịp đặc biệt như mừng sinh nhật, tân gia, mừng năm mới.', 650000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.733' AS DateTime), CAST(N'2024-11-20T14:49:05.733' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0077', 1, N'CPTN013', N'Phát tài núi', N'Cây phát tài núi 2 tầng chậu đá mài CPTN013', N'Cây phát tài núi rất thường được lựa chọn để làm quà tặng vào những dịp khai trương, lên nhà mới, văn phòng mới… với mong muốn đem lại nhiều tài lộc và may mắn cho người được tặng.', 1900000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.733' AS DateTime), CAST(N'2024-11-20T14:49:05.733' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0078', 1, N'CVNB001', N'Cau vàng Nhật Bản', N'Cây cau vàng Nhật Bản chậu ươm CVNB001', N'Cau vàng Nhật Bản là dòng cau cảnh chịu bóng râm rất tốt, có chiều cao chỉ từ 80~100cm, tán lá gọn gàng nên rất thích hợp để trưng bày trong không gian nội thất. Là một trong những loại cau kiểng được ưu chuộng bởi khả năng mang lại không gian xanh mát, lọc không khí và ý nghĩa tốt trong phong thủy.', 400000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.733' AS DateTime), CAST(N'2024-11-20T14:49:05.733' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0079', 1, N'SPSE004', N'Lan ý Mỹ', N'Cây lan ý Mỹ ‘Sensation’ chậu đất nung SPSE004', N'Khác với Lan Ý thông thường, Lan Ý Mỹ có những chiếc lá lớn hơn và đường gân màu xanh nổi bật. Chúng là loài có sức sống cực kì mãnh liệt, chịu hạn tốt và có thể phát triển khỏe mạnh trong môi trường thiếu sáng. Loài cây to lớn này sẽ giúp tạo điểm nhấn tuyệt vời, và đồng thời mang lại không gian xanh mát cho nội thất rất hiệu quả.', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.737' AS DateTime), CAST(N'2024-11-20T14:49:05.737' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0080', 1, N'PHBR006', N'Trầu bà đế vương kim cương', N'Cây trầu bà đế vương kim cương ‘Birkin’ chậu đất nung PHBR006', N'Đế vương kim cương sở hữu bộ lá xanh khoẻ khoắn, xen kẽ vân sọc trắng hài hoà và đầy cuốn hút. Chắc chắn nó sẽ là điểm nhấm tuyệt vời cho không gian nội thất, bớt đi sự nhàm chán và giúp cải thiện chất lượng không khí hiệu quả.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.737' AS DateTime), CAST(N'2024-11-20T14:49:05.737' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0081', 1, N'FITR006', N'Đa tam phúc', N'Cây đa tam phúc ‘Triangularis’ chậu đất nung FITR006', N'Đây sẽ là một dạng năng lượng tích cực, bạn sẽ cảm nhận được nhiều giá trị như sức khỏe, sự giàu có hay mối quan hệ tốt đẹp đến với cuộc sống của mình.', 300000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.740' AS DateTime), CAST(N'2024-11-20T14:49:05.740' AS DateTime))
GO
