INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0083', 1, N'TBTX009', N'Cây trầu bà thanh xuân / Cây trầu bà tay Phật', N'Cây trầu bà thanh xuân chậu đất nung TBTX009', N'Trầu bà thanh xuân là loại cây trong nhà độc đáo được mọi người ưa thích và trưng bày trang trí. Trầu Bà Thanh Xuân có ý nghĩa về mặt phong thủy nó còn có ý nghĩa may mắn, đem lại tài lộc, gia tăng vận khí, thể hiện ý chí vươn lên của gia chủ.', 950000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.740' AS DateTime), CAST(N'2024-11-20T14:49:05.740' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0084', 1, N'', N'Trầu bà xanh', N'Cây trầu bà cột chậu đá mài trụ vuông CTBC006', N'Có tác dụng thanh lọc không khí trong nhà mà còn chứa đựng ý nghĩa phong thủy rất tốt, mang dáng vẻ thanh lịch và sang trọng.', 1250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.743' AS DateTime), CAST(N'2024-11-20T14:49:05.743' AS DateTime))
