INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0097', 1, N'', N'Cây trường sinh cẩm thạch', N'Cây trường sinh cẩm thạch chậu đất nung hoa cúc PEOB003', N'Cây trường sinh cẩm thạch là một loại cây cảnh trong nhà đẹp mắt, với bộ lá luôn xanh mát, sức sống mãnh liệt, dễ chăm sóc. Đây cũng là loại cây phong thủy với tác dụng mang đến sức khỏe, may mắn và tiền tài tới cho gia chủ. Người ta thường hay tặng cây trường sinh vào những dịp đặc biệt như là một lời chúc phúc tới người nhận.', 280000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.760' AS DateTime), CAST(N'2024-11-20T14:49:05.760' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0098', 1, N'', N'Cây giữ tiền', N'Cây giữ tiền chậu men sứ trắng họa tiết AGWL003', N'Cây giữ tiền là một trong các loại cây dễ chăm sóc mà vẫn luôn xanh tươi quanh năm, nhờ đó mà gia chủ không mất nhiều thời gian chăm sóc. Trong phong thủy, khi đặt Cây Giữ Tiền trong nhà sẽ mang lại ý nghĩa giúp tăng tài lộc, giữ gìn của cải trong nhà.', 280000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.763' AS DateTime), CAST(N'2024-11-20T14:49:05.763' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0099', 1, N'', N'Cây giữ tiền', N'Cây giữ tiền chậu đất nung nâu đậm AGWL003', N'Cây giữ tiền là một trong các loại cây dễ chăm sóc mà vẫn luôn xanh tươi quanh năm, nhờ đó mà gia chủ không mất nhiều thời gian chăm sóc. Trong phong thủy, khi đặt Cây Giữ Tiền trong nhà sẽ mang lại ý nghĩa giúp tăng tài lộc, giữ gìn của cải trong nhà.', 280000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.763' AS DateTime), CAST(N'2024-11-20T14:49:05.763' AS DateTime))
