INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0100', 1, N'', N'Cây giữ tiền', N'Cây giữ tiền chậu đất nung vintage AGWL002', N'Cây giữ tiền là một trong các loại cây dễ chăm sóc mà vẫn luôn xanh tươi quanh năm, nhờ đó mà gia chủ không mất nhiều thời gian chăm sóc. Trong phong thủy, khi đặt Cây Giữ Tiền trong nhà sẽ mang lại ý nghĩa giúp tăng tài lộc, giữ gìn của cải trong nhà.', 320000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.763' AS DateTime), CAST(N'2024-11-20T14:49:05.763' AS DateTime))
