INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0101', 1, N'STGF004', N'Cây lưỡi hổ hoàng kim', N'Cây lưỡi hổ Hoàng Kim ‘Gold Flame’ chậu đất nung STGF004', N'Lưỡi hổ Gold Flame là dòng “cây cảnh quốc dân” được nhiều người lựa chọn để trồng trang trí trong nhà. Nó không những dễ sống đến mức “gần như bất tử” mà còn giúp mang lại vẻ đẹp tự nhiên, trên lá có những sọc vằn ấn tượng, lá cứng cáp và hình tượng rõ ràng, phù hợp để trồng trong mọi không gian nội thất.', 280000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.767' AS DateTime), CAST(N'2024-11-20T14:49:05.767' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0102', 1, N'RADE024', N'Cây hạnh phúc', N'Cây hạnh phúc một thân cao 1m6 chậu đất nung RADE024', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa mang lại may mắn và hạnh phúc nên cây thường được chọn để làm cây trưng trong nhà hoặc làm quà tặng.', 900000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.767' AS DateTime), CAST(N'2024-11-20T14:49:05.767' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0103', 1, N'LONI023', N'Cây kim ngân bính', N'Cây kim ngân thắt bính cao 1m8 chậu sứ trắng LONI023', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 1150000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.770' AS DateTime), CAST(N'2024-11-20T14:49:05.770' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0104', 1, N'LYRA043', N'Bàng Singapore / Sung tỳ bà', N'Cây bàng Singapore dáng tree gốc to chậu xi măng LYRA043', N'Cây Bàng Singapore Lớn có thể dễ dàng nhận ra ở những góc quán cafe, bàn làm việc công. Với những chiếc lá căng bóng hình đàn vĩ cầm rất lớn, nhiều gân là hình chân chim nổi bật.', 1500000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.773' AS DateTime), CAST(N'2024-11-20T14:49:05.773' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0105', 1, N'SCHE017', N'Ngũ gia bì', N'Cây ngũ gia bì để sàn chậu trụ tròn đá mài SCHE017', N'Ngũ gia bì là loại cây mang lại tài vận, thịnh vượng và may mắn, trồng trong nhà sẽ mang đến một không gian thư thái, trong lành cho gia đình.', 750000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.773' AS DateTime), CAST(N'2024-11-20T14:49:05.773' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0106', 1, N'MONS020', N'Trầu bà Nam Mỹ', N'Cây trầu bà Nam Mỹ Monstera ‘Deliciosa’ chậu lớn MONS020', N'Monstera là dòng câycó sức sống mạnh mẽ, dễ chăm sóc, chỉ ánh sáng tán xạ vừa phải, thích với môi trường có ít ánh sáng. Cây trầu bà Nam Mỹ được xem là biểu tượng rất được ưu thích trong lĩnh vực thời trang, kiến trúc và nội thất. Nó thường được đặt cạnh các thương hiệu lớn như một cách để tạo thêm điểm nhấn và phong cách.', 2200000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.777' AS DateTime), CAST(N'2024-11-20T14:49:05.777' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0107', 1, N'', N'Bàng Singapore / Sung tỳ bà', N'Cây bàng Singapore 2 nhánh chậu xi măng để sàn LYRA042', N'Cây Bàng Singapore Lớn có thể dễ dàng nhận ra ở những góc quán cafe, bàn làm việc công. Với những chiếc lá căng bóng hình đàn vĩ cầm rất lớn, nhiều gân là hình chân chim nổi bật.', 450000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.777' AS DateTime), CAST(N'2024-11-20T14:49:05.777' AS DateTime))
