INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0108', 1, N'CANE004', N'Cây đuôi công ‘Network’', N'Cây đuôi công ‘Network’ chậu sứ trắng CANE004', N'Với những vân lá tạo nên hoạ tiết ô lưới ngẫu nhiên độc đáo như một bức tranh mosaic kì công. Calathea Network tạo nên sự khác biệt không thể tìm thấy với bất kỳ loại cây nào.', 270000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.777' AS DateTime), CAST(N'2024-11-20T14:49:05.777' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0109', 1, N'NTMX021', N'Cây Đại phú gia / Trầu bà neon', N'Chậu cây nội thất mix Đại phú gia, Trầu bà Neon NTMX021', N'Chậu cây nội thất được mix các loại cây dễ chăm sóc, thích nghi tốt với điều kiện thiếu sáng trong nhà. Sản phẩm được mix các loại cây Đại phú gia, Trầu bà Neon thích hợp đặt tại phòng khách, lối hành lang, văn phòng, sảnh nhà hàng, khách sạn hoặc làm quà tặng.', 820000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.780' AS DateTime), CAST(N'2024-11-20T14:49:05.780' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0110', 1, N'CASA003', N'Cây đuôi công sọc', N'Cây đuôi công sọc Calathea Sanderiana chậu gốm sứ CASA003', N'Calathea ornata Sanderiana là loài thực vật thân thảo, có lá hình thuôn tròn, sọc trắng xanh. Loài này rất dễ sống, thường được trồng để trang trí trong nhà, thanh lọc không khí và mang ý nghĩa đem lại may mắn, thành công và thịnh vượng.', 230000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.780' AS DateTime), CAST(N'2024-11-20T14:49:05.780' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0111', 1, N'AGPL003', N'Cây hồng phát lộc', N'Cây hồng phát lộc ‘Pink Lady’ chậu sứ trắng AGPL003', N'Cây hồng phát lộc là loại cây nhỏ để bàn, có màu hồng phớt tươi mới và bắt mắt, giúp tạo điểm nhấn cho góc làm việc thêm sinh động. Chúng còn là dòng cây phong thủy, được cho rằng giúp mang lại những điều may mắn và thịnh vượng tới cho gia chủ. Hồng phát lộc cũng là một món quà rất ý nghĩa vào những dịp khai trương, sinh nhật hoặc dịp lễ.', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.783' AS DateTime), CAST(N'2024-11-20T14:49:05.783' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0112', 1, N'', N'Phát tài núi', N'Cây phát tài núi 2 tầng chậu xi măng họa siết sọc CPTN010', N'Cây phát tài núi rất thường được lựa chọn để làm quà tặng vào những dịp khai trương, lên nhà mới, văn phòng mới… với mong muốn đem lại nhiều tài lộc và may mắn cho người được tặng.', 1850000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.783' AS DateTime), CAST(N'2024-11-20T14:49:05.783' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0113', 1, N'ABSD004', N'Rồng bạc', N'Cây rồng bạc ‘Silver Dragon’ chậu sứ trắng ABSD004', N'Bạn không cần dành quá nhiều thời gian cho Rồng Bạc nhưng vẫn ngắm nhìn được vẻ đẹp của nó mỗi ngày.', 340000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.787' AS DateTime), CAST(N'2024-11-20T14:49:05.787' AS DateTime))
