INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0114', 1, N'LONI022', N'Cây kim ngân bính', N'Cây kim ngân một thân để bàn chậu sứ LONI022', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.787' AS DateTime), CAST(N'2024-11-20T14:49:05.787' AS DateTime))
