INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0115', 1, N'PHIR006', N'Trầu bà đế vương đỏ', N'Cây trầu bà đế vương đỏ chậu đất nung PHIR006', N'Thân dạng thảo lớn, trong tự nhiên cây có thể leo được, nhưng đa số khi trồng chậu thì thân vươn thẳng chắc chắn, cao khoảng dưới 1m5.', 300000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.790' AS DateTime), CAST(N'2024-11-20T14:49:05.790' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0116', 1, N'', N'Bàng Đài Loan cẩm thạch', N'Cây bàng Đài Loan cẩm thạch chậu xi măng trụ tròn cao BUBU005', N'Cây Bàng Đài Loan Cẩm Thạch có lá nhỏ xinh và sắc xanh, viền trắng hồng rất khác biệt và nổi bật, giúp không gian trở nên độc đáo và sang trọng', 750000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.790' AS DateTime), CAST(N'2024-11-20T14:49:05.790' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0117', 1, N'PHBR005', N'Trầu bà đế vương kim cương', N'Cây trầu bà đế vương kim cương ‘Birkin’ chậu đất nung PHBR005', N'Đế vương kim cương sở hữu bộ lá xanh khoẻ khoắn, xen kẽ vân sọc trắng hài hoà và đầy cuốn hút. Chắc chắn nó sẽ là điểm nhấm tuyệt vời cho không gian nội thất, bớt đi sự nhàm chán và giúp cải thiện chất lượng không khí hiệu quả.', 420000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.790' AS DateTime), CAST(N'2024-11-20T14:49:05.790' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0118', 1, N'HCMX002', N'Hoa cúc mâm xôi', N'Chậu hoa cúc mâm xôi trang trí xọt nhựa HCMX002', N'Cúc mâm xôi là một trong các loài hoa không thể thiếu vào dịp Tết cổ truyền. Chậu cúc mâm xôi có hình dáng tỏa ra theo dạng hình cầu, mang ý nghĩa vẹn tròn, cho một năm mới xuôn sẻ. Với màu vàng được xem là màu của sung túc, đầm ấm và nhiều tài lộc hơn. Do đó, người ta thường tặng cả cặp làm quà tặng cho ông bà, cha mẹ hoặc quý đối tác.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.793' AS DateTime), CAST(N'2024-11-20T14:49:05.793' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0119', 1, N'CDPG006', N'Đại phú gia', N'Cây đại phú gia chậu xi măng đá mài CDPG006', N'Cây đại phú gia để bàn thuộc họ cây ráy, có tên khoa học là Aglaoocma SP. Loài cây này mọc phân bổ chủ yếu ở các nước có khí hậu nhiệt đới, ưa ẩm và bóng râm có nguồn gốc từ châu Mỹ.', 840000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.793' AS DateTime), CAST(N'2024-11-20T14:49:05.793' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0120', 1, N'BDCT004', N'Đa búp đỏ cẩm thạch', N'Cây đa búp đỏ cẩm thạch một thân chậu sứ BDCT004', N'Từ lâu cây Đa luôn là biểu tượng của sự trường tồn, sức sống dẻo dai, nơi chứa đựng thần quyền và tâm linh của con người. Chính lẽ đó mà trong phong thủy, Đa Búp Đỏ cũng mang ý nghĩa của sự may mắn, an lành.', 300000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.797' AS DateTime), CAST(N'2024-11-20T14:49:05.797' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0121', 1, N'AGRA003', N'Cây hồng phát lộc', N'Cây vạn lộc son ‘Red Anjamani’ để bàn chậu sứ AGRA003', N'Cô tòng đuôi lươn sở hữu bộ lá nhiều màu sắc rực rỡ, cùng những đường viền hoa văn độc đáo, chúngthường được trồng trang trí cho bồn hoa, ban công hoặc trước hiên nhà. Loại cây này đôi lúc được trồng trong nhà, nhưng đòi hỏi phải trồng nơi có nhiều ánh sáng, gần cửa sổ.', 320000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.797' AS DateTime), CAST(N'2024-11-20T14:49:05.797' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0122', 1, N'TUBO003', N'Cây tùng bồng lai', N'Cây tùng bồng lai cặp đôi tình yêu chậu sứ TUBO003', N'Cây Tùng Bông Lai là một loài cây mang vẻ đẹp trang nhã, với tán lá dầy xanh mướt trông giống như những đám mây và có kích thước nhỏ gọn nên rất thích hợp để bàn làm việc. Chúng là loài cây dễ trồng nên không cần phải tốn công chăm sóc, tuy nhiên cần đặt tại nơi có nhiều ánh sáng.', 320000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.797' AS DateTime), CAST(N'2024-11-20T14:49:05.797' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0123', 1, N'', N'Cây tùng bồng lai', N'Cây Tùng bồng lai chậu đất nung wax hoa cúc TUBO002', N'Cây Tùng Bông Lai là một loài cây mang vẻ đẹp trang nhã, với tán lá dầy xanh mướt trông giống như những đám mây và có kích thước nhỏ gọn nên rất thích hợp để bàn làm việc. Chúng là loài cây dễ trồng nên không cần phải tốn công chăm sóc, tuy nhiên cần đặt tại nơi có nhiều ánh sáng.', 320000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.800' AS DateTime), CAST(N'2024-11-20T14:49:05.800' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0124', 1, N'', N'Cây hạnh phúc', N'Cây hạnh phúc chậu đất nung hoàng gia RADE023', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa mang lại may mắn và hạnh phúc nên cây thường được chọn để làm cây trưng trong nhà hoặc làm quà tặng.', 750000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.800' AS DateTime), CAST(N'2024-11-20T14:49:05.800' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0125', 1, N'', N'Cây cỏ lan chi / cây dây nhện', N'Cây cỏ lan chi để bàn chậu men bóng họa tiết SPI003', N'Cỏ Lan Chi (hay còn gọi là Cỏ Nhện) là loại cây rất dễ sống với điều kiện khí hậu nóng tại Việt Nam. Đặc biệt, nó nằm trong top các loại cây lọc không khí rất hiệu quả, có thể đặt trong phòng ngủ giúp bạn có giấc ngủ trong lành hơn.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.800' AS DateTime), CAST(N'2024-11-20T14:49:05.800' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0126', 1, N'LYRA041', N'Cây bàng Singapore', N'Cây bàng Singapore một thân chậu đất nung LYRA041', N'Cây Bàng Singapore là loại cây nội thất đang được ưa chuộng nhất hiện nay. Cây có khả năng cải thiện chất lượng không khí. Mang lại sự xanh mát và sang trọng cho không gian của bạn, trang trí phòng khách, văn phòng, quán cafe hay shop.Hoặc làm quà tặng dịp khai trương, tân gia…', 340000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.803' AS DateTime), CAST(N'2024-11-20T14:49:05.803' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0127', 1, N'', N'Cây Trầu Bà Chân Vịt', N'Cây Trầu Bà Chân Vịt chậu sứ trắng có vân Philodendron Xanadu CTBCV002', N'Khi nói đến Trầu Bà Chân Vịt thì có thể nhiều người sẽ cảm thấy lạ lẫm kèm theo đó là tò mò không biết hình dạng của loài cây đó ra sao. Đó là một loài cây có đặc tính sinh trưởng mạnh mẽ, thường được mọi người dùng để tô điểm cho không gian sinh sống, trang trí nội thất.', 750000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.803' AS DateTime), CAST(N'2024-11-20T14:49:05.803' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0128', 1, N'ZAMI031', N'Cây kim tiền / Kim phát tài', N'Cây kim tiền trưng tết chậu đất nung hoa cúc ZAMI031', N'Cây kim tiền có lá hình xương cá màu xanh mướt. Loài này rất dễ sống phát triển mạnh ở những nơi có độ ẩm cao, thường được trồng để trang trí trong phòng khách, làm quà tặng tân gia, khai trương cửa hàng.', 420000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.807' AS DateTime), CAST(N'2024-11-20T14:49:05.807' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0129', 1, N'', N'Cây ngọc ngân', N'Cây ngọc ngân Thái chậu gốm họa tiết cầu vồng AGSN009', N'Cây ngọc ngân là là cây trong nhà được đánh giá cao về phong thuỷ, người ta quan niệm rằng cây Ngọc ngân mang đến tài lộc, may mắn khi đặt trên bàn làm việc hay trang trí trong văn phòng. Về mặt tinh thần cây Ngọc ngân rất thích hợp làm quà tặng tình yêu.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.807' AS DateTime), CAST(N'2024-11-20T14:49:05.807' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0130', 1, N'', N'Cây kim ngân bính', N'Cây kim ngân bính để bàn chậu sứ có hình LONI021', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.807' AS DateTime), CAST(N'2024-11-20T14:49:05.807' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0131', 1, N'RADE026', N'Cây hạnh phúc', N'Cây hạnh phúc bonsai để bàn chậu sứ RADE026', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa mang lại may mắn và hạnh phúc nên cây thường được chọn để làm cây trưng trong nhà hoặc làm quà tặng.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.810' AS DateTime), CAST(N'2024-11-20T14:49:05.810' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0132', 1, N'ANTH008', N'Cây hồng môn', N'Cây hồng môn tiểu cảnh thỏ trắng ôm túi may mắn ANTH008', N'Cây hồng môn được biết tới là một loại cây cảnh mang lại điều tốt lành, có thể giúp điều hòa khí phong thủy trong nhà, có khả năng thu hút những dòng khí tích cực và làm tiêu bớt dòng khí tiêu cực cho môi trường xung quanh, trồng cây hồng môn trong nhà sẽ giúp không gian sống trở nên hài hòa và bình yên hơn.', 450000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.810' AS DateTime), CAST(N'2024-11-20T14:49:05.810' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0133', 1, N'HCMX001', N'Hoa cúc mâm xôi', N'Chậu hoa cúc mâm xôi trưng Tết cỡ lớn trang trí xọt tre HCMX001', N'Cúc mâm xôi là một trong các loài hoa không thể thiếu vào dịp Tết cổ truyền. Chậu cúc mâm xôi có hình dáng tỏa ra theo dạng hình cầu, mang ý nghĩa vẹn tròn, cho một năm mới xuôn sẻ. Với màu vàng được xem là màu của sung túc, đầm ấm và nhiều tài lộc hơn. Do đó, người ta thường tặng cả cặp làm quà tặng cho ông bà, cha mẹ hoặc quý đối tác.', 380000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.810' AS DateTime), CAST(N'2024-11-20T14:49:05.810' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0134', 1, N'CTBH008', N'Trúc bách hợp', N'Cây trúc bách hợp một thân chậu xi măng CTBH008', N'Còn được gọi là trúc phất dụ, mọc thành bụi sum sê, ở chính giữa tạo thành hình hoa thị và tua tủa ra xung quanh. Cây có thân cứng, lá thuôn nhọn ở đầu, mép nguyên, màu xanh bóng xen lần dải màu vàng tươi từ gốc tới ngọn', 950000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.810' AS DateTime), CAST(N'2024-11-20T14:49:05.810' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0135', 1, N'LONI020', N'Cây kim ngân', N'Cây kim ngân thắt bính chậu đất nung LONI020', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 990000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.813' AS DateTime), CAST(N'2024-11-20T14:49:05.813' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0136', 1, N'ANTH007', N'Cây hồng môn', N'Cây hồng môn cỡ lớn chậu gốm sứ ANTH007', N'Cây hồng môn được biết tới là một loại cây cảnh mang lại điều tốt lành, có thể giúp điều hòa khí phong thủy trong nhà, có khả năng thu hút những dòng khí tích cực và làm tiêu bớt dòng khí tiêu cực cho môi trường xung quanh, trồng cây hồng môn trong nhà sẽ giúp không gian sống trở nên hài hòa và bình yên hơn.', 520000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.813' AS DateTime), CAST(N'2024-11-20T14:49:05.813' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0137', 1, N'LONI019', N'Cây kim ngân', N'Cây kim ngân 3 thân để bàn chậu đất nung LONI019', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 230000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.813' AS DateTime), CAST(N'2024-11-20T14:49:05.813' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0138', 1, N'MOAD003', N'Cây trầu bà lỗ', N'Cây trầu bà lỗ Monstera ‘Adansonii’ chậu gốm sứ MOAD003', N'Trầu bà lỗ có tên khoa học là, Monstera adansonii, hay còn được gọi là Swiss Cheese Vine, với bộ lá xanh mát hình chóp và dễ sống trong nhà nên loại cây này rất được ưu chuộng. Mỗi chiếc lá có đầy những lỗ hình bầu dục tự nhiên trông rất lạ mắt giúp nó khó nhầm lẫn với các loại cây khác.', 220000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.817' AS DateTime), CAST(N'2024-11-20T14:49:05.817' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0139', 1, N'AGSU003', N'Cây bao thanh thiên', N'Cây bao thanh thiên ‘Aglaonema Sumatra’ chậu đất nung AGSU003', N'Cây bao thanh thiên có bộ lá sặc sỡ và khỏe khoắn nên rất thích hợp để trang hoàng thêm điểm nhấn cho không gian sống. Loại cây này còn được xe là tượng trưng cho sự ngay thẳng, chính trực trong phong thủy. Khi trồng sẽ giúp thu hút năng lượng tích cực, xua đuổi cái xấu.', 380000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.817' AS DateTime), CAST(N'2024-11-20T14:49:05.817' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0140', 1, N'NTMX020', N'Cây cọ Nhật/ Thịnh vượng / Cung điện / Trầu bà', N'Chậu cây nội thất mix Cọ nhật, Thịnh vượng, Cung điện, Trầu bà NTMX020', N'Chậu cây nội thất được mix các loại cây dễ chăm sóc, thích nghi tốt với điều kiện thiếu sáng trong nhà. Sản phẩm được mix các loại cây Cọ Nhật, Cung điện, Thịnh vượng, Trầu bà thích hợp đặt tại phòng khách, lối hành lang, văn phòng, sảnh nhà hàng, khách sạn hoặc làm quà tặng.', 1200000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.820' AS DateTime), CAST(N'2024-11-20T14:49:05.820' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0141', 1, N'RADE021', N'Cây hạnh phúc', N'Cây hạnh phúc một thân nhỏ đất nung RADE021', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa mang lại may mắn và hạnh phúc nên cây thường được chọn để làm cây trưng trong nhà hoặc làm quà tặng.', 650000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.820' AS DateTime), CAST(N'2024-11-20T14:49:05.820' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0142', 1, N'NTMX019', N'Cây đại lộc / vạn lộc / ngọc ngân / đô la', N'Chậu cây cảnh mix đại lộc, vạn lộc, ngọc ngân, đô la NTMX019', N'Chậu cây nội thất được mix các loại cây dễ chăm sóc, thích nghi tốt với điều kiện thiếu sáng trong nhà. Sản phẩm được mix các loại cây Đại lộc, Vạn lộc, Ngọc ngân, Đô la thích hợp đặt tại phòng khách, lối hành lang, văn phòng, sảnh nhà hàng, khách sạn hoặc làm quà tặng.', 6250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.820' AS DateTime), CAST(N'2024-11-20T14:49:05.820' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0143', 1, N'RADE025', N'Cây hạnh phúc', N'Cây hạnh phúc một thân cao 150cm chậu đá mài RADE025', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa mang lại may mắn và hạnh phúc nên cây thường được chọn để làm cây trưng trong nhà hoặc làm quà tặng.', 990000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.823' AS DateTime), CAST(N'2024-11-20T14:49:05.823' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0144', 1, N'TBTX008', N'Cây trầu bà thanh xuân / Cây trầu bà tay Phật', N'Cây trầu bà thanh xuân cỡ lớn chậu đá mài TBTX008', N'Trầu bà thanh xuân là loại cây trong nhà độc đáo được mọi người ưa thích và trưng bày trang trí. Trầu Bà Thanh Xuân có ý nghĩa về mặt phong thủy nó còn có ý nghĩa may mắn, đem lại tài lộc, gia tăng vận khí, thể hiện ý chí vươn lên của gia chủ.', 1200000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.823' AS DateTime), CAST(N'2024-11-20T14:49:05.823' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0145', 1, N'AGSN008', N'Cây ngọc ngân', N'Cây ngọc ngân ‘Snow White’ chậu đất nung AGSN008', N'Cây ngọc ngân là là cây trong nhà được đánh giá cao về phong thuỷ, người ta quan niệm rằng cây Ngọc ngân mang đến tài lộc, may mắn khi đặt trên bàn làm việc hay trang trí trong văn phòng. Về mặt tinh thần cây Ngọc ngân rất thích hợp làm quà tặng tình yêu.', 175000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.823' AS DateTime), CAST(N'2024-11-20T14:49:05.823' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0146', 1, N'NTMX018', N'Cây hạnh phúc / vạn lộc / trúc Nhật / tróc bạc', N'Chậu cây nội thất mix hạnh phúc, vạn lộc, trúc Nhật, tróc bạc NTMX018', N'Chậu cây nội thất được mix các loại cây dễ chăm sóc, thích nghi tốt với điều kiện thiếu sáng trong nhà. Sản phẩm được mix các loại cây Hạnh Phúc, Vạn lộc, Trúc Nhật, Tróc bạc thích hợp thể đặt tại phòng khách, lối hành lang, văn phòng làm việc, sảnh nhà hàng, khách sạn hoặc làm quà tặng.', 1250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.827' AS DateTime), CAST(N'2024-11-20T14:49:05.827' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0147', 1, N'MONS106', N'Trầu bà Nam Mỹ', N'Cây trầu bà Nam Mỹ Monstera ‘Borsigiana’ chậu sứ MONS106', N'Monstera là dòng câycó sức sống mạnh mẽ, dễ chăm sóc, chỉ ánh sáng tán xạ vừa phải, thích với môi trường có ít ánh sáng. Cây trầu bà Nam Mỹ được xem là biểu tượng rất được ưu thích trong lĩnh vực thời trang, kiến trúc và nội thất. Nó thường được đặt cạnh các thương hiệu lớn như một cách để tạo thêm điểm nhấn và phong cách.', 750000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.827' AS DateTime), CAST(N'2024-11-20T14:49:05.827' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0148', 1, N'RADE020', N'Cây hạnh phúc', N'Cây hạnh phúc một thân cỡ trung chậu ươm RADE020', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa mang lại may mắn và hạnh phúc nên cây thường được chọn để làm cây trưng trong nhà hoặc làm quà tặng.', 450000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.827' AS DateTime), CAST(N'2024-11-20T14:49:05.827' AS DateTime))
