INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0150', 1, N'LONI018', N'Cây kim ngân', N'Cây kim ngân 3 thân để bàn chậu đỏ phát tài LONI018', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 280000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.830' AS DateTime), CAST(N'2024-11-20T14:49:05.830' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0151', 1, N'ZAMI029', N'Cây kim tiền / Kim phát tài', N'Cây kim tiền để sàn chậu men sứ ZAMI029', N'Cây kim tiền có lá hình xương cá màu xanh mướt. Loài này rất dễ sống phát triển mạnh ở những nơi có độ ẩm cao, thường được trồng để trang trí trong phòng khách, làm quà tặng tân gia, khai trương cửa hàng.', 420000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.830' AS DateTime), CAST(N'2024-11-20T14:49:05.830' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0152', 1, N'EAMQ001', N'Trầu bà lá sữa', N'Cây trầu bà lá sữa ‘Marble Queen’ EAMQ001', N'Nhiều bạn nhầm lẫn loại này với trầu bà sữa nhưng Epipremnum Marble Queen là loại trầu bà đặc biệt với form lá ú tròn hơn gần giống như hình trái tim nhìn rất lạ mắt.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.833' AS DateTime), CAST(N'2024-11-20T14:49:05.833' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0153', 1, N'NTMX016', N'Cây hạnh phúc / vạn lộc / ngọc ngân / thường xuân', N'Chậu cây nội thất mix hạnh phúc, vạn lộc, ngọc ngân, thường xuân NTMX016', N'Chậu cây nội thất được mix các loại cây dễ chăm sóc, thích nghi tốt với điều kiện thiếu sáng trong nhà. Sản phẩm được mix các loại cây Hạnh Phúc, Vạn lộc, Ngọc ngân, Thường Xuân thích hợp thể đặt tại phòng khách, lối hành lang, văn phòng làm việc, sảnh nhà hàng, khách sạn hoặc làm quà tặng.', 1250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.833' AS DateTime), CAST(N'2024-11-20T14:49:05.833' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0154', 1, N'LIVI004', N'Cọ lá xẻ', N'Cây cọ lá xẻ mini để bàn chậu đất nung LIVI004', N'Cây cọ nhật là loại cây trong nhà có kiểu lá xòe rộng như những cánh quạt, giúp trang trí không gian thêm xanh mát. Nó còn là loại cây phong thủy tượng trưng cho sự giàu sang và tiền tài nên rất đáng trồng trên bàn làm việc.', 85000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.833' AS DateTime), CAST(N'2024-11-20T14:49:05.833' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0155', 1, N'MONS002', N'Trầu bà Nam Mỹ', N'Cây trầu bà Nam Mỹ Monstera chậu ươm MONS002', N'Cây trầu bà Nam Mỹ được xem là một loài cây kiểng lá “quốc dân”, được ưu chuộng khắp nơi trên thế giới. Nhờ sở hữu một bộ lá ấn tượng, trang nhã và sang trong mà chúng luôn trở thành tâm điểm điểm của những hình ảnh đại diện cho các nhãn hàng, thương hiệu cho tới cá nhân trên các trang mạng xã hội.', 450000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.837' AS DateTime), CAST(N'2024-11-20T14:49:05.837' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0156', 1, N'AGIG002', N'Cây tiểu bạch mã hoàng tử', N'Cây tiểu bạch mã hoàng tử ‘Ivy Green’ chậu ươm AGIG002', N'Cô tòng đuôi lươn sở hữu bộ lá nhiều màu sắc rực rỡ, cùng những đường viền hoa văn độc đáo, chúngthường được trồng trang trí cho bồn hoa, ban công hoặc trước hiên nhà. Loại cây này đôi lúc được trồng trong nhà, nhưng đòi hỏi phải trồng nơi có nhiều ánh sáng, gần cửa sổ.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.837' AS DateTime), CAST(N'2024-11-20T14:49:05.837' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0157', 1, N'AGWL001', N'Cây giữ tiền', N'Cây giữ tiền ‘White Lance’ chậu ươm AGWL001', N'Cây giữ tiền là một trong các loại cây dễ chăm sóc mà vẫn luôn xanh tươi quanh năm, nhờ đó mà gia chủ không mất nhiều thời gian chăm sóc. Trong phong thủy, khi đặt Cây Giữ Tiền trong nhà sẽ mang lại ý nghĩa giúp tăng tài lộc, giữ gìn của cải trong nhà.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.837' AS DateTime), CAST(N'2024-11-20T14:49:05.837' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0158', 1, N'NTMX015', N'Cây đại phú gia / Vạn lộc / Ngọc ngân / May mắn', N'Chậu cây nội thất mix đại phú gia, vạn lộc, ngọc ngân, may mắn NTMX015', N'Chậu cây nội thất được mix các loại cây dễ chăm sóc, thích nghi tốt với điều kiện thiếu sáng trong nhà. Sản phẩm được mix các loại cây Đại Phú Gia, Vạn lộc, Ngọc ngân, May Mắn thích hợp thể đặt tại phòng khách, lối hành lang, văn phòng làm việc, sảnh nhà hàng, khách sạn hoặc làm quà tặng.', 1250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.840' AS DateTime), CAST(N'2024-11-20T14:49:05.840' AS DateTime))
