INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0159', 1, N'MONS105', N'Trầu bà Nam Mỹ', N'Cây trầu bà Nam Mỹ Monstera ‘Borsigiana’ chậu sứ MONS105', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa mang lại may mắn và hạnh phúc nên cây thường được chọn để làm cây trưng trong nhà hoặc làm quà tặng.', 750000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.840' AS DateTime), CAST(N'2024-11-20T14:49:05.840' AS DateTime))
