INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0161', 1, N'NTMX014', N'Cây lưỡi hổ / Vạn lộc / Ngọc ngân / Phú quý', N'Chậu cây nội thất mix lưỡi hổ, vạn lộc, ngọc ngân, trầu bà NTMX014', N'Chậu cây nội thất được mix các loại cây dễ chăm sóc, thích nghi tốt với điều kiện thiếu sáng trong nhà. Sản phẩm được mix các loại cây Lưỡi hổ, Vạn lộc, Ngọc ngân, May Mắn thích hợp thể đặt tại phòng khách, lối hành lang, văn phòng làm việc, sảnh nhà hàng, khách sạn hoặc làm quà tặng.', 1050000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.843' AS DateTime), CAST(N'2024-11-20T14:49:05.843' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0162', 1, N'NTMX011', N'Cây đại phú gia / Đô la / May mắn', N'Chậu cây nội thất mix đại phú gia, đô la, may mắn NTMX011', N'Chậu cây nội thất được mix các loại cây dễ chăm sóc, thích nghi tốt với điều kiện thiếu sáng trong nhà. Sản phẩm được mix các loại cây Đại Phú Gia, Đô La, May Mắn thích hợp thể đặt tại phòng khách, lối hành lang, văn phòng làm việc, sảnh nhà hàng, khách sạn hoặc làm quà tặng.', 1400000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.843' AS DateTime), CAST(N'2024-11-20T14:49:05.843' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0163', 1, N'ELAS005', N'Đa búp đỏ', N'Cây đa búp đỏ chậu đất nung ELAS005', N'Đa Búp Đỏ là loại cây có sức sống mãnh liệt, nó tượng trưng sự vươn lên mạnh mẽ, trường tồn và hạnh phúc. Không chỉ mang lại điểm nhấn xanh cho không gian sống, Đa Búp Đỏ còn còn mang lại ý nghĩa rất tốt trong phong thủy, giúp gia đình hòa thuận, mọi việc thuận lợi.', 440000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.843' AS DateTime), CAST(N'2024-11-20T14:49:05.843' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0164', 1, N'HELI001', N'Cây chuối mỏ két đỏ / Thiên điểu cẩm thạch', N'Cây chuối mỏ két cẩm thạch chậu ươm HELI001', N'Chuối mỏ két cẩm thạch là loài cây nhiệt đới có hoa và bộ lá tươi sáng, thích hợp trồng trang trí sân vườn, ban công hoặc sân thượng. Loài cây này có đặc điểm sống trong râm mát nên cũng có thể đặt trang trí trong nhà rất đẹp mắt.', 110000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.843' AS DateTime), CAST(N'2024-11-20T14:49:05.843' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0165', 1, N'LYRA040', N'Cây bàng Singapore', N'Cây bàng Singapore chậu xi măng đá mài LYRA040', N'Cây Bàng Singapore là loại cây nội thất đang được ưa chuộng nhất hiện nay. Cây có khả năng cải thiện chất lượng không khí. Mang lại sự xanh mát và sang trọng cho không gian của bạn, trang trí phòng khách, văn phòng, quán cafe hay shop.Hoặc làm quà tặng dịp khai trương, tân gia…', 370000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.847' AS DateTime), CAST(N'2024-11-20T14:49:05.847' AS DateTime))
GO
