INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0167', 1, N'ANTH006', N'Cây hồng môn', N'Cây hồng môn để bàn chậu gốm in “Tài Lộc” ANTH006', N'Cây hồng môn được biết tới là một loại cây cảnh mang lại điều tốt lành, có thể giúp điều hòa khí phong thủy trong nhà, có khả năng thu hút những dòng khí tích cực và làm tiêu bớt dòng khí tiêu cực cho môi trường xung quanh, trồng cây hồng môn trong nhà sẽ giúp không gian sống trở nên hài hòa và bình yên hơn.', 370000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.850' AS DateTime), CAST(N'2024-11-20T14:49:05.850' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0168', 1, N'SAZE002', N'Lưỡi hổ xanh', N'Cây lưỡi hổ xanh ‘Zeylanica’ chậu xi măng đá mài SAZE002', N'Lưỡi hổ có lẽ là loại cây nội thất quen thuộc nhất đối với những người yêu cây cảnh. Loài cây này có khả năng chịu nóng, chịu hạn tốt, sống được trong bóng râm và đặc biệt nó có khả năng lọc không khí rất tuyệt vời.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.850' AS DateTime), CAST(N'2024-11-20T14:49:05.850' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0169', 1, N'BUBU006', N'Bàng Đài Loan cẩm thạch', N'Cây bàng đài loan cẩm thạch chậu đất nung BUBU006', N'Bàng Đài Loan cẩm thạch có lá nhỏ xinh và sắc xanh, viền trắng hồng rất khác biệt và nổi bật, giúp không gian trở nên độc đáo và sang trọng', 750000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.850' AS DateTime), CAST(N'2024-11-20T14:49:05.850' AS DateTime))
