INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0170', 1, N'PNIX010', N'Cây cau nga mi / Chà là cảnh', N'Cây cau nga mi cao 150-160cm chậu xi măng trắng PNIX010', N'Cau Nga Mi là một loại cây cảnh nội thất có kích thước tương đối lớn, nhưng không quá chiếm diện tích, mang một vẻ đẹp tự nhiên giúp tạo cảm giác thư thái và thoải mái. Với bộ lá xum xuê, xanh mát và dạng rũ giúp tạo cho không gian nội thất thêm phần sang trọng, duyên dáng và vô cùng ấn tượng.', 1850000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.853' AS DateTime), CAST(N'2024-11-20T14:49:05.853' AS DateTime))
