INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0171', 1, N'CHRY009', N'Cau vàng Nhật Bản', N'Cây cau vàng Nhật Bản cỡ trung chậu đá mài CHRY009', N'Cây cau Nhật có tác dụng hút khí độc, làm sạch không khí trong nhà và môi trường xung quanh. Cây hấp thu chất ô nhiễm vào lá và chuyển các độc tố xuống rễ.', 740000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.853' AS DateTime), CAST(N'2024-11-20T14:49:05.853' AS DateTime))
