INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0180', 1, N'SPAV004', N'Tróc bạc Albo', N'Cây tróc bạc ‘Albo Variegata’ chậu gốm sứ SPAV004', N'Tróc bạc Albo là loại cây có thể phát triển tốt ngay cả trong điều kiện thiếu sáng, do đó bạn sẽ không phải quá lo lắng khi trồng chúng trong nhà. Loài cây này cũng có sức sống rất khỏe mạnh, phát triển nhanh và ít cần phải chăm sóc. Cây phát triển theo dạng dây leo, hình dáng lá như mũi tên nên có tên gọi “Arrowhead Plant” trong tiếng Anh.', 360000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.863' AS DateTime), CAST(N'2024-11-20T14:49:05.863' AS DateTime))
