INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0181', 1, N'LYRA038', N'Cây bàng Singapore', N'Cây bàng Singapore hai nhánh nhỏ chậu đất nung LYRA038', N'Cây Bàng Singapore là loại cây nội thất đang được ưa chuộng nhất hiện nay. Cây có khả năng cải thiện chất lượng không khí. Mang lại sự xanh mát và sang trọng cho không gian của bạn, trang trí phòng khách, văn phòng, quán cafe hay shop.Hoặc làm quà tặng dịp khai trương, tân gia…', 280000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.867' AS DateTime), CAST(N'2024-11-20T14:49:05.867' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0182', 1, N'SPNR004', N'Tróc bạc hồng', N'Cây tróc bạc hồng ‘Neon Robusta’ chậu đất nung SPNR004', N'Tróc bạc hồng là loại cây có thể phát triển tốt ngay cả trong điều kiện thiếu sáng, do đó bạn sẽ không phải quá lo lắng khi trồng chúng trong nhà. Loài cây này cũng có sức sống rất khỏe mạnh, phát triển nhanh và ít cần phải chăm sóc. Cây phát triển theo dạng dây leo, hình dáng lá như mũi tên nên có tên gọi “Arrowhead Plant” trong tiếng Anh.', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.867' AS DateTime), CAST(N'2024-11-20T14:49:05.867' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0183', 1, N'PWAF004', N'Cây trầu bà thanh xuân vàng', N'Cây trầu bà thanh xuân vàng chậu đất nung PWAF004', N'Trầu bà thanh xuân vàng là loại cây có màu sắc gây ấn tượng, bởi chúng hoàn toàn được “phủ” bởi màu vàng rực rỡ. Nếu như bạn đang muốn mang thêm sắc màu vào không gian sống thì hãy cân nhắc tới loại cây này. Hơn nữa, đây cũng là loại cây cực kì dễ chăm sóc, chịu hạn tốt.', 380000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.870' AS DateTime), CAST(N'2024-11-20T14:49:05.870' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0184', 1, N'MARA301', N'Cây cầu nguyên', N'Cây cầu nguyện Maranta leuconeura chậu đất nung MARA301', N'Maranta leuconeura là một loại cây nội thất rất được ưu thích tại các nước Châu Âu. Loài cây này sở hữu bộ lá sặc sỡ tựa như một chiếc đuôi công, những đường gân lá khỏe khoắn gây ấn tượng mạnh, cùng tông màu đẹp như một bức tranh nghệ thuật.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.870' AS DateTime), CAST(N'2024-11-20T14:49:05.870' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0185', 1, N'SCHE016', N'Ngũ gia bì', N'Cây ngũ gia bì bonsai để bàn SCHE016', N'Ngũ gia bì là loại cây mang lại tài vận, thịnh vượng và may mắn, trồng trong nhà sẽ mang đến một không gian thư thái, trong lành cho gia đình.', 680000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.870' AS DateTime), CAST(N'2024-11-20T14:49:05.870' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0186', 1, N'CFML001', N'Huyết huyết dụ ‘Mocha Latte’', N'Cây huyết dụ ‘Mocha Latte’ chậu ươm CFML001', N'Cây phất dụ ‘Mocha Latte’ là loại cây có bộ lá sặc sỡ như một tách ‘Mocha Latte’, rất thích để trồng trang trí nội thất. Với sức sống cực kỳ mãnh liệt, loại cây sẽ là một sự lựa chọn tuyệt vời dành cho những “người lưới”. Vẻ đẹp độc đáo của cây phất dụ ‘bảy sắc’ chắc chắn sẽ rất hút mắt những vị khách tới thăm nhà bạn.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.870' AS DateTime), CAST(N'2024-11-20T14:49:05.870' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0187', 1, N'PEWA003', N'Cây dưa hấu', N'Cây dưa hấu ‘Watermelon’ để bàn chậu cú mèo PEWA003', N'Cây dưa hấu có kích thước nhỏ gọn, là hình bầu dục, tán lá sọc xanh sẫm và thân màu đỏ. Chính là kiểu lá sọc xanh tựa như cây dưa hấu nên chúng được đặt tên là cây dưa hấu ‘ Watermelon’. Tuy những chiếc lá khá mỏng manh, nhưng nó lại có sức sống rất khỏe, dễ chăm sóc.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.873' AS DateTime), CAST(N'2024-11-20T14:49:05.873' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0188', 1, N'CHLO002', N'Cây phượng hoàng lửa / Lục thảo lan', N'Cây phượng hoàng lửa Chlorophytum chậu gốm CHLO002', N'Cây phượng hoàng lửa là loại có sức sống rất bền bỉ, dễ chăm sóc và sống được nơi thiếu ánh sáng nên rất thích hợp để trồng trong nhà. Loại cây này sở hữu bộ lá màu xanh mướt, cùng phần thân màu cam ấm cúng nên rất thích hợp với các không gian tối giản.', 380000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.873' AS DateTime), CAST(N'2024-11-20T14:49:05.873' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0189', 1, N'LYRA036-1', N'Cây bàng Singapore', N'Cây bàng Singapore hai nhánh nhỏ chậu đen LYRA037', N'Cây Bàng Singapore là loại cây nội thất đang được ưa chuộng nhất hiện nay. Cây có khả năng cải thiện chất lượng không khí. Mang lại sự xanh mát và sang trọng cho không gian của bạn, trang trí phòng khách, văn phòng, quán cafe hay shop.Hoặc làm quà tặng dịp khai trương, tân gia…', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.873' AS DateTime), CAST(N'2024-11-20T14:49:05.873' AS DateTime))
