INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0190', 1, N'CFWR002', N'Huyết phất dụ 7 sắc', N'Cây huyết dụ bảy sắc cầu vòng chậu đất nung CFWR002', N'Cây phất dụ ‘bảy sắc’ là loại cây có bộ lá sặc sỡ như ‘bảy sắc cầu vòng’, rất thích để trồng trang trí nội thất. Với sức sống cực kỳ mãnh liệt, loại cây sẽ là một sự lựa chọn tuyệt vời dành cho những “người lưới”. Vẻ đẹp độc đáo của cây phất dụ ‘bảy sắc’ chắc chắn sẽ rất hút mắt những vị khách tới thăm nhà bạn.', 220000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.877' AS DateTime), CAST(N'2024-11-20T14:49:05.877' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0191', 1, N'LICU008', N'Cọ Nhật', N'Cây cọ nhật để sàn chậu đá mài LICU008', N'Cây cọ nhật là loại cây trong nhà có kiểu lá xòe rộng như những cánh quạt, giúp trang trí không gian thêm xanh mát. Nó còn là loại cây phong thủy tượng trưng cho sự giàu sang và tiền tài nên rất đáng trồng trên bàn làm việc.', 650000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.877' AS DateTime), CAST(N'2024-11-20T14:49:05.877' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0192', 1, N'CPTN009', N'Phát tài núi', N'Cây phát tài núi 2 tầng chậu ươm CPTN009', N'Cây phát tài núi rất thường được lựa chọn để làm quà tặng vào những dịp khai trương, lên nhà mới, văn phòng mới… với mong muốn đem lại nhiều tài lộc và may mắn cho người được tặng.', 1200000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.877' AS DateTime), CAST(N'2024-11-20T14:49:05.877' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0193', 1, N'CFWR001', N'Huyết phất dụ 7 sắc', N'Cây huyết dụ bảy sắc cầu vòng chậu ươm CFWR001', N'Cây phất dụ ‘bảy sắc’ là loại cây có bộ lá sặc sỡ như ‘bảy sắc cầu vòng’, rất thích để trồng trang trí nội thất. Với sức sống cực kỳ mãnh liệt, loại cây sẽ là một sự lựa chọn tuyệt vời dành cho những “người lưới”. Vẻ đẹp độc đáo của cây phất dụ ‘bảy sắc’ chắc chắn sẽ rất hút mắt những vị khách tới thăm nhà bạn.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.880' AS DateTime), CAST(N'2024-11-20T14:49:05.880' AS DateTime))
