INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0194', 1, N'DITS001', N'Cây vạn niên thanh', N'Cây vạn niên thanh ‘Tropic Snow’ chậu ươm DITS001', N'Với bộ lá rực rỡ, có nền màu xanh đậm, bên trong là những đốm sáng tựa như những ngôi sao nên cây sao sáng thường được trồng để trang hoàng cho không gian nội thất. Loại cây này còn được xem là biểu tượng của sự may mắn, nguồn năng lượng tích cực, tài lộc và sự thịnh vượng.', 400000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.880' AS DateTime), CAST(N'2024-11-20T14:49:05.880' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0195', 1, N'AGMO003', N'Cây sao sáng lá đậm', N'Cây sao sáng lá đậm ‘Galaxy’ chậu sứ AGMO003', N'Với bộ lá rực rỡ, có nền màu xanh đậm, bên trong là những đốm sáng tựa như những ngôi sao nên cây sao sáng thường được trồng để trang hoàng cho không gian nội thất. Loại cây này còn được xem là biểu tượng của sự may mắn, nguồn năng lượng tích cực, tài lộc và sự thịnh vượng.', 450000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.880' AS DateTime), CAST(N'2024-11-20T14:49:05.880' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0196', 1, N'AGLE003', N'Cây cung điện vàng', N'Cây cung điện vàng ‘Pink Legacy’ chậu sứ AGLE003', N'Cây cung điện sở hữu bộ lá nhiều màu sắc rực rỡ như chốn “hoàng cung”, cùng với đó là những đường viền hoa văn độc đáo như tranh vẽ. Loại cây này rất dễ chăm sóc, thích hợp để trang trí không gian phòng khách, quầy tiếp tân, sảnh ra vào hoặc để bàn làm việc.', 280000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.880' AS DateTime), CAST(N'2024-11-20T14:49:05.880' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0197', 1, N'SAFS003', N'Cây lưỡi hổ thái', N'Cây lưỡi hổ Thái để bàn chậu đất nung “Futura superba” SAFS003', N'Lưỡi hổ là loại cây cảnh nội thất kinh điển nhất, bởi sức sống bền bỉ không cần tốn công chăm sóc, lại còn được NASA đánh giá là có khả năng thanh lọc không khí rất hiệu quả bằng một cơ chế hấp thu các loại chất khí độc hại trên bộ lá.', 220000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.883' AS DateTime), CAST(N'2024-11-20T14:49:05.883' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0198', 1, N'ZAMI027', N'Cây kim tiền / Kim phát tài', N'Cây kim tiền để bàn tiểu cảnh ông bà chậu sứ ZAMI027', N'Cây kim tiền có lá hình xương cá màu xanh mướt. Loài này rất dễ sống phát triển mạnh ở những nơi có độ ẩm cao, thường được trồng để trang trí trong phòng khách, làm quà tặng tân gia, khai trương cửa hàng.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.883' AS DateTime), CAST(N'2024-11-20T14:49:05.883' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0199', 1, N'AGPL002', N'Cây hồng phát lộc', N'Cây hồng phát lộc ‘Pink Lady’ chậu sứ trắng AGPL002', N'Cây hồng phát lộc là loại cây nhỏ để bàn, có màu hồng phớt tươi mới và bắt mắt, giúp tạo điểm nhấn cho góc làm việc thêm sinh động. Chúng còn là dòng cây phong thủy, được cho rằng giúp mang lại những điều may mắn và thịnh vượng tới cho gia chủ. Hồng phát lộc cũng là một món quà rất ý nghĩa vào những dịp khai trương, sinh nhật hoặc dịp lễ.', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.883' AS DateTime), CAST(N'2024-11-20T14:49:05.883' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0200', 1, N'ANTH005', N'Cây hồng môn', N'Cây hồng môn để bàn tiểu cảnh “mèo chiêu tài” ANTH005', N'Cây hồng môn được biết tới là một loại cây cảnh mang lại điều tốt lành, có thể giúp điều hòa khí phong thủy trong nhà, có khả năng thu hút những dòng khí tích cực và làm tiêu bớt dòng khí tiêu cực cho môi trường xung quanh, trồng cây hồng môn trong nhà sẽ giúp không gian sống trở nên hài hòa và bình yên hơn.', 360000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.887' AS DateTime), CAST(N'2024-11-20T14:49:05.887' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0201', 1, N'ZAMI026', N'Cây kim tiền / Kim phát tài', N'Cây kim tiền lớn để sàn chậu nhựa trụ tròn ZAMI026', N'Cây kim tiền có lá hình xương cá màu xanh mướt. Loài này rất dễ sống phát triển mạnh ở những nơi có độ ẩm cao, thường được trồng để trang trí trong phòng khách, làm quà tặng tân gia, khai trương cửa hàng.', 950000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.887' AS DateTime), CAST(N'2024-11-20T14:49:05.887' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0202', 1, N'CTBC004', N'Trầu bà xanh', N'Cây trầu bà cột chậu nhựa trụ tròn CTBC004', N'Cây trầu bà cột chứa đựng ý nghĩa phong thủy rất tốt, mang dáng vẻ thanh lịch và sang trọng. Đồng thời nó còn có tác dụng thanh lọc không khí trong nhà rất tốt, giúp không gian xanh mát và trong lành hơn.', 1400000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.890' AS DateTime), CAST(N'2024-11-20T14:49:05.890' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0203', 1, N'BUBU001', N'Bàng Đài Loan cẩm thạch', N'Cây bàng đài loan cẩm thạch chậu ươm BUBU001', N'Bàng Đài Loan cẩm thạch có lá nhỏ xinh và sắc xanh, viền trắng hồng rất khác biệt và nổi bật, giúp không gian trở nên độc đáo và sang trọng', 340000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.890' AS DateTime), CAST(N'2024-11-20T14:49:05.890' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0204', 1, N'PHBI004', N'Cây hồng hạc chân cam', N'Cây hồng hạc thân cam “Billietiae’ chậu đất nung PHBI004', N'Cây Hạc Cam đặc trưng bởi những chiếc lá thuôn dài, hình dây đeo có xẻ trái tim sâu, phần cuống cũng được tô điểm bởi màu da cam rất bắt mắt. Khi trưởng thành cây hạc Philodendron billietiae có kích thước rất khủng nên được nhiều người săn đón sưu tầm.', 1500000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.890' AS DateTime), CAST(N'2024-11-20T14:49:05.890' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0205', 1, N'SHBG002', N'Cây lưỡi hổ Thái xanh', N'Cây lưỡi hổ xanh mini ‘Black Gold’ thủy sinh SHBG002', N'Lưỡi hổ Thái xanh mini là dòng lưỡi hổ nhỏ để bàn, có chiều cao tối đa khoảng 20cm, không có nhiều vằn như những loại lưỡi hổ khác, nhưng nó lại sở hữu bộ lá màu xanh đậm ấn tượng, mang lại nét ‘cứng cáp’ tự nhiên cho không gian. Chúng rất thích hợp để trên bàn làm việc, kệ trang trí hoặc làm quà tặng.', 220000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.890' AS DateTime), CAST(N'2024-11-20T14:49:05.890' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0206', 1, N'SSBG001', N'Cây lưỡi hổ Thái xanh', N'Cây lưỡi hổ xanh ‘Superba Black Gold’ chậu ươm SSBG001', N'Lưỡi hổ Thái Xanh là dòng lưỡi hổ nhỏ để bàn, có chiều cao tối đa khoảng 40cm, không có nhiều vằn như những loại lưỡi hổ khác, nhưng nó lại sở hữu bộ lá màu xanh đậm ấn tượng, mang lại nét ‘cứng cáp’ tự nhiên cho không gian. Chúng rất thích hợp để trên bàn làm việc, kệ trang trí hoặc làm quà tặng.', 150000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.893' AS DateTime), CAST(N'2024-11-20T14:49:05.893' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0207', 1, N'ROSM002', N'Cây hương thảo', N'Cây hương thảo cỡ trung chậu ươm ROSM002', N'Không chỉ có tác dụng trang trí cho góc ban công mà cây hương thảo còn là một loại cây thảo mộc giúp gia tăng hương vị cho món ăn. Cây hương thảo cũng có nhiều tác dụng đối với sức khỏe con người như giải nhiệt, lợi tiểu, giảm sưng viêm, hỗ trợ tiêu hóa, có hương thơm giúp tinh thần thoải mái.', 90000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.893' AS DateTime), CAST(N'2024-11-20T14:49:05.893' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0208', 1, N'TUBO001', N'Cây tùng bồng lai', N'Cây tùng bồng lai để bàn nhỏ chậu ươm TUBO001', N'Cây Tùng Bông Lai là một loài cây mang vẻ đẹp trang nhã, với tán lá dầy xanh mướt trông giống như những đám mây và có kích thước nhỏ gọn nên rất thích hợp để bàn làm việc. Chúng là loài cây dễ trồng nên không cần phải tốn công chăm sóc, tuy nhiên cần đặt tại nơi có nhiều ánh sáng.', 150000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.897' AS DateTime), CAST(N'2024-11-20T14:49:05.897' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0209', 1, N'KIGI001', N'Cây kim giao', N'Cây kim giao để bàn tiểu cảnh ‘mèo chiêu tài’ KIGI001', N'Kim giao là một cây thân gỗ có giá trị kinh tế lớn. Nhờ có sức sống mạnh mẽ, kiểu dáng đẹp, lá xum xuê và xanh mướt nên chúng cũng được nhân giống để làm cây cảnh để bàn, giúp tạo không gian xanh mát và thư giãn. Đồng thời đây cũng là một loại cây mang ý nghĩa phong thủy rất tốt. Rất thích hợp làm quà tặng.', 360000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.897' AS DateTime), CAST(N'2024-11-20T14:49:05.897' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0210', 1, N'LAMA003-1', N'Cây ráy ngựa vằn', N'Cây ráy ngựa vằn ‘Alocasica Sarian’ chậu ươm ALSA001', N'Alocasia sarian là một loại cây trong nhà có kích thước khổng lồ, khi trưởn thành lá có thể đạt được chiều dài tới 1,5m và rộng 1m. Nó chính là con lai giữa Alocasia zebrina và Alocasia micholitziana. Tuy có thể giúp mang lại vẻ độc đáo, ấn tượng cho không gian nội thất nhưng chúng rất ưu sáng, nên sẽ cần phải đặt tại nơi có nhiều nhiều ánh sáng.', 220000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.897' AS DateTime), CAST(N'2024-11-20T14:49:05.897' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0211', 1, N'SCHE015', N'Ngũ gia bì', N'Cây ngũ gia bì để bàn chậu sứ trắng SCHE015', N'Ngũ gia bì là loại cây mang lại tài vận, thịnh vượng và may mắn, trồng trong nhà sẽ mang đến một không gian thư thái, trong lành cho gia đình.', 360000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.900' AS DateTime), CAST(N'2024-11-20T14:49:05.900' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0212', 1, N'MONS104', N'Trầu bà Nam Mỹ', N'Cây trầu bà Nam Mỹ Monstera ‘Borsigiana’ chậu đá mài đen MONS104', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa mang lại may mắn và hạnh phúc nên cây thường được chọn để làm cây trưng trong nhà hoặc làm quà tặng.', 750000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.900' AS DateTime), CAST(N'2024-11-20T14:49:05.900' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0213', 1, N'RADE014', N'Cây hạnh phúc', N'Cây hạnh phúc một thân lớn chậu đá mài RADE014', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa mang lại may mắn và hạnh phúc nên cây thường được chọn để làm cây trưng trong nhà hoặc làm quà tặng.', 1650000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.900' AS DateTime), CAST(N'2024-11-20T14:49:05.900' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0214', 1, N'ANTH004', N'Cây hồng môn', N'Cây hồng môn hồng cỡ lớn chậu ươm ANTH004', N'Cây hồng môn được biết tới là một loại cây cảnh mang lại điều tốt lành, có thể giúp điều hòa khí phong thủy trong nhà, có khả năng thu hút những dòng khí tích cực và làm tiêu bớt dòng khí tiêu cực cho môi trường xung quanh, trồng cây hồng môn trong nhà sẽ giúp không gian sống trở nên hài hòa và bình yên hơn.', 280000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.900' AS DateTime), CAST(N'2024-11-20T14:49:05.900' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0215', 1, N'YUCA001', N'Cây dứa diệp tiễn / Thùa bạc', N'Cây dứa diệp tiễn ‘Yucca Silver’ chậu ươm YUCA001', N'Cô tòng đuôi lươn sở hữu bộ lá nhiều màu sắc rực rỡ, cùng những đường viền hoa văn độc đáo, chúngthường được trồng trang trí cho bồn hoa, ban công hoặc trước hiên nhà. Loại cây này đôi lúc được trồng trong nhà, nhưng đòi hỏi phải trồng nơi có nhiều ánh sáng, gần cửa sổ.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.903' AS DateTime), CAST(N'2024-11-20T14:49:05.903' AS DateTime))
GO
