INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0221', 1, N'AGLE001', N'Cây cung điện vàng', N'Cây cung điện vàng ‘Pink Legacy’ chậu ươm AGLE001', N'Cây cung điện sở hữu bộ lá nhiều màu sắc rực rỡ như chốn “hoàng cung”, cùng với đó là những đường viền hoa văn độc đáo như tranh vẽ. Loại cây này rất dễ chăm sóc, thích hợp để trang trí không gian phòng khách, quầy tiếp tân, sảnh ra vào hoặc để bàn làm việc.', 150000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.907' AS DateTime), CAST(N'2024-11-20T14:49:05.907' AS DateTime))
