INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0222', 1, N'AGRS002', N'Cây hồng phát lộc', N'Cây vạn lộc son ‘Red Star’ thủy sinh AGRS002', N'Cô tòng đuôi lươn sở hữu bộ lá nhiều màu sắc rực rỡ, cùng những đường viền hoa văn độc đáo, chúngthường được trồng trang trí cho bồn hoa, ban công hoặc trước hiên nhà. Loại cây này đôi lúc được trồng trong nhà, nhưng đòi hỏi phải trồng nơi có nhiều ánh sáng, gần cửa sổ.', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.910' AS DateTime), CAST(N'2024-11-20T14:49:05.910' AS DateTime))
