INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0223', 1, N'AGRA001', N'Cây hồng phát lộc', N'Cây vạn lộc son ‘Red Anjamani’ hai thân chậu ươm AGRA001', N'Cô tòng đuôi lươn sở hữu bộ lá nhiều màu sắc rực rỡ, cùng những đường viền hoa văn độc đáo, chúngthường được trồng trang trí cho bồn hoa, ban công hoặc trước hiên nhà. Loại cây này đôi lúc được trồng trong nhà, nhưng đòi hỏi phải trồng nơi có nhiều ánh sáng, gần cửa sổ.', 320000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.910' AS DateTime), CAST(N'2024-11-20T14:49:05.910' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0224', 1, N'AGPL001', N'Cây hồng phát lộc', N'Cây hồng phát lộc ‘Pink Lady’ chậu ươm AGPL001', N'Cây hồng phát lộc là loại cây nhỏ để bàn, có màu hồng phớt tươi mới và bắt mắt, giúp tạo điểm nhấn cho góc làm việc thêm sinh động. Chúng còn là dòng cây phong thủy, được cho rằng giúp mang lại những điều may mắn và thịnh vượng tới cho gia chủ. Hồng phát lộc cũng là một món quà rất ý nghĩa vào những dịp khai trương, sinh nhật hoặc dịp lễ.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.910' AS DateTime), CAST(N'2024-11-20T14:49:05.910' AS DateTime))
GO
