INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0230', 1, N'CDBD202', N'Đa búp đỏ cẩm thạch', N'Cây đa búp đỏ cẩm thạch 1 thân chậu ươm BDCT003', N'Từ lâu cây Đa luôn là biểu tượng của sự trường tồn, sức sống dẻo dai, nơi chứa đựng thần quyền và tâm linh của con người. Chính lẽ đó mà trong phong thủy, Đa Búp Đỏ cũng mang ý nghĩa của sự may mắn, an lành.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.917' AS DateTime), CAST(N'2024-11-20T14:49:05.917' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0231', 1, N'LAMA002', N'Cây cô tòng đuôi lươn', N'Cây cô tòng đuôi lươn ‘Croton Captain Kidd’ chậu ươm LAMA002', N'Cô tòng đuôi lươn sở hữu bộ lá nhiều màu sắc rực rỡ, cùng những đường viền hoa văn độc đáo, chúng thường được trồng trang trí cho bồn hoa, ban công hoặc trước hiên nhà. Loại cây này đôi lúc được trồng trong nhà, nhưng đòi hỏi phải trồng nơi có nhiều ánh sáng, gần cửa sổ.', 65000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.920' AS DateTime), CAST(N'2024-11-20T14:49:05.920' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0232', 1, N'LAMA001', N'Cây cô tòng lá mít', N'Cây cô tòng lá mít ‘Croton Petra’ chậu ươm LAMA001', N'Cô tòng lá mít là loại có thể trồng được cả trong nhà lẫn ngoài trời. Với tán lá rực rỡ nhiều màu sắc như xanh lá, vàng, đỏ và cam, sẽ là một lựa chọn tuyệt vời để trang hoàng cho ngôi nhà thêm sinh động hơn.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.920' AS DateTime), CAST(N'2024-11-20T14:49:05.920' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0233', 1, N'AGRS001', N'Cây vạn lộc đỏ', N'Cây vạn lộc đỏ ‘Suksom’ chậu ươm AGRS001', N'Cây bao thanh thiên có bộ lá sặc sỡ và khỏe khoắn nên rất thích hợp để trang hoàng thêm điểm nhấn cho không gian sống. Loại cây này còn được xe là tượng trưng cho sự ngay thẳng, chính trực trong phong thủy. Khi trồng sẽ giúp thu hút năng lượng tích cực, xua đuổi cái xấu.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.920' AS DateTime), CAST(N'2024-11-20T14:49:05.920' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0234', 1, N'AGSW001', N'Cây ngọc bích', N'Cây ngọc bích ‘Super White’ chậu ươm AGSW001', N'Cây ngọc bích là là cây trong nhà được đánh giá cao về phong thuỷ, người ta quan niệm rằng cây Ngọc ngân mang đến tài lộc, may mắn khi đặt trên bàn làm việc hay trang trí trong văn phòng. Về mặt tinh thần cây Ngọc ngân rất thích hợp làm quà tặng tình yêu.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.923' AS DateTime), CAST(N'2024-11-20T14:49:05.923' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0235', 1, N'SCHE011', N'Ngũ gia bì cẩm thạch', N'Cây ngũ gia bì cẩm thạch cỡ nhỏ chậu ươm SCHE011', N'Cây ngũ gia bì là loại cây mang lại tài vận, thịnh vượng và may mắn, trồng trong nhà sẽ mang đến một không gian thư thái, trong lành cho gia đình.', 60000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.923' AS DateTime), CAST(N'2024-11-20T14:49:05.923' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0236', 1, N'RADE011', N'Cây hạnh phúc', N'Cây hạnh phúc cỡ trung chậu ươm RADE011', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa mang lại may mắn và hạnh phúc nên cây thường được chọn để làm cây trưng trong nhà hoặc làm quà tặng.', 220000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.923' AS DateTime), CAST(N'2024-11-20T14:49:05.923' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0237', 1, N'AGSU001', N'Cây bao thanh thiên', N'Cây bao thanh thiên ‘Aglaonema Sumatra’ chậu ươm AGSU001', N'Cây bao thanh thiên có bộ lá sặc sỡ và khỏe khoắn nên rất thích hợp để trang hoàng thêm điểm nhấn cho không gian sống. Loại cây này còn được xe là tượng trưng cho sự ngay thẳng, chính trực trong phong thủy. Khi trồng sẽ giúp thu hút năng lượng tích cực, xua đuổi cái xấu.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.927' AS DateTime), CAST(N'2024-11-20T14:49:05.927' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0238', 1, N'PHBZ024', N'Trầu bà Brazil', N'Cây trầu bà Brasil ‘Carnival’ leo cột chậu ươm PHBZ024', N'Trầu bà tỷ phú là loại cây nội thất cao cấp với những chiếc lá to có hình trái tim, màu cẩm thạch sang trọng luôn được săn đón trong giới mê cây cảnh. Trầu bà tỷ phú còn được xem là loại cây phong thủy, mang ý nghĩa về sự thành đạt và trù phú.', 330000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.927' AS DateTime), CAST(N'2024-11-20T14:49:05.927' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0239', 1, N'PHIL106', N'Trầu bà tỷ phú cẩm thạch', N'Cây trầu bà tỷ phú cẩm thạch ‘Burle Marx’ PHIL106', N'Trầu bà tỷ phú là loại cây nội thất cao cấp với những chiếc lá to có hình trái tim, màu cẩm thạch sang trọng luôn được săn đón trong giới mê cây cảnh. Trầu bà tỷ phú còn được xem là loại cây phong thủy, mang ý nghĩa về sự thành đạt và trù phú.', 650000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.927' AS DateTime), CAST(N'2024-11-20T14:49:05.927' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0240', 1, N'AGMO001', N'Cây sao sáng lá đậm', N'Cây sao sáng lá đậm ‘Galaxy’ chậu ươm AGMO001', N'Với bộ lá rực rỡ, có nền màu xanh đậm, bên trong là những đốm sáng tựa như những ngôi sao nên cây sao sáng thường được trồng để trang hoàng cho không gian nội thất. Loại cây này còn được xem là biểu tượng của sự may mắn, nguồn năng lượng tích cực, tài lộc và sự thịnh vượng.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.930' AS DateTime), CAST(N'2024-11-20T14:49:05.930' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0241', 1, N'CHLO001', N'Cây phượng hoàng lửa / Lục thảo lan', N'Cây phượng hoàng lửa Chlorophytum chậu ươm CHLO001', N'Cây phượng hoàng lửa là loại có sức sống rất bền bỉ, dễ chăm sóc và sống được nơi thiếu ánh sáng nên rất thích hợp để trồng trong nhà. Loại cây này sở hữu bộ lá màu xanh mướt, cùng phần thân màu cam ấm cúng nên rất thích hợp với các không gian tối giản.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.930' AS DateTime), CAST(N'2024-11-20T14:49:05.930' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0242', 1, N'TBDV501', N'Trầu bà đế vương kim cương', N'Cây trầu bà đế vương kim cương ‘Birkin’ TBDV501', N'Trầu Bà Đế Vương Kim Cương là một làn gió mới trong kiểng lá khi nói đến các loại cây trồng trong nhà đang thịnh hành và nó chắc chắn sẽ trêu ngươi bất kỳ người đam mê cây cảnh nào.', 125000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.930' AS DateTime), CAST(N'2024-11-20T14:49:05.930' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0243', 1, N'TBDV100', N'Cây trầu bà đế vương vàng', N'Cây trầu bà đế vương ‘Rojo’ mini chậu ươm TBDV100', N'Trầu Bà Đế Vương có tên tiếng Anh là Philodendron Imperial thuộc họ Araceae (Ráy), là dòng cây thân thảo, trong tự nhiên dòng cây này có thể cao hơn 1,5 m nhưng với mục đích trang trí thì MOW sẽ gửi đến các bạn cây với kích cỡ nhỏ để tiện đặt ở bất cứ đâu mình thích.', 75000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.930' AS DateTime), CAST(N'2024-11-20T14:49:05.930' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0244', 1, N'TBDV300', N'Cây trầu bà đế vương vàng', N'Cây trầu bà đế vương xanh mini chậu ươm TBDV300', N'Trầu Bà Đế Vương có tên tiếng Anh là Philodendron Imperial thuộc họ Araceae (Ráy), là dòng cây thân thảo, trong tự nhiên dòng cây này có thể cao hơn 1,5 m nhưng với mục đích trang trí thì MOW sẽ gửi đến các bạn cây với kích cỡ nhỏ để tiện đặt ở bất cứ đâu mình thích.', 75000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.933' AS DateTime), CAST(N'2024-11-20T14:49:05.933' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0245', 1, N'TBDV400', N'Cây trầu bà đế vương vàng', N'Cây trầu bà đế vương vàng mini chậu ươm TBDV400', N'Trầu Bà Đế Vương có tên tiếng Anh là Philodendron Imperial thuộc họ Araceae (Ráy), là dòng cây thân thảo, trong tự nhiên dòng cây này có thể cao hơn 1,5 m nhưng với mục đích trang trí thì MOW sẽ gửi đến các bạn cây với kích cỡ nhỏ để tiện đặt ở bất cứ đâu mình thích.', 90000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.933' AS DateTime), CAST(N'2024-11-20T14:49:05.933' AS DateTime))
