INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0247', 1, N'ASPL120', N'Cây dương xỉ tổ chim Nhật Bản', N'Cây dương xỉ tổ chim ‘Osaka’ chậu ươm ASPL120', N'Dương xỉ tổ chim có tán lá dài, uốn lượn sóng phần viền lá và xanh mướt. Loài này có bộ lá khá dày và cứng cáp, rất dễ chăm sóc, thích ánh sáng tán xạ và ẩm môi trường trung bình.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.933' AS DateTime), CAST(N'2024-11-20T14:49:05.933' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0248', 1, N'CANE001', N'Cây đuôi công ‘Network’', N'Cây đuôi công ‘Network’ chậu ươm CANE001', N'Với những vân lá tạo nên hoạ tiết ô lưới ngẫu nhiên độc đáo như một bức tranh mosaic kì công. Calathea Network tạo nên sự khác biệt không thể tìm thấy với bất kỳ loại cây nào.', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.937' AS DateTime), CAST(N'2024-11-20T14:49:05.937' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0249', 1, N'CATH002', N'Cây đuôi công táo xanh', N'Cây đuôi công táo thủy sinh ‘Orbifolia’ CATH002', N'Những chiếc ta to xanh mướt cùng phần viền hoa văn của cây đuôi công táo xanh chắc chắn sẽ mang lại cho không gian nhà bạn những điểm nhấn tuyệt vời. Bạn có thể trồng loại cây này để trang trí thêm cho phòng khách, phòng ăn hay nhà bếp.', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.937' AS DateTime), CAST(N'2024-11-20T14:49:05.937' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0250', 1, N'LYRA036', N'Cây bàng Singapore', N'Cây bàng Singapore hai nhánh nhỏ chậu ươm LYRA036', N'Cây Bàng Singapore là loại cây nội thất đang được ưa chuộng nhất hiện nay. Cây có khả năng cải thiện chất lượng không khí. Mang lại sự xanh mát và sang trọng cho không gian của bạn, trang trí phòng khách, văn phòng, quán cafe hay shop.Hoặc làm quà tặng dịp khai trương, tân gia…', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.937' AS DateTime), CAST(N'2024-11-20T14:49:05.937' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0251', 1, N'LYRA035', N'Cây bàng Singapore', N'Cây bàng Singapore mini để bàn tiểu cảnh Uyên Ương LYRA035', N'Cây bàng Singapore đang loại cây trong nhà được nhiều người ưu chuộng với bộ lá màu xanh lá mượt mà, dáng thẳng đứng thanh lịch và sang trọng giúp cho không gian nhà bạn thêm phần sinh động. B', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.940' AS DateTime), CAST(N'2024-11-20T14:49:05.940' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0252', 1, N'RADE010', N'Cây hạnh phúc', N'Cây hạnh phúc một thân chậu sứ trắng RADE010', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa mang lại may mắn và hạnh phúc nên cây thường được chọn để làm cây trưng trong nhà hoặc làm quà tặng.', 650000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.940' AS DateTime), CAST(N'2024-11-20T14:49:05.940' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0253', 1, N'ZAMI025', N'Cây kim tiền / Kim phát tài', N'Cây kim tiền để bàn chậu sứ ZAMI025', N'Cây kim tiền là loài thực vật họ nhà Araceae, có lá hình xương cá màu xanh mướt. Loài này rất dễ sống phát triển mạnh ở những nơi có độ ẩm cao, thường được trồng để trang trí trong phòng khách, làm quà tặng tân gia, khai trương cửa hàng.', 220000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.940' AS DateTime), CAST(N'2024-11-20T14:49:05.940' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0254', 1, N'BDCT002', N'Đa búp đỏ cẩm thạch', N'Cây đa búp đỏ cẩm thạch 3 thân chậu ươm BDCT002', N'Từ lâu cây Đa luôn là biểu tượng của sự trường tồn, sức sống dẻo dai, nơi chứa đựng thần quyền và tâm linh của con người. Chính lẽ đó mà trong phong thủy, Đa Búp Đỏ cũng mang ý nghĩa của sự may mắn, an lành.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.940' AS DateTime), CAST(N'2024-11-20T14:49:05.940' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0255', 1, N'RADE009', N'Cây hạnh phúc', N'Cây hạnh phúc 2 tầng chậu sứ trắng RADE009', N'Cây dễ sinh trưởng phát triển mọi diều kiện thời tiết khác nhau nên rất dễ trồng và chăm sóc. Cây sống tốt trong điều kiện có điều hoà và môi trường thiếu sáng nên chúng ta có thể dễ dàng lựa chọn cây trang trí để bàn cho không gian làm việc trở nên xanh mát và ấm áp.', 990000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.943' AS DateTime), CAST(N'2024-11-20T14:49:05.943' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0256', 1, N'TBTX006', N'Cây trầu bà thanh xuân / Cây trầu bà tay Phật', N'Cây trầu bà thanh xuân cỡ lớn chậu đá mài TBTX006', N'Trầu bà thanh xuân là loại cây trong nhà độc đáo được mọi người ưa thích và trưng bày trang trí. Trầu Bà Thanh Xuân có ý nghĩa về mặt phong thủy nó còn có ý nghĩa may mắn, đem lại tài lộc, gia tăng vận khí, thể hiện ý chí vươn lên của gia chủ.', 1200000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.943' AS DateTime), CAST(N'2024-11-20T14:49:05.943' AS DateTime))
GO
