GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0261', 1, N'DIEF004', N'Cây tuyết trắng', N'Cây tuyết trắng chậu ươm Dieffenbachia sp DIEF004', N'Là một trong các loại cây được nhiều người ưa thích bởi mang lại nhiều tác dụng hữu ích, không những thế còn có nghĩa phong thủy tốt.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.950' AS DateTime), CAST(N'2024-11-20T14:49:05.950' AS DateTime))
