INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0264', 1, N'CALA025', N'Cây đuôi công', N'Cây đuôi công Calathea roseopicta Marion chậu sứ CALA025', N'Calathea Roseopicta Marion là loài thực vật thân thảo, có lá hình thuôn tròn, màu xanh đậm, họa tiết viền xanh nhạt. Loài này rất dễ sống, thường được trồng để trang trí trong nhà, thanh lọc không khí và mang ý nghĩa đem lại may mắn, thành công và thịnh vượng.', 420000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.950' AS DateTime), CAST(N'2024-11-20T14:49:05.950' AS DateTime))
