INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0265', 1, N'ZAMI024', N'Cây kim tiền / Kim phát tài', N'Cây kim tiền để bàn chậu men sứ ZAMI024', N'Cây kim tiền là loài thực vật họ nhà Araceae, có lá hình xương cá màu xanh mướt. Loài này rất dễ sống phát triển mạnh ở những nơi có độ ẩm cao, thường được trồng để trang trí trong phòng khách, làm quà tặng tân gia, khai trương cửa hàng.', 320000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.953' AS DateTime), CAST(N'2024-11-20T14:49:05.953' AS DateTime))
