INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0266', 1, N'MARA300', N'Cây cầu nguyên', N'Cây cầu nguyện Maranta leuconeura MARA300', N'Maranta leuconeura là một loại cây nội thất rất được ưu thích tại các nước Châu Âu. Loài cây này sở hữu bộ lá sặc sỡ tựa như một chiếc đuôi công, những đường gân lá khỏe khoắn gây ấn tượng mạnh, cùng tông màu đẹp như một bức tranh nghệ thuật.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.953' AS DateTime), CAST(N'2024-11-20T14:49:05.953' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0267', 1, N'CALA520', N'Cây đuôi xương cá', N'Cây đuôi xương cá Calathea burle-marxii var CALA520', N'Cây đuôi xương cá là loài thực vật thân thảo, có lá hình thuôn tròn, sọc xanh. Loài này rất dễ sống, thường được trồng để trang trí trong nhà, thanh lọc không khí và mang ý nghĩa đem lại may mắn, thành công và thịnh vượng.', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.953' AS DateTime), CAST(N'2024-11-20T14:49:05.953' AS DateTime))
GO
