GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0273', 1, N'PHIL152', N'Cây hồng hạc chân cam', N'Cây hồng hạc thân cam Philodendron billietiae chậu đất nung PHIL152', N'Cây Hạc Cam đặc trưng bởi những chiếc lá thuôn dài, hình dây đeo có xẻ trái tim sâu, phần cuống cũng được tô điểm bởi màu da cam rất bắt mắt. Khi trưởng thành cây hạc Philodendron billietiae có kích thước rất khủng nên được nhiều người săn đón sưu tầm.', 1550000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.960' AS DateTime), CAST(N'2024-11-20T14:49:05.960' AS DateTime))
