INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0275', 1, N'ANTH003', N'Cây hồng môn', N'Cây hồng môn nhỏ để bàn chậu sứ ANTH003', N'Cây hồng môn được biết tới là một loại cây cảnh mang lại điều tốt lành, có thể giúp điều hòa khí phong thủy trong nhà, có khả năng thu hút những dòng khí tích cực và làm tiêu bớt dòng khí tiêu cực cho môi trường xung quanh, trồng cây hồng môn trong nhà sẽ giúp không gian sống trở nên hài hòa và bình yên hơn.', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:05.963' AS DateTime), CAST(N'2024-11-20T14:49:05.963' AS DateTime))
GO
