INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0320', 1, N'LONI003', N'Cây kim ngân', N'Cây kim ngân thân trụ to để bàn chậu ươm LONI003', N'Cây kim ngân thân xoắn với dáng cao độc đáo rất phù hợp để trang trí trong nhà, như là trong phòng khách, kệ trang trí hoặc bàn làm việc. Nà là giống cây cảnh nội thất có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.013' AS DateTime), CAST(N'2024-11-20T14:49:06.013' AS DateTime))
