INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0339', 1, N'mons015', N'Trầu bà hạnh phúc', N'Cây trầu bà hạnh phúc để bàn chậu gốm Monstera Pinnatipartita MONS015', N'Cây có bản lá to màu xanh thuộc hành Mộc nên cây phù hợp làm cây phong thủy cho người mệnh Mộc và mệnh Hỏa, mang đến may mắn, thành đạt và bình an cho gia chủ.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.043' AS DateTime), CAST(N'2024-11-20T14:49:06.043' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0340', 1, N'ASPA004', N'Dương xỉ Hà Lan', N'Cây dương xỉ Hà Lan để bàn chậu gốm sứ ASPA004', N'Dương xỉ Hà Lan là một loại cây trong nhà có sức sống rất bền bỉ, bộ lá cứng cáp, kháng bệnh tốt và dễ chăm sóc. Nó còn nổi tiếng với khả năng lọc không khí giúp môi trường sống thêm trong lạnh. loại bỏ các chất khí độc hại trong không khí.', 280000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.043' AS DateTime), CAST(N'2024-11-20T14:49:06.043' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0341', 1, N'cala018', N'Đuôi công táo xanh', N'Cây đuôi công táo xanh để bàn chậu gốm Calathea Orbifolia CALA018', N'Với tán lá tròn trịa xoè rộng phủ xanh cả khu vườn nhỏ, bạn chỉ cần trồng vài cây Orbifolia là không khí tropical mát mẻ đã về với không gian nhà rồi đó.', 400000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.043' AS DateTime), CAST(N'2024-11-20T14:49:06.043' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0342', 1, N'ASPL008-1', N'Đuôi công xương cá', N'Cây Đuôi công xương cá chậu ươm CALA016', N'Cây đuôi công thường được chọn để mang lại không gian xanh mát cho phòng làm việc, phòng làm việc, văn phòng, quán cafe,… Bởi loài cây có những đường vân sọc độc đáo, cùng màu xanh dễ chịu giúp căn phòng trở nên tươi mát và sang trọng hơn.', 200000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.047' AS DateTime), CAST(N'2024-11-20T14:49:06.047' AS DateTime))
GO
