INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0344', 1, N'PHIL016', N'Philodendron Mayoi', N'Cây philodendron mayoi leo cột chậu ươm PHIL016', N'Philodendron Mayoi là một loại cây nội thất cao cấp có hình dáng lá độc đáo, thích hợp đặt trong những không gian hiện đại và sang trọng.', 650000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.050' AS DateTime), CAST(N'2024-11-20T14:49:06.050' AS DateTime))
