INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0364', 1, N'CATH104', N'Cây đuôi phụng', N'Cây đuôi phụng lớn chậu men sứ trắng CATH104', N'Vẻ đẹp độc đáo của loài cây này khiến cho người ta phải gọi nó bằng cái tên là cây đuôi phụng, và theo “mặc định” thì nó luôn là một sự lựa chọn tuyệt hảo được dùng để trang trí cho không gian nội thất thêm phần sinh động.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.070' AS DateTime), CAST(N'2024-11-20T14:49:06.070' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0365', 1, N'CAMA005', N'Đuôi công khổng tước', N'Cây đuôi công khổng tước ‘Makoyana’ chậu đất nung CAMA005', N'Loài cây đuôi công này được trồng rất phổ biến trong nội thất với mục đích trang trí, tạo thêm mảnh xanh và thanh lọc không khí, họa tiết lá rất sang trọng.', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.070' AS DateTime), CAST(N'2024-11-20T14:49:06.070' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0366', 1, N'cbtt001', N'Bao thanh thiên', N'Cây bao thanh thiên chậu gốm để bàn CBTT001', N'Sống lâu năm và thường mọc thành bụi, mang đặc điểm nổi bật nhờ các gân đỏ rõ nét trên nền lá màu xanh tía.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.073' AS DateTime), CAST(N'2024-11-20T14:49:06.073' AS DateTime))
GO
