INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0369', 1, N'ctbh005', N'Trúc bách hợp', N'Cây trúc bách hợp chậu gốm có họa tiết CTBH005', N'Cây trúc bách hợp thường được làm quà tặng nhân dịp khánh thành, khai trương, tân gia, như là lời chúc may mắn đến với người nhận.', 750000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.077' AS DateTime), CAST(N'2024-11-20T14:49:06.077' AS DateTime))
