INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0371', 1, N'crq001', N'Chuối rẻ quạt', N'Cây chuối rẻ quạt chậu gốm họa tiết CRQ001', N'Tuy cây chuối rẻ quạt thuộc giống cây ngoại nhập, nhưng cây vẫn sống tốt trong điều kiện khí hậu tại nước ta.', 750000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.077' AS DateTime), CAST(N'2024-11-20T14:49:06.077' AS DateTime))
