INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0372', 1, N'cptn008', N'Phát tài núi', N'Cây phát tài núi 2 tầng chậu sứ CPTN008', N'Cây phát tài núi rất thường được lựa chọn để làm quà tặng vào những dịp khai trương, lên nhà mới, văn phòng mới… với mong muốn đem lại nhiều tài lộc và may mắn cho người được tặng.', 1650000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.080' AS DateTime), CAST(N'2024-11-20T14:49:06.080' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0373', 1, N'cptn007', N'Phát tài núi', N'Cây phát tài núi nhiều nhánh chậu sứ họa tiết CPTN007', N'Cây phát tài núi rất thường được lựa chọn để làm quà tặng vào những dịp khai trương, lên nhà mới, văn phòng mới… với mong muốn đem lại nhiều tài lộc và may mắn cho người được tặng.', 3200000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.080' AS DateTime), CAST(N'2024-11-20T14:49:06.080' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0374', 1, N'mons013', N'Cây Trầu Bà Lỗ', N'Cây Trầu Bà Lỗ chậu gốm để bàn Monstera adansonii Monkey Mask – MONS013', N'Monstera adansonii là cây thân thảo, thích nghi với bóng râm hoàn toàn, vì vậy chúng thường được trồng trong nhà, sức sống mạnh mẽ, dễ dàng chăm sóc và có thể tồn tại trong nhiều môi trường khác nhau, gốc nhiều nhánh và đốt.
Với những chiếc lá xanh tươi, thân hình nhỏ nhắn trông rất dễ thương có thể sẽ rất phù hợp với các bạn nữ, nhân viên văn phòng trong lúc mệt mỏi có thể ngắm nhìn để giải tỏa phần nào áp lực công việc, cuộc sống.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.080' AS DateTime), CAST(N'2024-11-20T14:49:06.080' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0375', 1, N'SANS007', N'Lưỡi hổ ta', N'Cây lưỡi hổ để bàn SANS007', N'Lưỡi hổ có lẽ là loại cây nội thất quen thuộc nhất đối với những người yêu cây cảnh. Loài cây này có khả năng chịu nóng, chịu hạn tốt, sống được trong bóng râm và đặc biệt nó có khả năng lọc không khí rất tuyệt vời.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.083' AS DateTime), CAST(N'2024-11-20T14:49:06.083' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0376', 1, N'LICU007', N'Cọ Nhật', N'Cây cọ Nhật cây văn phòng LICU007', N'Cây cọ nhật là loại cây trong nhà có kiểu lá xòe rộng như những cánh quạt, giúp trang trí không gian thêm xanh mát. Nó còn là loại cây phong thủy tượng trưng cho sự giàu sang và tiền tài nên rất đáng trồng trên bàn làm việc.', 550000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.083' AS DateTime), CAST(N'2024-11-20T14:49:06.083' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0377', 1, N'MIX006', N'Cây văn phòng - cây quà tặng', N'Cây văn phòng – cây quà tặng MIX006', N'Combo cây văn phòng Mix006 có thể dễ dàng bài trí trong văn phòng, quán cafe, phòng khách…mà không phải lo về ngũ hành tương sinh, tương khắc.
Chậu cây văn phòng MIX006 là sản phẩm được MOW phối trộn với nhau một cách hài hòa và hợp lý. Điểm nhấn là cây Hoàng Hậu làm trung tâm, dưới chân là cây Phú Quý, cây Ngọc Ngân và cây thường xuân. Biểu trưng cho một bà Hoàng Hậu nhân từ ôm lấy những đứa còn, mong đem lại hạnh phúc và tài lộc cho gia chủ.', 1290000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.083' AS DateTime), CAST(N'2024-11-20T14:49:06.083' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0378', 1, N'TBTX004', N'Cây trầu bà thanh xuân / Cây trầu bà tay Phật', N'Cây trầu bà thanh xuân cỡ trung chậu đất nung TBTX004', N'Trầu bà thanh xuân là loại cây trong nhà độc đáo được mọi người ưa thích và trưng bày trang trí. Trầu Bà Thanh Xuân có ý nghĩa về mặt phong thủy nó còn có ý nghĩa may mắn, đem lại tài lộc, gia tăng vận khí, thể hiện ý chí vươn lên của gia chủ.', 520000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.087' AS DateTime), CAST(N'2024-11-20T14:49:06.087' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0379', 1, N'ARAC026', N'Cây môn thái', N'Cây môn Thái Caladium lindenii chậu đất nung ARAC026', N'Cây môn Thái sở hữu chất lá dày, khỏe khoắn, có form tai thỏ bắt mắt, cùng với sự tương phản giữa màu xanh thẩm của lá và sắc trắng ở gân lá, tạo ra một điểm nhấn riêng cho khu vườn của bạn. Loại cây này cực kì dễ chăm sóc và tốc độ phát triển cũng rất nhanh.', 420000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.087' AS DateTime), CAST(N'2024-11-20T14:49:06.087' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0380', 1, N'cdvd004', N'Đế vương đỏ', N'Cây Trầu bà đế vương đỏ chậu men lu sọc Philodendron Imperial Red CDVD004', N'Thân dạng thảo lớn, trong tự nhiên cây có thể leo được, nhưng đa số khi trồng chậu thì thân vươn thẳng chắc chắn, cao khoảng dưới 1m5.', 850000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.090' AS DateTime), CAST(N'2024-11-20T14:49:06.090' AS DateTime))
GO
