INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0384', 1, N'CDBD003', N'Đa búp đỏ', N'Cây đa búp đỏ một thân chậu xi măng CDBD003', N'Từ lâu cây Đa luôn là biểu tượng của sự trường tồn, sức sống dẻo dai, nơi chứa đựng thần quyền và tâm linh của con người. Chính lẽ đó mà trong phong thủy, Đa Búp Đỏ cũng mang ý nghĩa của sự may mắn, an lành.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.093' AS DateTime), CAST(N'2024-11-20T14:49:06.093' AS DateTime))
