GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0390', 1, N'PHIL800', N'Philodendron splendid', N'Cây Philodendron splendid leo cột chậu xi măng PHIL801', N'Philodendron splendid là loại cây kiểng lá rất được yêu thích bởi nó có phiến lá hình tim thuôn dài và mặt lá nhung mịn rất đẹp mắt. Những đường gân màu xanh sáng, có vệt hồng ở điểm giao giữa cuống và lá tạo thêm sự sắc sảo.', 3850000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.100' AS DateTime), CAST(N'2024-11-20T14:49:06.100' AS DateTime))
