INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0392', 1, N'CHAM006', N'Cau Hawaii', N'Cây cau Hawaii chậu xi măng đá mài CHAM006', N'Cau Hawaii là một loại cây cây cảnh nội thất phổ biến, thích hợp để trưng bày trong các không gian nội thất sang trọng. Loại cây này có sức sống mãnh liệt, dễ chăm sóc, có bộ lá xanh mướt và mang ý nghĩa rất tốt trong phong thủy.', 750000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.103' AS DateTime), CAST(N'2024-11-20T14:49:06.103' AS DateTime))
GO
