INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0394', 1, N'AGLA004-1', N'Cây vạn lộc', N'Cây Vạn Lộc để bàn Aglaonema Lady Valentine AGLA010', N'Cây vạn lộc (Aglaonema Lady Valentine) là dòng cây cảnh nội thất dễ chăm sóc, có thể sống được trong điều kiện ánh sáng thấp. Với một hình dạng lá độc đáo, bên trên là những họa tiết đẹp mắt giống như tranh vẽ giúp tạo thêm điểm nhấn cho không gian nội thất. Kích thước nhỏ gọn của cây vạn lộc thủy sinh rất thích hợp để đặt trang trí trên bàn hoặc trên tủ kệ.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.107' AS DateTime), CAST(N'2024-11-20T14:49:06.107' AS DateTime))
GO
