INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0397', 1, N'NTMX017', N'Cây phát tài / Vạn lộc / Ngọc ngân / Đô la / Trúc vàng', N'Chậu cây mix phát tài núi, trúc Nhật, vạn lộc, ngọc ngân, đô la NTMX017', N'Chậu cây nội thất được mix các loại cây dễ chăm sóc, thích nghi tốt với điều kiện thiếu sáng trong nhà. Sản phẩm được mix các loại cây Phát tài, Vạn lộc, Ngọc ngân, Đô la, Trúc Nhật mini thích hợp thể đặt tại phòng khách, lối hành lang, văn phòng làm việc, sảnh nhà hàng, khách sạn hoặc làm quà tặng.', 1250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.110' AS DateTime), CAST(N'2024-11-20T14:49:06.110' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0398', 1, N'MIX003', N'Cây văn phòng', N'Cây văn phòng – cây quà tặng MIX003', N'Chậu cây văn phòng MIX003 là sản phẩm được MOW phối trộn với nhau một cách hài hòa và hợp lý.
Lưỡi hổ cao làm chủ đạo, dưới chân là Vạn Lộc đỏ, Ngọc Ngân màu trắng ngọc và cây Đô La bao quanh gốc làm điểm tựa cho cây Lưỡi Hổ phát triển cũng như sự phát triển Tài Lộc của gia chủ.
Với chậu cây văn phòng Mix003 này chúng ta có thể dễ dàng bài trí trong văn phòng, quán cafe, phòng khách…mà không phải lo về ngũ hành tương sinh, tương khắc.', 890000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.110' AS DateTime), CAST(N'2024-11-20T14:49:06.110' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0399', 1, N'DRAC401', N'Cây huyết dụ kiếm', N'Cây huyết dụ kiếm chậu xi măng đá mài DRAC401', N'Cây huyết Dụ là một loại cây phong thủy có tác dụng mang lại may mắn, giữ tiền của và tài lộc cho gia chủ. Bên cạnh đó, cây huyết dụ được trồng hòng để ngăn chặn, xua đuổi tà ma tấn công vào nhà.', 420000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.113' AS DateTime), CAST(N'2024-11-20T14:49:06.113' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0400', 1, N'SANS034', N'Lưỡi hổ xanh', N'Cây lưỡi hổ xanh chậu đá xi măng vàng SANS034', N'Lưỡi hổ có lẽ là loại cây nội thất quen thuộc nhất đối với những người yêu cây cảnh. Loài cây này có khả năng chịu nóng, chịu hạn tốt, sống được trong bóng râm và đặc biệt nó có khả năng lọc không khí rất tuyệt vời.', 950000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.113' AS DateTime), CAST(N'2024-11-20T14:49:06.113' AS DateTime))
