INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0401', 1, N'PHIL026', N'Cây cung đàn xanh', N'Cây cung đàn chậu đất nung để bàn PHIL026', N'Cung đàn xanh là loại cây nội thất được săn đón ráo riết bởi cộng đồng kiểng lá trên thế giới bởi hình dáng lá răng cưa khá thú vị của nó. Nếu bạn đang muốn làm đa dạng bộ sưu tập cây trong nhà của mình thì em nó là một sự lựa chọn rất tuyệt vời.', 260000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.113' AS DateTime), CAST(N'2024-11-20T14:49:06.113' AS DateTime))
