INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0407', 1, N'ALOCA007', N'Rồng bạc', N'Cây Rồng Bạc để bàn – Alocasia Baginda Silver Dragon – ALOCA007', N'Bạn không cần dành quá nhiều thời gian cho Rồng Bạc nhưng vẫn ngắm nhìn được vẻ đẹp của nó mỗi ngày.', 280000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.120' AS DateTime), CAST(N'2024-11-20T14:49:06.120' AS DateTime))
