INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0408', 1, N'PHIL010', N'Trầu bà tim xanh', N'Cây Trầu Bà Tim Xanh để bàn – Philodendron Scandens – PHIL010', N'Trầu bà tim xanh (Philodendron scandens) sở hữu những chiếc lá màu xanh bóng hình trái tim quyến rũ, có thể trồng theo phong cách thả xuống trên kệ trang trí, trên tủ sách hoặc được treo lơ lửng, cũng có thể được gắn vào cột leo đẹp mắt. Chúng có khả năng sinh trưởng nhanh chóng và rất dễ chăm sóc, chỉ cần tưới một lần một tuần.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.123' AS DateTime), CAST(N'2024-11-20T14:49:06.123' AS DateTime))
