INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0409', 1, N'ALOCA006', N'Môn quan âm', N'Cây Môn quan âm để bàn – Alocasia Polly – ALOCA006', N'Điểm nổi bật nhất ở Môn Quan Âm là hình dáng lá độc đáo. Với những chiếc lá hình tim, nổi bật lên bề mặt lá là những đường gân dày, hòa cùng sắc tím trông vô cùng bắt mắt, độc đáo.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.123' AS DateTime), CAST(N'2024-11-20T14:49:06.123' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0410', 1, N'PHIL009', N'Trầu Bà Đế Vương Vàng', N'Cây trầu bà đế vương vàng chậu xi măng PHIL009', N'Trầu bà đế vương vàng có kích thước lá to nên rất thích hợp để trang trí trong phòng khách, quầy tiếp tân, quán cafe, nhà hàng… màu vàng của lá vừa đẹp, vừa sang và vừa mang ý nghĩa phong thủy rất tốt.', 450000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.127' AS DateTime), CAST(N'2024-11-20T14:49:06.127' AS DateTime))
