INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0411', 1, N'LYRA031', N'Cây bàng Singapore', N'Cây bàng Singapore 2 thân chậu đá mài LYRA031', N'Là loại cây nội thất đang được ưa chuộng nhất hiện nay bởi cây có khả năng cải thiện chất lượng không khí mang lại sự xanh mát và sang trọng cho không gian.', 800000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.130' AS DateTime), CAST(N'2024-11-20T14:49:06.130' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0412', 1, N'SAZE001', N'Lưỡi hổ xanh', N'Cây lưỡi hổ xanh ‘Zeylanica’ chậu ươm SAZE001', N'Lưỡi hổ có lẽ là loại cây nội thất quen thuộc nhất đối với những người yêu cây cảnh. Loài cây này có khả năng chịu nóng, chịu hạn tốt, sống được trong bóng râm và đặc biệt nó có khả năng lọc không khí rất tuyệt vời.', 150000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.130' AS DateTime), CAST(N'2024-11-20T14:49:06.130' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0413', 1, N'CHP004', N'Cây hạnh phúc', N'Cây hạnh phúc chậu bầu đen CHP004', N'Cây dễ sinh trưởng phát triển mọi diều kiện thời tiết khác nhau nên rất dễ trồng và chăm sóc. Cây sống tốt trong điều kiện có điều hoà và môi trường thiếu sáng nên chúng ta có thể dễ dàng lựa chọn cây trang trí để bàn cho không gian làm việc trở nên xanh mát và ấm áp.', 990000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.130' AS DateTime), CAST(N'2024-11-20T14:49:06.130' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0414', 1, N'CALA009', N'Đuôi công táo xanh', N'Cây đuôi công táo xanh để bàn chậu sứ CALA009', N'Với tán lá tròn trịa xoè rộng phủ xanh cả khu vườn nhỏ, bạn chỉ cần trồng vài cây Orbifolia là không khí tropical mát mẻ đã về với không gian nhà rồi đó.', 320000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.133' AS DateTime), CAST(N'2024-11-20T14:49:06.133' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0415', 1, N'EANJ004', N'Cây trầu bà cẩm thạch', N'Cây trầu bà cẩm thạch ‘Njoy’ chậu sứ EANJ004', N'Cây trầu bà cẩm thạch (Epipremnum ‘Njoy’) là một dòng trầu bà mới được du nhập, có bộ lá màu loang kem xanh độc đáo. Cũng tương tự cây trầu bà, nó cũng là giống cây có sức sống cực kỳ khỏe mạnh, với bộ lá xanh quanh năm và tốc độ phát triển khá nhanh.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.133' AS DateTime), CAST(N'2024-11-20T14:49:06.133' AS DateTime))
GO
