INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0417', 1, N'scin001', N'Trầu bà lụa', N'Cây Trầu bà lụa chậu gốm để bàn Scindapsus pictus Exotica SCIN001', N'Dễ dàng được lòng những người thích cây treo, cây leo hoặc các giống cây quý hiếm vì nó có hoa văn và màu sắc đẹp.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.137' AS DateTime), CAST(N'2024-11-20T14:49:06.137' AS DateTime))
