INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0418', 1, N'DRSU001', N'Trúc Nhật vàng', N'Cây trúc Nhật vàng để bàn chậu đất nung DRSU001', N'Với kích thước nhỏ gọn, Trúc Nhật vàng rất thích hợp đặt trên bàn làm việc, kệ trang trí hoặc văn phòng. Trúc Nhật thuộc có đặc điểm phát triển như thân tre, với tán lá màu vàng đốm rất đẹp mắt, giúp tăng thêm sức sống cho không gian sống của bạn.', 145000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.137' AS DateTime), CAST(N'2024-11-20T14:49:06.137' AS DateTime))
