INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0436', 1, N'', N'Cây Ổ Rồng', N'Cây Ổ Rồng treo tường Staghorn Fern STAG002', N'Cây Ổ Rồng được dùng để làm đẹp khoảng không ở khu vườn. Loài cây không thể thiếu cho những ai muốn tạo nên một khu rừng nhiệt đới thực thụ.', 450000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.157' AS DateTime), CAST(N'2024-11-20T14:49:06.157' AS DateTime))
