INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0437', 1, N'LYRA015', N'Cây bàng Singapore', N'Cây bàng Singapore để bàn chậu men sứ LYRA015', N'Bàng Singapore là loại cây nội thất đang được ưa chuộng nhất hiện nay bởi cây có khả năng cải thiện chất lượng không khí mang lại sự xanh mát và sang trọng cho không gian.', 280000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.160' AS DateTime), CAST(N'2024-11-20T14:49:06.160' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0438', 1, N'MONS008', N'Cây Trầu Bà Lỗ', N'Cây Trầu Bà Lỗ để bàn Monstera adansonii Monkey Mask – MONS008', N'Monstera adansonii là cây thân thảo, thích nghi với bóng râm hoàn toàn, vì vậy chúng thường được trồng trong nhà, sức sống mạnh mẽ, dễ dàng chăm sóc và có thể tồn tại trong nhiều môi trường khác nhau, gốc nhiều nhánh và đốt.
Với những chiếc lá xanh tươi, thân hình nhỏ nhắn trông rất dễ thương có thể sẽ rất phù hợp với các bạn nữ, nhân viên văn phòng trong lúc mệt mỏi có thể ngắm nhìn để giải tỏa phần nào áp lực công việc, cuộc sống.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.160' AS DateTime), CAST(N'2024-11-20T14:49:06.160' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0439', 1, N'ZAMI011', N'Cây kim tiền', N'Cây kim tiền cỡ trung chậu sứ ZAMI011', N'Cây kim tiền là loài thực vật họ nhà Araceae, có lá hình xương cá màu xanh mướt. Loài này rất dễ sống phát triển mạnh ở những nơi có độ ẩm cao, thường được trồng để trang trí trong phòng khách, làm quà tặng tân gia, khai trương cửa hàng.', 650000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.160' AS DateTime), CAST(N'2024-11-20T14:49:06.160' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0440', 1, N'DVX002', N'Cây Trầu Bà Đế Vương Xanh', N'Cây Trầu Bà Đế Vương Xanh Để Bàn DVX002', N'Trầu Bà Đế Vương có tên tiếng Anh là Philodendron Imperial thuộc họ Araceae (Ráy). Nguồn gốc của cây từ đảo Solomon, nguyên sinh ở Indonesia, là dòng cây thân thảo, trong tự nhiên dòng cây này có thể cao hơn 1.5m, nhưng với mục đích trang trí thì MOW sẽ gửi đến các bạn cây với kích cỡ nhỏ để tiện đặt ở bất cứ đâu mình thích.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.160' AS DateTime), CAST(N'2024-11-20T14:49:06.160' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0441', 1, N'CDBD002', N'Đa búp đỏ', N'Cây đa búp đỏ để bàn 3 thân chậu sứ CDBD002', N'Từ lâu cây Đa luôn là biểu tượng của sự trường tồn, sức sống dẻo dai, nơi chứa đựng thần quyền và tâm linh của con người. Chính lẽ đó mà trong phong thủy, Đa Búp Đỏ cũng mang ý nghĩa của sự may mắn, an lành.', 550000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.163' AS DateTime), CAST(N'2024-11-20T14:49:06.163' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0442', 1, N'RADE008', N'Cây hạnh phúc', N'Cây hạnh phúc để bàn chậu sứ RADE008', N'Cây dễ sinh trưởng phát triển mọi diều kiện thời tiết khác nhau nên rất dễ trồng và chăm sóc. Cây sống tốt trong điều kiện có điều hoà và môi trường thiếu sáng nên chúng ta có thể dễ dàng lựa chọn cây trang trí để bàn cho không gian làm việc trở nên xanh mát và ấm áp.', 150000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.163' AS DateTime), CAST(N'2024-11-20T14:49:06.163' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0443', 1, N'TBTX003', N'Cây trầu bà thanh xuân / Cây trầu bà tay Phật', N'Cây trầu bà thanh xuân chậu gốm TBTX003', N'Trầu bà thanh xuân là loại cây trong nhà độc đáo được mọi người ưa thích và trưng bày trang trí. Trầu Bà Thanh Xuân có ý nghĩa về mặt phong thủy nó còn có ý nghĩa may mắn, đem lại tài lộc, gia tăng vận khí, thể hiện ý chí vươn lên của gia chủ.', 500000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.163' AS DateTime), CAST(N'2024-11-20T14:49:06.163' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0444', 1, N'LONI011', N'Cây kim ngân', N'Cây kim ngân một thân trụ lớn chậu sứ trắng LONI011', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 450000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.167' AS DateTime), CAST(N'2024-11-20T14:49:06.167' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0445', 1, N'CTN001', N'Cây hoàng hậu, cây thanh ngân', N'Cây thanh ngân – hoàng hậu để bàn CTN001', N'Cây Thanh Lam thường mọc thành bụi lớn và có tán lá rộng. Thân và lá của cây mọc vươn thẳng. Phần thân của cây có màu trắng, phần lá có có màu xanh trắng. Phần rìa lá có màu xanh đậm, phần chính giữa lá có màu trắng. Lá cây có hình bầu dục với các gân và sống lá rõ.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.167' AS DateTime), CAST(N'2024-11-20T14:49:06.167' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0446', 1, N'ZAMI021', N'Cây kim tiền', N'Cây kim tiền cỡ trung chậu men sứ heritage ZAMI021', N'Cây kim tiền là loài thực vật họ nhà Araceae, có lá hình xương cá màu xanh mướt. Loài này rất dễ sống phát triển mạnh ở những nơi có độ ẩm cao, thường được trồng để trang trí trong phòng khách, làm quà tặng tân gia, khai trương cửa hàng.', 650000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.167' AS DateTime), CAST(N'2024-11-20T14:49:06.167' AS DateTime))
