INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0447', 1, N'agla005', N'Ngân hậu; Minh Ty Rằn', N'Cây Ngân hậu chậu men sứ Aglaonema Marantifolium AGLA005', N'Cây ngân hậu đại diện cho sự sang chảnh, quyền cao quý tộc giống như cái tên hoàng gia của nó vậy.', 380000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.170' AS DateTime), CAST(N'2024-11-20T14:49:06.170' AS DateTime))
