INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0449', 1, N'sans002', N'Lưỡi hổ Thái kim cương đen', N'Cây Lưỡi hổ kim cương đen để bàn Sansevieria Trifasciata Black Diamond SANS002', N'Lưỡi hổ “Black Diamond” không có nhiều vằn như những loại lưỡi hổ khác, nhưng nó lại sở hữu bộ lá màu xanh lá bóng mượt ấn tượng, mang lại nét cứng cáp tự nhiên cho không gian nội thất.', 320000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.170' AS DateTime), CAST(N'2024-11-20T14:49:06.170' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0450', 1, N'sans001', N'Ngà voi', N'Cây Ngà voi chậu gốm để bàn Sansevireria Cylindrica SANS001', N'Hình dáng bên ngoài độc đáo như chính tên gọi, bởi giống như những chiếc ngà voi vươn thẳng lên cao.', 320000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.170' AS DateTime), CAST(N'2024-11-20T14:49:06.170' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0451', 1, N'CATH546', N'Đuôi công xương cá', N'Cây Đuôi công xương cá Calathea burle-marxii CATH546', N'Cây đuôi công thường được chọn để mang lại không gian xanh mát cho phòng làm việc, phòng làm việc, văn phòng, quán cafe,… Bởi loài cây có những đường vân sọc độc đáo, cùng màu xanh dễ chịu giúp căn phòng trở nên tươi mát và sang trọng hơn.', 360000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.173' AS DateTime), CAST(N'2024-11-20T14:49:06.173' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0452', 1, N'chob001', N'Cánh bướm xanh', N'Cây Cánh bướm xanh để bàn chậu gốm họa tiết Christia Obcordata CHOB001', N'Hiện đang rất được ưa chuộng nhờ vẻ đẹp hoang dại với những sọc đỏ tía trên nền xanh hình tam giác , tạo tổng thể như những cánh bướm phất phơ trước gió.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.173' AS DateTime), CAST(N'2024-11-20T14:49:06.173' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0453', 1, N'', N'Trầu bà đế vương kim cương', N'Cây trầu bà đế vương kim cương để bàn PHIL201', N'Gây ấn tượng với những đường sọc trắng đẹp mắt, mang ý nghĩa phong thủy may mắn và tiền tại cho chủ sở hữu.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.173' AS DateTime), CAST(N'2024-11-20T14:49:06.173' AS DateTime))
