INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0454', 1, N'bego001', N'Thu hải đường', N'Cây Thu hải đường băng giá để bàn Begonia Ice Storm BEGO001', N'Những đốm trắng nổi rõ trên mặt lá như những giọt nước dưới cái lạnh mùa đông kết tinh thành băng đá.', 480000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.177' AS DateTime), CAST(N'2024-11-20T14:49:06.177' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0455', 1, N'DITS002', N'Vạn niên thanh', N'Cây vạn niên thanh ‘Tropic Snow’ chậu sứ cao DITS002', N'Với bộ lá rực rỡ, có nền màu xanh đậm, bên trong là những đốm sáng tựa như những ngôi sao nên cây sao sáng thường được trồng để trang hoàng cho không gian nội thất. Loại cây này còn được xem là biểu tượng của sự may mắn, nguồn năng lượng tích cực, tài lộc và sự thịnh vượng.', 650000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.177' AS DateTime), CAST(N'2024-11-20T14:49:06.177' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0456', 1, N'aloca002', N'Môn nhung', N'Cây Môn Nhung chậu gốm để bàn Alocasia Micholitziana Frydek ALOCA002', N'Làm cho ngôi nhà, khu vườn của bạn sinh động thêm với những chiếc lá rộng và mượt như nhung, kèm theo đó là những đường gân trắng nổi bật.', 1400000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.177' AS DateTime), CAST(N'2024-11-20T14:49:06.177' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0457', 1, N'PTDL003', N'Cây phát tài đài loan', N'Cây phát tài Đài Loan để bàn chậu sứ Geometric PTDL003', N'Cây phát tài Đài Loan lá dài màu xanh sọc vàng, mặt lá bóng, mép lá nguyên, bẹ lá ôm sát thân. Thân gỗ nhỏ sống lâu năm, chịu bóng râm tốt, sống được ngoài trời. Phát triển chậm và ít khi phân nhánh ngang', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.180' AS DateTime), CAST(N'2024-11-20T14:49:06.180' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0458', 1, N'ZAMI014', N'Cây kim tiền / Kim phát tài', N'Cây kim tiền cỡ lớn chậu xi măng remy màu đen ZAMI014', N'Cây kim tiền là loài thực vật họ nhà Araceae, có lá hình xương cá màu xanh mướt. Loài này rất dễ sống phát triển mạnh ở những nơi có độ ẩm cao, thường được trồng để trang trí trong phòng khách, làm quà tặng tân gia, khai trương cửa hàng.', 850000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.180' AS DateTime), CAST(N'2024-11-20T14:49:06.180' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0459', 1, N'RADE007', N'Cây hạnh phúc', N'Cây hạnh phúc một thân cỡ trung chậu đá mài RADE007', N'Cây hạnh phúc là dòng cây cảnh đẹp, sức sống khỏe mạnh, dễ chăm sóc. Trên cây có những tán lá xanh tươi, mượt mà thể hiện cho sự hi vọng và niềm tin mạnh mẽ. Với ý nghĩa may mắn hạnh phúc và dễ chăm sóc mà cây được chọn để làm cây trưng trong nhà hay làm quà tặng.', 990000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.180' AS DateTime), CAST(N'2024-11-20T14:49:06.180' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0460', 1, N'agsc001', N'Thanh tâm', N'Cây Thanh tâm chậu gốm Aglaonema Modestum Schott AGSC001', N'Một trong những loại cây cảnh trong nhà rất có giá trị về mặt phong thủy đang được nhiều người đam mê cây cảnh săn đón.', 400000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.180' AS DateTime), CAST(N'2024-11-20T14:49:06.180' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0461', 1, N'phil005', N'Hồng hạc cam', N'Cây Hạc cam để bàn chậu xi măng đá mài Philodenron Billietiae PHIL005', N'Với chiếc lá gây ấn tượng khá mạnh với nhiều người chơi kiểng nên hiện tại Billietiae đang dần phổ biến tại Việt Nam.', 2000000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.183' AS DateTime), CAST(N'2024-11-20T14:49:06.183' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0462', 1, N'BMHT002', N'Bạch mã hoàng tử', N'Cây Bạch mã hoàng tử chậu trắng BMHT002', N'Là loại cây nội thất đẹp thường được trồng để trang trí trong văn phòng, nhà ở, quán cafe, phòng làm việc với nhiều ý nghĩa phong thủy tốt đẹp.', 450000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.183' AS DateTime), CAST(N'2024-11-20T14:49:06.183' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0463', 1, N'SPI002', N'Cây cỏ lan chi / cây dây nhện', N'Cây cỏ lan chi để bàn chậu gốm trắng SPI002', N'Cỏ Lan Chi (hay còn gọi là Cỏ Nhện) là loại cây rất dễ sống với điều kiện khí hậu nóng tại Việt Nam. Đặc biệt, nó nằm trong top các loại cây lọc không khí rất hiệu quả, có thể đặt trong phòng ngủ giúp bạn có giấc ngủ trong lành hơn.', 125000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.183' AS DateTime), CAST(N'2024-11-20T14:49:06.183' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0464', 1, N'AGLV004', N'Cây vạn lộc', N'Cây vạn lộc ‘Valentine’ để bàn chậu sứ trắng AGLV004', N'Cây vạn lộc là dòng cây cảnh nội thất dễ chăm sóc, có thể sống được trong điều kiện ánh sáng thấp. Với một hình dạng lá độc đáo, bên trên là những họa tiết đẹp mắt giống như tranh vẽ giúp tạo thêm điểm nhấn cho không gian nội thất.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.187' AS DateTime), CAST(N'2024-11-20T14:49:06.187' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0465', 1, N'CTBC003-1', N'Trầu bà xanh', N'Cây trầu bà xanh để bàn chậu gốm CTBC004', N'Cây trầu bà để bàn có tác dụng thanh lọc không khí trong nhà mà còn chứa đựng ý nghĩa phong thủy rất tốt, mang dáng vẻ thanh lịch và sang trọng.', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.187' AS DateTime), CAST(N'2024-11-20T14:49:06.187' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0466', 1, N'SCHE002', N'Ngũ gia bì', N'Cây ngũ gia bì mini chậu đất nung SCHE005', N'Cây ngũ gia bì còn được gọi là cây Chân chim, có dáng đẹp, sống khỏe, dễ uốn tỉa nên thường được trồng làm cây cảnh văn phòng, trang trí trong nhà.', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.190' AS DateTime), CAST(N'2024-11-20T14:49:06.190' AS DateTime))
GO
