INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0468', 1, N'LONI010', N'Cây kim ngân', N'Cây kim ngân để bàn chậu sứ tuổi Tuất LONI010', N'Kim ngân là loại cây mang ý nghĩa may mắn, tài lộc và thường được làm quà biếu trong các dịp khai trương, tân gia, lên chức… như lời cầu chúc vạn sự may mắn, tấn tài tấn lộc đến người nhận.Chọn vị trí đặt cây cũng khá quan trọng để thu hút sự thịnh vượng và may mắn cho gia chủ.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.190' AS DateTime), CAST(N'2024-11-20T14:49:06.190' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0469', 1, N'AGLA003', N'Cây Phú Quý', N'Cây Phú quý để bàn chậu gốm Aglaonema Siam Aurora chậu sứ để bàn AGLA003', N'Cây Phú Quý có ý nghĩa mang lại may mắn, phú quý, đại cát đại lợi, bình an cho chủ nhân. Để Trúc Phú Quý mang lại ý nghĩa trọn vẹn bạn lưu ý về vị trí đặt theo hướng hợp với bản mệnh của mình.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.193' AS DateTime), CAST(N'2024-11-20T14:49:06.193' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0470', 1, N'MONS006', N'Trầu bà lá xẻ', N'Cây Trầu bà Nam Mỹ Monstera nhiều thân chậu gốm đen MONS006', N'Là loài cây sở hữu cho mình những chiếc lá được tạo nét như trái tim, càng lớn lá bắt đầu xuất hiện các đường xẻ một cách ngẫu nhiên.', 650000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.193' AS DateTime), CAST(N'2024-11-20T14:49:06.193' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0471', 1, N'CTBH004', N'Trúc bách hợp', N'Cây trúc bách hợp chậu xi măng xám CTBH004', N'Cây trúc bách hợp thường được làm quà tặng nhân dịp khánh thành, khai trương, tân gia, như là lời chúc may mắn đến với người nhận.', 750000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.193' AS DateTime), CAST(N'2024-11-20T14:49:06.193' AS DateTime))
