INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0472', 1, N'mons005', N'Trầu bà lá xẻ', N'Cây Trầu bà Nam Mỹ Monstera nhiều thân chậu xi măng MONS005', N'Là loài cây sở hữu cho mình những chiếc lá được tạo nét như trái tim, càng lớn lá bắt đầu xuất hiện các đường xẻ một cách ngẫu nhiên.', 1200000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.193' AS DateTime), CAST(N'2024-11-20T14:49:06.193' AS DateTime))
