INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0473', 1, N'CNN002', N'Cây ngọc ngân', N'Cây Ngọc Ngân để bàn chậu gốm size Trung – Aglaonema Snow White CNN002', N'Cây ngọc ngân thuộc dòng thân thảo, họ nhà Araceae, lá hình bầu, thuôn nhọn dần về đuôi. Lá cây mềm, màu xanh đốm trắng khá đặc trưng, viền lá màu xanh đậm và mướt. Cây ngọc ngân thuộc giống cây ưa bóng và sinh trưởng mạnh ở nơi mát mẻ rất thích hợp trồng cửa sổ phòng ngủ, phòng khách và trang trí cho cảnh quan văn phòng, quán cafe.', 450000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.197' AS DateTime), CAST(N'2024-11-20T14:49:06.197' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0474', 1, N'ancr001', N'Hồng môn lá tim', N'Cây Hồng môn Anthurium Crystallinum để bàn ANCR001', N'Crystallinum đẻ nhánh, tốc độ ra lá và để nhánh nhanh nhưng size lá không quá to.', 1200000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.197' AS DateTime), CAST(N'2024-11-20T14:49:06.197' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0475', 1, N'CNN001', N'Cây ngọc ngân', N'Cây ngọc ngân để bàn chậu đất nung AGLA004', N'Cây ngọc ngân là là cây trong nhà được đánh giá cao về phong thuỷ, người ta quan niệm rằng cây Ngọc ngân mang đến tài lộc, may mắn khi đặt trên bàn làm việc hay trang trí trong văn phòng. Về mặt tinh thần cây Ngọc ngân rất thích hợp làm quà tặng tình yêu.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.197' AS DateTime), CAST(N'2024-11-20T14:49:06.197' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0476', 1, N'TBTX005', N'Cây trầu bà thanh xuân / Cây trầu bà tay Phật', N'Cây trầu bà thanh xuân lớn chậu sứ trắng TBTX005', N'Trầu bà thanh xuân là loại cây trong nhà độc đáo được mọi người ưa thích và trưng bày trang trí. Trầu Bà Thanh Xuân có ý nghĩa về mặt phong thủy nó còn có ý nghĩa may mắn, đem lại tài lộc, gia tăng vận khí, thể hiện ý chí vươn lên của gia chủ.', 650000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.200' AS DateTime), CAST(N'2024-11-20T14:49:06.200' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0477', 1, N'CATH065', N'Đuôi công sọc', N'Cây Đuôi công sọc Calathea Vittata chậu gốm CATH065', N'Nếu bạn đang tìm một chiếc cây để bàn thật bắt mắt hay một món quà khai trương văn phòng mới cho những người bạn trân trọng thì đừng ngần ngại mà chọn ngay một chiếc Đuôi Công xinh xắn này nhé.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.200' AS DateTime), CAST(N'2024-11-20T14:49:06.200' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0478', 1, N'TBTX001', N'Cây trầu bà thanh xuân / Cây trầu bà tay Phật', N'Cây trầu bà thanh xuân cỡ lớn chậu ươm TBTX002', N'Trầu bà thanh xuân là loại cây trong nhà độc đáo được mọi người ưa thích và trưng bày trang trí. Trầu Bà Thanh Xuân có ý nghĩa về mặt phong thủy nó còn có ý nghĩa may mắn, đem lại tài lộc, gia tăng vận khí, thể hiện ý chí vươn lên của gia chủ.', 550000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.200' AS DateTime), CAST(N'2024-11-20T14:49:06.200' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0479', 1, N'ALOCA001', N'• Môn Rồng Bạc
• Alocasia Baginda
• Silver Dragon', N'Cây Môn Rồng Bạc Alocasia Baginda Silver Dragon chậu sứ trắng  ALOCA001', N'Một viên ngọc đến từ họ nhà Alocasia, kích thích mọi ánh nhìn, Alocasia Baginda Silver Dragon nổi tiếng và đầy mê hoặc. Nó có thể tồn tại khá tốt trong nhà lẫn ngoài trời.', 650000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.200' AS DateTime), CAST(N'2024-11-20T14:49:06.200' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0480', 1, N'CDBD001', N'Đa búp đỏ', N'Cây đa búp đỏ 3 thân chậu sứ trắng CDBD001', N'Từ lâu cây Đa luôn là biểu tượng của sự trường tồn, sức sống dẻo dai, nơi chứa đựng thần quyền và tâm linh của con người. Chính lẽ đó mà trong phong thủy, Đa Búp Đỏ cũng mang ý nghĩa của sự may mắn, an lành.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.203' AS DateTime), CAST(N'2024-11-20T14:49:06.203' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0481', 1, N'dief001', N'Sao sáng', N'Cây Sao sáng Dieffenbachia Camille chậu sứ để bàn DIEF001', N'Có nguồn gốc từ vùng Caribê và Nam Mỹ, chúng được trồng rộng rãi để làm cây trang trí.', 450000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.203' AS DateTime), CAST(N'2024-11-20T14:49:06.203' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0482', 1, N'agla002', N'Cây Phú Quý', N'Cây Phú quý Aglaonema Siam Aurora chậu sứ để bàn AGLA002', N'Cây Phú Quý có ý nghĩa mang lại may mắn, phú quý, đại cát đại lợi, bình an cho chủ nhân. Để Trúc Phú Quý mang lại ý nghĩa trọn vẹn bạn lưu ý về vị trí đặt theo hướng hợp với bản mệnh của mình.', 390000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.203' AS DateTime), CAST(N'2024-11-20T14:49:06.203' AS DateTime))
