INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0510', 1, N'ZAMI016', N'Cây kim tiền / Kim phát tài', N'Cây Kim tiền chậu xi măng đá hình lu ZAMI016', N'Các nhánh thân mọc thành từng bụi với chiều dài trung bình từ 18 đến 45 cm phù hợp để trồng chậu đặt trong phòng.', 850000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.240' AS DateTime), CAST(N'2024-11-20T14:49:06.240' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0511', 1, N'LONI012', N'Cây kim ngân', N'Cây kim ngân một thân cổ thụ chậu sứ xanh LONI012', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 480000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.240' AS DateTime), CAST(N'2024-11-20T14:49:06.240' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0512', 1, N'FITR005', N'Đa Tam Phúc', N'Cây đa tam phúc cẩm thạch chậu đá mài xám FITR005', N'Có nguồn gốc từ miền nam Thái Lan. Loại cây này thường được trồng trang trí sân vườn, hoặc trồng chậu làm cây cảnh.', 1200000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.243' AS DateTime), CAST(N'2024-11-20T14:49:06.243' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0513', 1, N'CPTN', N'Phát tài núi', N'Cây Phát tài núi chậu xi măng trắng hình lu CPTN001', N'Thường xuyên được người ta đem tặng nhau trong những dịp khai trương, lên nhà mới… với mong muốn đem lại nhiều tài lộc và may mắn.', 1450000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.243' AS DateTime), CAST(N'2024-11-20T14:49:06.243' AS DateTime))
