INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0514', 1, N'CHPD', N'Huyết phất dụ', N'Cây huyết phất dụ chậu gốm xanh CHPD001', N'Là cây thân gỗ mọc theo bụi thường xanh, dáng thân và tán lá rất đẹp thu hút người nhìn.', 600000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.247' AS DateTime), CAST(N'2024-11-20T14:49:06.247' AS DateTime))
