INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0515', 1, N'PHIL002', N'Trầu Bà Đế Vương Vàng', N'Cây trầu bà đế vương vàng chậu sứ để bàn PHIL002', N'Trầu bà đế vương vàng có kích thước lá to nên rất thích hợp để trang trí trong phòng khách, quầy tiếp tân, quán cafe, nhà hàng… màu vàng của lá vừa đẹp, vừa sang và vừa mang ý nghĩa phong thủy rất tốt.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.247' AS DateTime), CAST(N'2024-11-20T14:49:06.247' AS DateTime))
