INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0516', 1, N'PHIL001', N'Trầu Bà Kim Cương', N'Cây trầu bà kim cương chậu sứ để bàn PHIL001', N'Trầu bà đế vương kim cương sở hữu những chiếc lá to, hơi tròn đầy và những đường kẻ sáng màu sọc ngang từ gân lá ra mép lá rất độc đáo. Loại cây rât dễ chăm sóc, nhưng cần trồng nơi có nhiều ánh sáng tán xạ, không thích hợp đặt trong phòng tối, điều đó ảnh hưởng đến màu sắc của cây.', 380000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.250' AS DateTime), CAST(N'2024-11-20T14:49:06.250' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0517', 1, N'AGLA103', N'Cây Phú Quý', N'Cây phú quý chậu sứ để bàn AGLA103', N'Cây Phú Quý có ý nghĩa mang lại may mắn, phú quý, đại cát đại lợi, bình an cho chủ nhân. Để Trúc Phú Quý mang lại ý nghĩa trọn vẹn bạn lưu ý về vị trí đặt theo hướng hợp với bản mệnh của mình.', 320000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.250' AS DateTime), CAST(N'2024-11-20T14:49:06.250' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0518', 1, N'cala001', N'Đuôi công xương cá', N'Cây đuôi công xương cá chậu xứ để bàn CALA001', N'Cây đuôi công thường được chọn để mang lại không gian xanh mát cho phòng làm việc, phòng làm việc, văn phòng, quán cafe,… Bởi loài cây có những đường vân sọc độc đáo, cùng màu xanh dễ chịu giúp căn phòng trở nên tươi mát và sang trọng hơn.', 360000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.253' AS DateTime), CAST(N'2024-11-20T14:49:06.253' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0519', 1, N'CHRY005', N'Cau vàng Nhật Bản', N'Cây cau vàng Nhật Bản cỡ lớn chậu đá mài CHRY005', N'Cây Cau Vàng Nhật là loại cây cảnh đẹp ngoài việc dùng làm trang trí nội thất, ngoại thất làm tô điểm cho không gian sống thì cây còn có khả năng hấp thụ các độc tố hóa học và có một ý nghĩa vô cùng đặc biệt trong việc lọc khí độc, trừ tà.', 950000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.257' AS DateTime), CAST(N'2024-11-20T14:49:06.257' AS DateTime))
