INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0522', 1, N'mons003', N'Trầu bà Nam Mỹ Monstera', N'Cây trầu bà Nam Mỹ Monstera chậu men sứ cao MONS003', N'Monstera là loài cây sở hữu cho mình những chiếc lá được tạo nét như trái tim, càng lớn lá bắt đầu xuất hiện các đường xẻ một cách ngẫu nhiên. Vì thế đây được xem là điểm độc đáo mà các nhà thiết kế nội thất lựa chọn nó.', 850000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.260' AS DateTime), CAST(N'2024-11-20T14:49:06.260' AS DateTime))
