INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0525', 1, N'CTBH006', N'Trúc bách hợp', N'Cây trúc bách hợp chậu gốm sứ trắng CTBH006', N'Còn được gọi là trúc phất dụ, mọc thành bụi sum sê, ở chính giữa tạo thành hình hoa thị và tua tủa ra xung quanh. Cây có thân cứng, lá thuôn nhọn ở đầu, mép nguyên, màu xanh bóng xen lần dải màu vàng tươi từ gốc tới ngọn', 700000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.263' AS DateTime), CAST(N'2024-11-20T14:49:06.263' AS DateTime))
