INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0531', 1, N'', N'Melanochrysum', N'Cây Philodendron Melanochrysum', N'Một cây kiểng lá sang đẹp decor đẹp bất chấp. Mặt lá nhung và lá hình mũi tên dài. Khi trưởng thành nó có thể leo cao . Cây rễ khoẻ lá lớn (hơn 10cm) và vài lá con.', 1100000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.273' AS DateTime), CAST(N'2024-11-20T14:49:06.273' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0532', 1, N'', N'Trầu Bà Sodiroi', N'Cây Trầu Bà Philodendron Sodiroi', N'Là loài bản xứ của French Guiana và cũng có thể tìm thấy ở một số quốc gia Nam Mỹ như Venezuela, Brazil và Colombia. Philodendron Sodiroi có phiến lá hình tim bầu bĩnh và các nếp gấp phồng đều theo các đường đường gân, lá màu xanh bạc, sáng bóng và các vết đốm màu xám bạc.', 1700000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.277' AS DateTime), CAST(N'2024-11-20T14:49:06.277' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0533', 1, N'', N'Cây hồng môn', N'Cây hồng môn thủy sinh để bàn ANTH002', N'Cây hồng môn được biết tới là một loại cây cảnh mang lại điều tốt lành, có thể giúp điều hòa khí phong thủy trong nhà, có khả năng thu hút những dòng khí tích cực và làm tiêu bớt dòng khí tiêu cực cho môi trường xung quanh, trồng cây hồng môn trong nhà sẽ giúp không gian sống trở nên hài hòa và bình yên hơn.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.277' AS DateTime), CAST(N'2024-11-20T14:49:06.277' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0534', 1, N'POTH252', N'Cây trầu bà cẩm thạch / Trầu bà sữa', N'Cây Trầu Bà Cẩm Thạch Thủy Sinh Njoy Pothos POTH252', N'Cây trầu bà cẩm thạch (Epipremnum ‘Njoy’) là một dòng trầu bà mới được du nhập, có bộ lá màu loang kem xanh độc đáo. Cũng tương tự cây trầu bà, nó cũng là giống cây có sức sống cực kỳ khỏe mạnh, với bộ lá xanh quanh năm và tốc độ phát triển khá nhanh.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.280' AS DateTime), CAST(N'2024-11-20T14:49:06.280' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0535', 1, N'PEOB002', N'Cây trường sinh', N'Cây Trường Sinh Thủy Sinh Peperomia obtusifolia PEOB002', N'Cây trường sinh (Peperomia obtusifolia) là một loại cây cảnh trong nhà đẹp mắt, với bộ lá luôn xanh mát, sức sống mãnh liệt, dễ chăm sóc. Đây cũng là loại cây phong thủy với tác dụng mang đến sức khỏe, may mắn và tiền tài tới cho gia chủ. Người ta thường hay tặng cây trường sinh vào những dịp đặc biệt như là một lời chúc phúc tới người nhận.', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.280' AS DateTime), CAST(N'2024-11-20T14:49:06.280' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0536', 1, N'LONI005', N'Cây kim ngân', N'Cây kim ngân thủy sinh để bàn LONI005', N'Cây Kim Ngân (Pachira aquatica) là dòng cây nội thất được ưu chuộng và phổ biến nhất trên thế giới, nó được biết đến là loại cây phong thủy giúp mang lại những điều tốt lành, vận may và tiền tài tới cho gia chủ.', 150000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.283' AS DateTime), CAST(N'2024-11-20T14:49:06.283' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0537', 1, N'PLTS001', N'Cây phát lộc', N'Cây phát lộc thủy sinh Dracaena sanderiana PLTS001', N'Cây phát lộc (Dracaena sanderiana) là một loại cây phong thủy được xem là có tác dụng chiêu tài, giúp gia tăng vượng khí cho gia chủ, xua đuổi tà khí và mang đến sự may mắn, tài lộc. Đây cũng là loại cây thích hợp để làm quà tặng giúp với ý nghĩa chúc phúc cho người được nhận.', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.283' AS DateTime), CAST(N'2024-11-20T14:49:06.283' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0538', 1, N'', N'Cây hồng lộc phát', N'Cây Hồng Lộc Phát Thủy Sinh Aglaonema Red Valentine', N'Cây hồng lộc phát (Aglaonema Red Valentine) là dòng cây cảnh nội thất dễ chăm sóc, có thể sống được trong điều kiện ánh sáng thấp. Với một hình dạng lá độc đáo, bên trên là những họa tiết đẹp mắt giống như tranh vẽ giúp tạo thêm điểm nhấn cho không gian nội thất. Kích thước nhỏ gọn của cây hồng lộc phát thủy sinh rất thích hợp để đặt trang trí trên bàn hoặc trên tủ kệ.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.283' AS DateTime), CAST(N'2024-11-20T14:49:06.283' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0539', 1, N'CAMA003', N'Đuôi công khổng tước', N'Cây đuôi công khổng tước thủy sinh CAMA003', N'Cau đuôi công khổng tước (Calathea makoyana) là một trong những loại cây cảnh nội thất rất được ưa chuộng hiện nay. Với tán lá xanh mượt mà, trên đó là những đốm xanh đặc sắc như đuôi công giúp tạo điểm nhấn cho không gian rất tuyệt vời. Cây đuôi công còn giúp mang lại không khí tự nhiên xanh mát, và là biểu tượng cho quyền quý, may mắn nên được lựa chọn làm món quà tặng trong các dịp sinh nhật, lễ tết, ngày đặc biệt…', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.287' AS DateTime), CAST(N'2024-11-20T14:49:06.287' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0540', 1, N'', N'Cây tiểu trâm', N'Cây cau tiểu trâm thủy sinh để bàn CHAM002', N'Cau tiểu trâm hay còn được gọi là dừa tụ thân là một trong những loại cây cảnh nội thất rất được ưa chuộng hiện nay. Với tán lá xanh mượt và đặc tính lọc sạch các chất khí độc, cau tiểu trâm mang lại không khí trong lành, bởi vậy cau tiểu trâm được lựa chọn làm món quà tặng trong các dịp sinh nhật, lễ tết, ngày đặc biệt…', 280000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.287' AS DateTime), CAST(N'2024-11-20T14:49:06.287' AS DateTime))
GO
