INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0555', 1, N'', N'Cây trầu bà thanh xuân', N'Cây trầu bà thanh xuân mini chậu ươm TBTX001', N'Trầu bà thanh xuân là loại cây trong nhà độc đáo được mọi người ưa thích và trưng bày trang trí. Trầu Bà Thanh Xuân có ý nghĩa về mặt phong thủy nó còn có ý nghĩa may mắn, đem lại tài lộc, gia tăng vận khí, thể hiện ý chí vươn lên của gia chủ.', 75000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.303' AS DateTime), CAST(N'2024-11-20T14:49:06.303' AS DateTime))
