INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0556', 1, N'', N'• Môn Baret', N'Cây Môn Caladium Red Baret', N'Với những vệt loang màu đỏ tươi trên nền lá màu xanh kèm theo đốm trắng, Caladium Baret mang một vẻ đẹp không lẫn vào đâu được giữa các loại caladium khác.', 950000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.307' AS DateTime), CAST(N'2024-11-20T14:49:06.307' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0557', 1, N'LONI004', N'Cây kim ngân', N'Cây kim ngân bính nhỏ chậu ươm LONI004', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.307' AS DateTime), CAST(N'2024-11-20T14:49:06.307' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0558', 1, N'', N'• Môn Ánh Trăng', N'Cây Môn Caladium Moon Light', N'Caladium Moon Light với đặc điểm lá trắng toàn bộ và các đường gân lá như đang “ẩn mình” trên những chiếc lá.', 700000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.307' AS DateTime), CAST(N'2024-11-20T14:49:06.307' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0559', 1, N'', N'• Cây trúc mây
• Cây mật cật', N'Cây Trúc Mây Rhapis Palm', N'Cây trúc mây (hay mật cật) là loại cây ưa nắng bán phần, có thể sinh trưởng và phát triển bình thường trong điều kiện ánh sáng yếu. Đồng thời nó có khả năng thanh lọc không khí và hạn chế bức xạ từ thiết bị điện tử, đem đến không gian trong lành.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.310' AS DateTime), CAST(N'2024-11-20T14:49:06.310' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0560', 1, N'LYRA025', N'Bàng Singapore / Sung tỳ bà', N'Cây bàng Singapore lớn 2 thân chậu xi măng LYRA025', N'Cây Bàng Singapore Lớn có thể dễ dàng nhận ra ở những góc quán cafe, bàn làm việc công. Với những chiếc lá căng bóng hình đàn vĩ cầm rất lớn, nhiều gân là hình chân chim nổi bật và sức sống rất mạnh mẽ và chắc chắn sẽ là một sự bổ sung tuyệt đẹp cho những góc trang trí cho góc làm việc, căn phòng, ngôi nhà của bạn.', 550000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.310' AS DateTime), CAST(N'2024-11-20T14:49:06.310' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0561', 1, N'', N'Cây trầu bà đế vương vàng', N'Cây Trầu Bà Đế Vương Đỏ Philodendron Imperial Red', N'Trầu Bà Đế Vương có tên tiếng Anh là Philodendron Imperial thuộc họ Araceae (Ráy), là dòng cây thân thảo, trong tự nhiên dòng cây này có thể cao hơn 1.5m, nhưng với mục đích trang trí thì MOW sẽ gửi đến các bạn cây với kích cỡ nhỏ để tiện đặt ở bất cứ đâu mình thích.', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.310' AS DateTime), CAST(N'2024-11-20T14:49:06.310' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0562', 1, N'', N'• Môn Nữ Hoàng', N'Cây Môn Caladium White Queen', N'Caladium White Queen với những đường gân đỏ chạy dọc theo những chiếc lá nền trắng đã làm nên tên tuổi của nó – Môn Nữ Hoàng', 500000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.313' AS DateTime), CAST(N'2024-11-20T14:49:06.313' AS DateTime))
