INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0563', 1, N'', N'Cây trầu bà đế vương vàng', N'Cây Trầu Bà Đế Vương Vàng Philodendron Imperial Golden', N'Trầu Bà Đế Vương có tên tiếng Anh là Philodendron Imperial thuộc họ Araceae (Ráy), là dòng cây thân thảo, trong tự nhiên dòng cây này có thể cao hơn 1,5 m nhưng với mục đích trang trí thì MOW sẽ gửi đến các bạn cây với kích cỡ nhỏ để tiện đặt ở bất cứ đâu mình thích.', 70000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.313' AS DateTime), CAST(N'2024-11-20T14:49:06.313' AS DateTime))
