GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0566', 1, N'', N'• Môn rằn ri
• Môn lính', N'Cây Môn Caladium Hilo Beauty', N'Dòng Caladium với họa tiết khá là bắt mắt, khá giống với họa tiết rằn ri thường xuất hiện trên áo lính.', 320000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.317' AS DateTime), CAST(N'2024-11-20T14:49:06.317' AS DateTime))
