INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0567', 1, N'', N'• Caladium Frog', N'Cây Môn Caladium Frog In A Blender', N'Dòng cây chắc hẳn sẽ lấy được sự thích thú tò mò từ những người chơi Caladium lâu năm, màu sắc rất hoàn hảo như những cây đột biến.', 1800000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.317' AS DateTime), CAST(N'2024-11-20T14:49:06.317' AS DateTime))
