INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0568', 1, N'', N'• Môn đỏ', N'Cây Môn Caladium Danasty – Môn Đỏ', N'Cây Môn Đỏ Caladium Danasty với màu sắc đỏ rực chắc chắn sẽ góp phần làm cho không gian của bạn thêm sinh động.', 270000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.320' AS DateTime), CAST(N'2024-11-20T14:49:06.320' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0569', 1, N'', N'Đuôi công đốm xanh', N'Cây Đuôi Công Đốm Xanh Calathea leopardina', N'Với các họa tiết đốm đặc trưng trên lá, giống cây đuôi công Calathea leopardina là một loại cây nội thất có tác dụng trang trí tuyệt vời cho không gian nội thất. Không giống như mọi loại đuôi công, giống đuôi công này “dễ chịu” hơn nhiều, có thể sống tại nơi ánh sáng yếu, ưu khí hậu mát mẻ, và chịu được hạn.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.320' AS DateTime), CAST(N'2024-11-20T14:49:06.320' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0570', 1, N'', N'Cây lưỡi Thái', N'Cây lưỡi hổ thái Sansevieria ‘Superba’ SANS001', N'Lưỡi hổ Thái “Futura Superba” là dòng cây cảnh mini có những chiếc lá nhỏ nhắn sọc vằn đẹp mắt, rất phù hợp để trồng trên bàn làm việc, kệ sách hoặc trang trí tiểu cảnh. Cây lưỡi hổ cũng được trồng với tác dụng phong thủy như là sự may mắn cho gia chủ.', 125000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.320' AS DateTime), CAST(N'2024-11-20T14:49:06.320' AS DateTime))
GO
