INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0572', 1, N'SANS701', N'Cây lưỡi mèo Thái xanh', N'Cây lưỡi mèo Thái xanh ‘Hahnii Green’ chậu ươm SANS701', N'Lưỡi hổ mèo “Hahnii Hort” là dòng cây cảnh mini có những chiếc lá nhỏ nhắn màu xanh chủ đạo đẹp mắt, rất phù hợp để trồng trên bàn làm việc, kệ sách hoặc trang trí tiểu cảnh. Cây lưỡi hổ cũng được trồng với tác dụng phong thủy như là sự may mắn cho gia chủ.', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.323' AS DateTime), CAST(N'2024-11-20T14:49:06.323' AS DateTime))
