INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0573', 1, N'SBGH001', N'Cây lưỡi hổ Thái xanh', N'Cây lưỡi hổ Thái xanh ‘Black Gold’ chậu ươm SBGH001', N'Lưỡi hổ Thái xanh “Black Gold” là dòng cây cảnh mini có những chiếc lá nhỏ nhắn màu xanh đen chủ đạo đẹp mắt, rất phù hợp để trồng trên bàn làm việc, kệ sách hoặc trang trí tiểu cảnh. Cây lưỡi hổ cũng được trồng với tác dụng phong thủy như là sự may mắn cho gia chủ.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.323' AS DateTime), CAST(N'2024-11-20T14:49:06.323' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0574', 1, N'STGH002', N'Cây lưỡi hổ Thái vàng mini', N'Cây lưỡi hổ vàng mini ‘Golden Hahnii’ chậu ươm STGH002', N'Lưỡi hổ Thái vàng “Golden Hahnii” là dòng cây cảnh mini với những chiếc lá nhỏ nhắn có màu vàng sáng sọc xanh đẹp mắt, rất phù hợp để trồng trên bàn làm việc, kệ sách hoặc trang trí tiểu cảnh. Cây lưỡi hổ cũng được trồng với tác dụng phong thủy như là sự may mắn cho gia chủ.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.327' AS DateTime), CAST(N'2024-11-20T14:49:06.327' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0575', 1, N'', N'Cây lưỡi hổ hoàng kim', N'Cây Lưỡi Hổ Hoàng Kim Sansevieria trifasciata Gold Flame', N'Lưỡi hổ Gold Flame là dòng “cây cảnh quốc dân” được nhiều người lựa chọn để trồng trang trí trong nhà. Nó không những dễ sống đến mức “gần như bất tử” mà còn giúp mang lại vẻ đẹp tự nhiên, trên lá có những sọc vằn ấn tượng, lá cứng cáp và hình tượng rõ ràng, phù hợp để trồng trong mọi không gian nội thất. Bện cạnh đó, cây lưỡi hổ còn được xem là dòng cây phong thủy mang lại nhiều ý nghĩa cho gia chủ.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.327' AS DateTime), CAST(N'2024-11-20T14:49:06.327' AS DateTime))
GO
