INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0604', 1, N'LONI008', N'Cây kim ngân', N'Cây kim ngân một thân để bàn chậu sứ LONI008', N'Cây Kim Ngân là loại cây cảnh trong nhà được trồng phổ biến trên khắp thế giới, nó có sức ảnh hưởng tới mức mà hầu như ai cũng tin rằng khi trồng có thể mang lại nhiều may mắn trong cuộc sống, công việc hoặc làm ăn.', 280000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.353' AS DateTime), CAST(N'2024-11-20T14:49:06.353' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0605', 1, N'CATH220', N'Cây đuôi công', N'Cây đuôi công Calathea Rosy Thai CATH220', N'Calathea roseopicta Rosy là loài thực vật thân thảo, có lá hình thuôn tròn, màu hồng. Loài này rất dễ sống, thường được trồng để trang trí trong nhà, thanh lọc không khí và mang ý nghĩa đem lại may mắn, thành công và thịnh vượng.', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.353' AS DateTime), CAST(N'2024-11-20T14:49:06.353' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0606', 1, N'CATH120', N'Cây đuôi công hồng', N'Cây đuôi công hồng Calathea Crimson CATH120', N'Calathea roseopicta Crimson là loài thực vật thân thảo, có lá hình thuôn tròn, màu hồng, hay được gọi với tên là Cây Đuôi Công Hồng. Loài này rất dễ sống, thường được trồng để trang trí trong nhà, thanh lọc không khí và mang ý nghĩa đem lại may mắn, thành công và thịnh vượng.', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.357' AS DateTime), CAST(N'2024-11-20T14:49:06.357' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0607', 1, N'', N'Cây vạn lộc', N'Cây Vạn Lộc Thủy Sinh Aglaonema Lady Valentine', N'Cây vạn lộc (Aglaonema Lady Valentine) là dòng cây cảnh nội thất dễ chăm sóc, có thể sống được trong điều kiện ánh sáng thấp. Với một hình dạng lá độc đáo, bên trên là những họa tiết đẹp mắt giống như tranh vẽ giúp tạo thêm điểm nhấn cho không gian nội thất. Kích thước nhỏ gọn của cây vạn lộc thủy sinh rất thích hợp để đặt trang trí trên bàn hoặc trên tủ kệ.', 220000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.357' AS DateTime), CAST(N'2024-11-20T14:49:06.357' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0608', 1, N'ZAMI006', N'Cây Kim Tiền', N'Cây kim tiền thủy sinh để bàn chậu thủy tinh ZAMI006', N'Kim Tiền được biết tới là một loại cây phong thủy có tác dụng chiêu tài rất tốt khi được trồng trong nhà. Đặt một chậu cây kim tiền thủy sinh nhỏ trên bàn làm việc sẽ giúp bạn thêm tài lộc, vận may, sức khỏe và giàu sang. Nếu trồng cây kim tiền nở hoa thì gia chủ lại càng đắc lộc.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.360' AS DateTime), CAST(N'2024-11-20T14:49:06.360' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0609', 1, N'PEAC003', N'Cây Lan Ý', N'Cây lan ý thủy sinh để bàn chậu nhựa PEAC003', N'Cây lan ý thuộc giống cây rất dễ sống, thường được trồng để trang trí trong nhà cần ít ánh sáng, thanh lọc không khí. Nó cũng loại bỏ nhiều chất độc từ không khí trong nhà bao gồm cả formaldehyde và amoniac. Ngoài ra Cây Lan Ý mang ý nghĩa đem lại may mắn, thành công và thịnh vượng, hợp với người mệnh Kim và Thủy', 185000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.360' AS DateTime), CAST(N'2024-11-20T14:49:06.360' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0610', 1, N'', N'Cây ngọc ngân', N'Cây Ngọc Ngân Thủy Sinh Aglaonema Snow White AGLA003', N'Cây ngọc ngân là là cây trong nhà được đánh giá cao về phong thuỷ, người ta quan niệm rằng cây Ngọc ngân mang đến tài lộc, may mắn khi đặt trên bàn làm việc hay trang trí trong văn phòng. Về mặt tinh thần cây Ngọc ngân rất thích hợp làm quà tặng tình yêu.', 240000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.360' AS DateTime), CAST(N'2024-11-20T14:49:06.360' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0611', 1, N'SCHE003', N'Cây ngũ gia bì', N'Cây ngũ gia bì thủy sinh để bàn SCHE003', N'Cây ngũ gia bì phù hợp để trồng trong nhà trang trí phòng khách, phòng ngủ, văn phòng. Đảm bảo cây nhận được đủ ánh sáng như gần cửa hay dưới ánh đèn giúp cây có thể quang hợp.', 220000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.363' AS DateTime), CAST(N'2024-11-20T14:49:06.363' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0612', 1, N'AGAU004', N'Cây phú quý viền đỏ', N'Cây Phú Quý Thủy Sinh Để Bàn Aglaonema ‘Aurora’ chậu thủy tinh AGAU004', N'Cây phú quý là dòng cây cảnh nội thất dễ chăm sóc, có thể sống được trong điều kiện ánh sáng thấp. Với một bộ lá độc đáo, trên đó là những họa tiết đẹp như tranh vẽ và bề mặt lá bóng bắt sáng giúp tạo thêm điểm nhấn cho không gian nội thất. Kích thước nhỏ gọn của cây phú quý thủy sinh rất thích hợp để đặt trang trí trên bàn hoặc trên tủ kệ.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.363' AS DateTime), CAST(N'2024-11-20T14:49:06.363' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0613', 1, N'', N'Cây sao sáng', N'Cây Sao Sáng Thủy Sinh Dieffenbachia Camilla', N'Cây sao sáng (Dieffenbachia Camilla) là dòng cây cảnh nội thất dễ chăm sóc, có thể sống được trong điều kiện ánh sáng thấp. Với một bộ lá độc đáo, trên đó là những họa tiết đẹp như tranh vẽ giúp tạo thêm điểm nhấn cho không gian nội thất. Kích thước nhỏ gọn của cây sao sáng thủy sinh rất thích hợp để đặt trang trí trên bàn hoặc trên tủ kệ.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.363' AS DateTime), CAST(N'2024-11-20T14:49:06.363' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0614', 1, N'EPAU004', N'Cây Trầu Bà Xanh', N'Cây Trầu Bà Thủy Sinh Epipremnum aureum chậu thủy tinh EPAU004', N'Cây Trầu Bà là một cái tên khá quen thuộc với đa số người Việt Nam, đến bất cứ đâu chúng ta cũng có thể bắt gặp hình bóng của loài cây này vì nó là một loại cây cảnh trong nhà cực kỳ khỏe mạnh, với bộ lá xanh quanh năm và tuổi thọ khá cao.', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.367' AS DateTime), CAST(N'2024-11-20T14:49:06.367' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0615', 1, N'', N'Cây lưỡi hổ', N'Cây Lưỡi Hổ Thủy Sinh Sansevieria trifasciata', N'Cây lưỡi hổ có thể được gọi là loài cây “quốc dân”, hầu như ở mỗi gia đình tại Việt Nam chúng ta đều dễ dàng bắt gặp loài cây này. Với đặc tính dễ chăm sóc, sức sống khỏe, ít khi bị bệnh, giá thành bình dân. Một điều rất thú vị khi trồng dưới dạng thủy sinh là chúng ta có thể quan sát trọn vẹn quá trình bén rễ của cây.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.367' AS DateTime), CAST(N'2024-11-20T14:49:06.367' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0616', 1, N'RADE004', N'Cây hạnh phúc', N'Cây hạnh phúc thân cổ thụ để bàn RADE004', N'Cây dễ sinh trưởng phát triển mọi diều kiện thời tiết khác nhau nên rất dễ trồng và chăm sóc. Cây sống tốt trong điều kiện có điều hoà và môi trường thiếu sáng nên chúng ta có thể dễ dàng lựa chọn cây trang trí để bàn cho không gian làm việc trở nên xanh mát và ấm áp.', 360000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.367' AS DateTime), CAST(N'2024-11-20T14:49:06.367' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0617', 1, N'FICU059', N'Cây hạnh phúc', N'Cây đa tam phúc một thân chậu ươm FICU059', N'Ficus Triangularis Variegata còn gọi là Si Thái cẩm thạch hay Đa tam phúc.', 380000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.370' AS DateTime), CAST(N'2024-11-20T14:49:06.370' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0618', 1, N'', N'Callisia Repens', N'Callisia Repens “Pink Lady” ', N'Callisia Repens “Pink Lady” thuộc họ thài lài, là cây thường xanh sống lâu năm, cây mọng nước, thân cao chỉ khoảng 10cm, với những cuống lá đầy những chiếc lá nhỏ.', 165000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.370' AS DateTime), CAST(N'2024-11-20T14:49:06.370' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0619', 1, N'CKNL005', N'Kim ngân lượng', N'Cây kim ngân lượng chậu sứ trang trí tết CKNL005', N'Cây kim ngân lượng mang vẻ đẹp lộng lẫy với chùm quả đỏ tươi xum xuê, mang hàm ý về tiền tài và phú quý. Trưng cây kim ngân lượng vào những dịp đầu năm là một cách để chiêu tài, may mắn trong dịp Tết. Những người làm ăn kinh doanh khi trồng kim ngân lượng sẽ giúp công việc buôn bán suôn sẻ và thuận lợi.', 550000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.370' AS DateTime), CAST(N'2024-11-20T14:49:06.370' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0620', 1, N'', N'Cây Trầu Bà', N'Cây Trầu Bà Leo Cột Epipremnum Aureum', N'Cây trầu bà leo cột còn có tên gọi khác là Cây Trầu Bà Xanh, cây Hoàng kim, Với kích thước khá lớn, đây chắc hẳn là một trong những công cụ đắc lực để tạo thêm mảng xanh cho không gian của bạn. Với sức sống mãnh liệt, dễ sinh tồn, trong phong thủy nó có ý nghĩa mang đến bình an, sung túc, may mắn, thể hiện sự mạnh mẽ và ý chí vươn lên của gia chủ.', 650000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.370' AS DateTime), CAST(N'2024-11-20T14:49:06.370' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0621', 1, N'', N'Hoàng Tâm Diệp', N'Trầu Bà Lụa – Scindapsus Pictus ‘Exotica’', N'Scindapsus Pictus ‘Exotica’ là một loài thực vật có nguồn gốc từ các vùng ấm và ẩm ướt, dễ dàng được lòng những người thích cây treo, cây leo hoặc các giống cây quý hiếm vì nó có hoa văn và màu sắc đẹp. Đặt Trầu bà lụa của bạn xa vật nuôi và trẻ em vì chúng rất độc nếu ăn phải.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.373' AS DateTime), CAST(N'2024-11-20T14:49:06.373' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0622', 1, N'SANS400', N'Cây Trầu Bà Lụa', N'Lưỡi Hổ Bạc Sansevieria ‘Moonshine’ SANS400', N'Khác với với những dòng cây lưỡi hổ mà ta thường thấy, loại lưỡi hổ Moonshine thì không có nhiều vằn ấn tượng như vậy, bù lại nó sở hữu một màu bạc xanh tươi sáng, thanh lịch và nhẹ nhàng. Nếu bạn là một người yêu thích tính đơn giản mà tinh tế thì cây lưỡi hộ bạc (hay lưỡi hổ bạch kim) là một sự lựa chọn rất tuyệt vời.', 125000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.373' AS DateTime), CAST(N'2024-11-20T14:49:06.373' AS DateTime))
GO
