INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0625', 1, N'', N'Cây Lá Bạc ', N'Cây Lá Bạc Pilea Cadierei', N'', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.377' AS DateTime), CAST(N'2024-11-20T14:49:06.377' AS DateTime))
