INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0626', 1, N'', N'Kiếm bạc', N'Cây Kiếm Bạc Philodendron Hastatum', N'Philodendron Hastatum mang một nét đặc trưng khó nhầm lẫn, lá mang hình dáng của thanh gươm màu xanh lơ pha bạc, là một loài cây khá dễ chịu với tốc độ phát triển khá ổn định.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.380' AS DateTime), CAST(N'2024-11-20T14:49:06.380' AS DateTime))
GO
