INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0630', 1, N'TBDV502', N'Trầu bà kim cương', N'Cây trầu bà đế vương kim cương lớn chậu ươm TBDV502', N'Cây Đế Vương Kim Cương đang trở thành loại cây nội thất phổ biến bởi vẻ đẹp lạ mắt mà nó mang lại. Trồng loại cây này trong nhà sẽ giúp mang chút điểm nhấn với viền sọc trắng xanh trên những chiếc lá cứng cáp. Đây cũng là loại cây phong thủy rất thích hợp để trên bàn làm việc.', 320000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.383' AS DateTime), CAST(N'2024-11-20T14:49:06.383' AS DateTime))
GO
