INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0633', 1, N'', N'• Trầu bà lá xẻ
• Trầu bà Nam Mỹ
• Trầu bà Monstera
• Monstera Deliciosa', N'Trầu bà lá xẻ Monstera Deliciosa cây con', N'Cây trầu bà lá xẻ (hay Monstera Deliciosa) là một loài cây kiểng lá “quốc dân”, được ưu chuộng khắp nơi trên thế giới. Nhờ sở hữu một bộ lá ấn tượng, trang nhã và sang trong mà chúng luôn trở thành tâm điểm điểm của những hình ảnh đại diện cho các nhãn hàng, thương hiệu cho tới cá nhân trên các trang mạng xã hội.', 150000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.387' AS DateTime), CAST(N'2024-11-20T14:49:06.387' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0634', 1, N'MOAD001', N'Cây trầu bà lỗ', N'Cây trầu bà lỗ Monstera adansonii chậu ươm MOAD001', N'Trầu bà lỗ có tên khoa học là, Monstera adansonii, hay còn được gọi là Swiss Cheese Vine, với bộ lá xanh mát hình chóp và dễ sống trong nhà nên loại cây này rất được ưu chuộng. Mỗi chiếc lá có đầy những lỗ hình bầu dục tự nhiên trông rất lạ mắt giúp nó khó nhầm lẫn với các loại cây khác.', 80000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.390' AS DateTime), CAST(N'2024-11-20T14:49:06.390' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0635', 1, N'MARA100', N'Cây cầu nguyên', N'Cây cầu nguyện Maranta leuconeura ‘massangeana’ MARA100', N'Maranta leuconeura ‘massangeana’ là một loại cây nội thất có tác dụng trang trí tuyệt vời cho không gian nội thất. Loại này khá dễ chăm sóc, có thể sống tại nơi ánh sáng yếu, ưu khí hậu mát mẻ, và chịu được hạn.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.390' AS DateTime), CAST(N'2024-11-20T14:49:06.390' AS DateTime))
GO
