INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0656', 1, N'CATH100', N'Cây đuôi phụng', N'Cây đuôi phụng Calathea Lancifolia CATH100', N'Calathea Lancifolia là loại cây trong nhà được ưu chuộng với bộ lá thuôn dài, bàu tròn mềm mại, bên trên là những họa tiết ấn tượng và quyến rũ. Vẻ đẹp độc đáo của loài cây này khiến cho người ta phải gọi nó bằng cái tên là cây đuôi phụng, và luôn là một sự lựa chọn tuyệt hảo để trang trí cho không gian thêm phần sinh động.', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.413' AS DateTime), CAST(N'2024-11-20T14:49:06.413' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0657', 1, N'', N'Cây Đuôi Công', N'Cây Đuôi Công Calathea Fasciata Borrusica', N'Calathea Fasciata Borrusica là loài thực vật thân thảo, có lá hình thuôn tròn, màu xanh đậm, họa tiết viền xanh nhạt. Loài này rất dễ sống, thường được trồng để trang trí trong nhà, thanh lọc không khí và mang ý nghĩa đem lại may mắn, thành công và thịnh vượng.', 450000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.413' AS DateTime), CAST(N'2024-11-20T14:49:06.413' AS DateTime))
