INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0672', 1, N'SCHE010', N'Ngũ gia bì cẩm thạch', N'Cây ngũ gia bì cẩm thạch chậu ươm SCHE010', N'Ngũ gia bì là loại cây mang lại tài vận, thịnh vượng và may mắn, trồng trong nhà sẽ mang đến một không gian thư thái, trong lành cho gia đình.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.430' AS DateTime), CAST(N'2024-11-20T14:49:06.430' AS DateTime))
