INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0673', 1, N'MONS007', N'Cây Trầu Bà Lỗ', N'Cây Trầu Bà Lỗ Monstera adansonii Monkey Mask – MONS007', N'Monstera adansonii là cây thân thảo, thích nghi với bóng râm hoàn toàn, vì vậy chúng thường được trồng trong nhà, sức sống mạnh mẽ, dễ dàng chăm sóc và có thể tồn tại trong nhiều môi trường khác nhau, gốc nhiều nhánh và đốt.
Với những chiếc lá xanh tươi, thân hình nhỏ nhắn trông rất dễ thương có thể sẽ rất phù hợp với các bạn nữ, nhân viên văn phòng trong lúc mệt mỏi có thể ngắm nhìn để giải tỏa phần nào áp lực công việc, cuộc sống.', 165000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.430' AS DateTime), CAST(N'2024-11-20T14:49:06.430' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0674', 1, N'CRYP001', N'Cây dứa hồng phụng / Lưỡi rồng', N'Cây dứa hồng phụng Cryptanthus ‘Elaine’ chậu ươm CRYP001', N'Với hoa văn độc đáo và màu sắc sặc sỡ, cây dứa hồng phụng rất thích hợp làm cây để bàn, hoặc là món quà tặng ý nghĩa nhân dịp lễ tết, mừng khai trương, thăng chức. Nếu trồng trong nhà, cây mang ý nghĩa giúp không khí tích cực, tăng cường tình yêu gia đình.', 80000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.430' AS DateTime), CAST(N'2024-11-20T14:49:06.430' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0675', 1, N'', N'Cây cọ Nhật / Kè Nhật', N'Cây cọ nhật nhỏ chậu ươm LICU001', N'Cọ Nhật là loại cây sở hữu bộ lá vừa to vừa xanh, chỉ cần trồng một cây là đủ để phủ xanh không gian sống. Bên cạnh đó loại cây này trong thủy được xem là có tác dụng sinh tài, giữ của, và giúp tạo nên sự sang trọng bởi vẻ ngoài thanh lịch của chúng.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.433' AS DateTime), CAST(N'2024-11-20T14:49:06.433' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0676', 1, N'CTBH001', N'Cây trúc bách hợp', N'Cây trúc bách hợp một thân Dracaena reflexa CTBH001', N'', 450000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.433' AS DateTime), CAST(N'2024-11-20T14:49:06.433' AS DateTime))
