INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0678', 1, N'', N'Cây Cung Điện Vàng', N'Cây Cung Điện Vàng – Chậu Đất Nung', N'Cây Cung Điện Vàng được tìm thấy ở những khu rừng khí hậu nhiệt đới gió mùa, thành ra chúng phát triển hoàn hảo với sinh nhưỡng của Việt Nam. Cây vô cùng khỏe, ưa môi trường mát có độ ẩm cao vì vậy cây cung điện là lựa chọn hoàn hảo cho decor phòng khách hoặc phòng ngủ hiện đại.', 220000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.437' AS DateTime), CAST(N'2024-11-20T14:49:06.437' AS DateTime))
GO
