INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0681', 1, N'ASPL140', N'Ráng ổ phụng', N'Cây ráng tổ phụng nhỏ chậu ươm ASPL140', N'Ráng ổ phụng là loại cây thuộc họ dương xỉ, có sức sống rất mãnh liệt, loài này có hình hài rất giống với tổ chim nên nó được xem là biểu tượng cho sự ấm áp, hạnh phúc và xum vầy trong gia đình.', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.440' AS DateTime), CAST(N'2024-11-20T14:49:06.440' AS DateTime))
