INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0684', 1, N'ZAMI004', N'Cây kim tiền / Cây kim phát tài', N'Cây kim tiền để bàn chậu sứ ZAMI004', N'Cây kim tiền được đánh giá rất cao là loại cây phong thủy đem đến tài lộc, thịnh vượng, giàu sang, sức khỏe cho gia chủ.Đặc biệt khi kim tiền nở hoa gia chủ càng đắc lộc.', 150000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.440' AS DateTime), CAST(N'2024-11-20T14:49:06.440' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0685', 1, N'', N'Cây Lan Tim Nhí/ Cây Khúc Thủy', N'Cây Lan Tim Nhí/ Cây Khúc Thủy – Cao 10cm', N'', 105000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.443' AS DateTime), CAST(N'2024-11-20T14:49:06.443' AS DateTime))
