INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0686', 1, N'CPTK004', N'Cây phát tài khúc', N'Cây phát tài khúc bộ 3 chậu sứ trắng CPTK004', N'Loài cây nội thất được đánh giá là đem lại nhiều sinh khí, may mắn và thịnh vượng cho gia chủ, nhất là khi cây nở hoa là dấu hiệu tiền tài đang đến với bạn. Hơn nữa, nếu bạn đặt cây theo hướng Đông hay Đông Nam của ngôi nhà thì sẽ đem tới nhiều may mắn bởi cây là đại diện cho hành Mộc.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.443' AS DateTime), CAST(N'2024-11-20T14:49:06.443' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0687', 1, N'', N'Cây Trúc Nhật Vàng', N'Cây Trúc Nhật Vàng – Cao 20cm', N'', 75000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.443' AS DateTime), CAST(N'2024-11-20T14:49:06.443' AS DateTime))
