INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0688', 1, N'PEOB004', N'Cây trường sinh cẩm thạch', N'Cây trường sinh cẩm thạch chậu đất nung PEOB004', N'Cây trường sinh cẩm thạch là một loại cây cảnh trong nhà đẹp mắt, với bộ lá luôn xanh mát, sức sống mãnh liệt, dễ chăm sóc. Đây cũng là loại cây phong thủy với tác dụng mang đến sức khỏe, may mắn và tiền tài tới cho gia chủ. Người ta thường hay tặng cây trường sinh vào những dịp đặc biệt như là một lời chúc phúc tới người nhận.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.447' AS DateTime), CAST(N'2024-11-20T14:49:06.447' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0689', 1, N'ZAMI005', N'Cây kim tiền', N'Cây kim tiền chậu đất nung họa tiết thổ cẩm ZAMI005', N'Cây kim tiền rất dễ sống vì có thể trồng tại nơi có ít ánh sáng, và nó cũng không cần đến quá nhiều nước để phát triển. Loại cây này thường được lựa chọn để đặt trong nhà để tạo thêm mảng xanh, đồng thời được trồng với tác dụng phong thủy.', 185000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.447' AS DateTime), CAST(N'2024-11-20T14:49:06.447' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0690', 1, N'ZAMI009', N'Cây kim tiền', N'Cây kim tiền để bàn chậu men sứ ZAMI009', N'Cây kim tiền hay kim phát tài là loại cây phong thủy rất được ưu chuộng và lựa chọn, với mong muốn công việc làm ăn luôn gặp thuận lợi, dù to nhỏ cũng đều suôn sẻ như sức sống của cây vậy.', 420000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.447' AS DateTime), CAST(N'2024-11-20T14:49:06.447' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0691', 1, N'', N'Cây Rau Má Kiểng/ Cỏ Đồng Tiền', N'Cây Rau Má Kiểng/ Cỏ Đồng Tiền – Cao 18cm', N'', 45000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.450' AS DateTime), CAST(N'2024-11-20T14:49:06.450' AS DateTime))
