INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0692', 1, N'AGLA050', N'Phú quý đỏ', N'Cây phú quý viền đỏ ‘Red Siam’ chậu ươm AGLA050', N'Aglaonema Red là loại cây trong nhà có thân màu trắng hồng, lá màu xanh viền đỏ đẹp mắt, Loài này rất dễ sống, thường được trồng để trang trí trong nhà, thanh lọc không khí và cũng là loại cây phong thủy, tượng trưng cho tài lộc và may mắn.', 75000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.450' AS DateTime), CAST(N'2024-11-20T14:49:06.450' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0693', 1, N'AGLA001', N'Cây ngọc ngân', N'Cây ngọc ngân ‘Snow White’ chậu ươm AGLA001', N'Cây ngọc ngân là là cây trong nhà được đánh giá cao về phong thuỷ, người ta quan niệm rằng cây Ngọc ngân mang đến tài lộc, may mắn khi đặt trên bàn làm việc hay trang trí trong văn phòng. Về mặt tinh thần cây Ngọc ngân rất thích hợp làm quà tặng tình yêu.', 75000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.450' AS DateTime), CAST(N'2024-11-20T14:49:06.450' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0694', 1, N'', N'Cây ngọc ngân', N'Cây Càng Cua Cẩm Thạch Peperomia scandens Variegata – Cao 16 Cm', N'Cây Càng Cua Cẩm Thạch Peperomia scandens Variegata dây leo mỏng manh, có lá màu xanh nhạt, trắng sữa, hình trái tim và cuối cùng rụng xuống khi chúng trưởng thành. Một loại cây biểu trưng cho vui vẻ, nhẹ nhàng và tươi tốt chắc chắn sẽ mang lại nụ cười cho bạn.', 85000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.450' AS DateTime), CAST(N'2024-11-20T14:49:06.450' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0695', 1, N'ANTH001', N'Cây hồng môn', N'Cây hồng môn nhỏ để bàn chậu ươm ANTH001', N'Cây hồng môn được biết tới là một loại cây cảnh mang lại điều tốt lành, có thể giúp điều hòa khí phong thủy trong nhà, có khả năng thu hút những dòng khí tích cực và làm tiêu bớt dòng khí tiêu cực cho môi trường xung quanh, trồng cây hồng môn trong nhà sẽ giúp không gian sống trở nên hài hòa và bình yên hơn.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.450' AS DateTime), CAST(N'2024-11-20T14:49:06.450' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0696', 1, N'', N'Cây Hoa Lan Quân Tử', N'Cây Hoa Lan Quân Tử – Cao 38cm', N'', 220000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.453' AS DateTime), CAST(N'2024-11-20T14:49:06.453' AS DateTime))
