INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0697', 1, N'PEAC001', N'Cây lan ý / Cánh buồm / Huệ hòa bình', N'Cây lan ý nhỏ chậu ươm PEAC001', N'Cây lan ý thuộc giống cây rất dễ sống, thường được trồng để trang trí trong nhà cần ít ánh sáng, thanh lọc không khí. Nó cũng loại bỏ nhiều chất độc từ không khí trong nhà bao gồm cả formaldehyde và amoniac. Loại cây này còn mang ý nghĩa đem lại may mắn, thành công và thịnh vượng, hợp với người mệnh Kim và Thủy', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.453' AS DateTime), CAST(N'2024-11-20T14:49:06.453' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0698', 1, N'LYRA011', N'Sung tì bà, sung tỳ bà hay sung lá đàn', N'Cây bàng Singapore mini để bàn chậu đất nung LYRA011', N'Cây bàng Singapore đang loại cây trong nhà được nhiều người ưu chuộng. Với bộ lá màu xanh lá mượt mà, dáng thẳng đứng thanh lịch và sang trọng giúp cho không gian nhà bạn thêm phần sinh động. Cây cũng có khả năng thanh lọc không khí giúp không gian thêm trong lanh.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.453' AS DateTime), CAST(N'2024-11-20T14:49:06.453' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0699', 1, N'HAWA001', N'Cau Hawaii', N'Cây cau Hawaii lớn chậu ươm HAWA001', N'Cau Hawaii là một loại cây cây cảnh nội thất phổ biến, thích hợp để trưng bày trong các không gian nội thất sang trọng. Loại cây này có sức sống mãnh liệt, dễ chăm sóc, có bộ lá xanh mướt và mang ý nghĩa rất tốt trong phong thủy.', 320000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.457' AS DateTime), CAST(N'2024-11-20T14:49:06.457' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0700', 1, N'PEOB001', N'Cây trường sinh', N'Cây trường sinh để bàn chậu ươm PEOB001', N'Cây trường sinh là một loại cây cảnh trong nhà đẹp mắt, với bộ lá luôn xanh mát, sức sống mãnh liệt, dễ chăm sóc. Đây cũng là loại cây phong thủy với tác dụng mang đến sức khỏe, may mắn và tiền tài tới cho gia chủ. Người ta thường hay tặng cây trường sinh vào những dịp đặc biệt như là một lời chúc phúc tới người nhận.', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.457' AS DateTime), CAST(N'2024-11-20T14:49:06.457' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0701', 1, N'', N'Cây Vạn Lộc/Thiên Phú', N'Cây Vạn Lộc/Thiên Phú', N'', 115000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.457' AS DateTime), CAST(N'2024-11-20T14:49:06.457' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0702', 1, N'HEDE001', N'Cây thường xuân', N'Cây thường xuân xanh chậu treo HEDE001', N'Cây thường xuân có bộ lá xanh tươi tốt, hình dáng ấn tượng giúp mang lại không gian xanh mát. Đây là dòng cây dễ chăm đang là “trend” được nhiều người lựa chọn trồng trang trí trong nhà rất đẹp.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.460' AS DateTime), CAST(N'2024-11-20T14:49:06.460' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0703', 1, N'DVX001', N'Cây Trầu Bà Đế Vương Xanh', N'Cây Trầu Bà Đế Vương Xanh Để Bàn DVX001', N'Trầu Bà Đế Vương có tên tiếng Anh là Philodendron Imperial thuộc họ Araceae (Ráy). Nguồn gốc của cây từ đảo Solomon, nguyên sinh ở Indonesia, là dòng cây thân thảo, trong tự nhiên dòng cây này có thể cao hơn 1.5m, nhưng với mục đích trang trí thì MOW sẽ gửi đến các bạn cây với kích cỡ nhỏ để tiện đặt ở bất cứ đâu mình thích.', 350000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.460' AS DateTime), CAST(N'2024-11-20T14:49:06.460' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0704', 1, N'PODO002', N'Tùng la hán', N'Cây tùng la hán thủy sinh để bàn PODO002', N'Cây tùng trong phong thủy được coi là loài cây quý có linh khí rất tốt bởi chúng có thể sống hàng trăm năm, giúp cản gió độc, xua đuổi tà khí, tránh những điều xui xẻo và đem lại sự trường thọ gia chủ.', 140000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.460' AS DateTime), CAST(N'2024-11-20T14:49:06.460' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0705', 1, N'CDBD004', N'Đa búp đỏ', N'Cây đa búp đỏ để bàn 3 thân chậu sứ trắng CDBD004', N'Từ lâu cây Đa luôn là biểu tượng của sự trường tồn, sức sống dẻo dai, nơi chứa đựng thần quyền và tâm linh của con người. Chính lẽ đó mà trong phong thủy, Đa Búp Đỏ cũng mang ý nghĩa của sự may mắn, an lành.', 230000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.463' AS DateTime), CAST(N'2024-11-20T14:49:06.463' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0706', 1, N'RADE001', N'Cây hạnh phúc', N'Cây hạnh phúc để bàn chậu ươm RADE001', N'Cây dễ sinh trưởng phát triển mọi diều kiện thời tiết khác nhau nên rất dễ trồng và chăm sóc. Cây sống tốt trong điều kiện có điều hoà và môi trường thiếu sáng nên chúng ta có thể dễ dàng lựa chọn cây trang trí để bàn cho không gian làm việc trở nên xanh mát và ấm áp.', 250000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.463' AS DateTime), CAST(N'2024-11-20T14:49:06.463' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0707', 1, N'SPID001', N'Cây cỏ lan chi / cây dây nhện', N'Cây cỏ lan chi để bàn chậu ươm SPID001', N'Cỏ Lan Chi (hay còn gọi là Cỏ Nhện) là loại cây rất dễ sống với điều kiện khí hậu nóng tại Việt Nam. Đặc biệt, nó nằm trong top các loại cây lọc không khí rất hiệu quả, có thể đặt trong phòng ngủ giúp bạn có giấc ngủ trong lành hơn.', 30000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.463' AS DateTime), CAST(N'2024-11-20T14:49:06.463' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0708', 1, N'CASA001', N'Calathea ornata Sanderiana', N'Cây đuôi công sọc Calathea Sanderiana chậu ươm CASA001', N'Calathea ornata Sanderiana là loài thực vật thân thảo, có lá hình thuôn tròn, sọc trắng xanh. Loài này rất dễ sống, thường được trồng để trang trí trong nhà, thanh lọc không khí và mang ý nghĩa đem lại may mắn, thành công và thịnh vượng.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.467' AS DateTime), CAST(N'2024-11-20T14:49:06.467' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0709', 1, N'', N'Cây trầu bà cẩm thạch', N'Cây Trầu Bà Lá Sữa Epipremnum pinnatum NJoy', N'Cây Trầu Bà Sữa hay còn gọi là Trầu Bà Cẩm Thạch, là một người “anh em” của cây Trầu Bà thông thường nên nó sở hữu những đặc điểm và tính chất tương tự. Nó có tên khoa học là Epipremnum ‘Marble Queen’ hay có thể gọi với tên tiếng Anh là Epipremnum pinnatum ‘NJoy’, thuộc họ Ráy (Araceae), có nguồn gốc từ miền bắc Australia, Malaysia.', 125000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.467' AS DateTime), CAST(N'2024-11-20T14:49:06.467' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0710', 1, N'CATH001', N'Cây đuôi công táo xanh', N'Cây đuôi công táo xanh Calathea Orbifolia chậu ươm CATH001', N'Cây đuôi công táo xanh là loài thực vật thân thảo, có lá hình thuôn tròn, sọc trắng xanh. Hay được gọi với tên là Cây Đuôi Công Táo Xanh. Loài này rất dễ sống, thường được trồng để trang trí trong nhà, thanh lọc không khí và mang ý nghĩa đem lại may mắn, thành công và thịnh vượng.', 180000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.470' AS DateTime), CAST(N'2024-11-20T14:49:06.470' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0711', 1, N'', N'Cây hoàng hậu chậu sứ', N'Cây hoàng hậu chậu sứ', N'Cây Hoàng Hậu có tên khoa học Aglaonema Diamond Bay, thuộc họ Araceae (ráy) có hoa, dòng Aglaonema phổ biến với các loại cây như: Vạn Lộc, Giữ Tiền, Bạch Mã Hoàng Tử, Phú Quý, Ngọc Ngân…Lá có chiều rộng trung bình khoảng 10cm, dài 20cm, rộng ở giữa và thuôn dần ở phía đầu, mặt sau của lá có màu xanh, lá mềm, nhẵn không có răng cưa hay gai.', 270000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.470' AS DateTime), CAST(N'2024-11-20T14:49:06.470' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0712', 1, N'PHIG003', N'Trầu bà đế vương xanh', N'Cây Trầu Bà Đế Vương Xanh Thủy Sinh ‘Imperial Green’ PHIG003', N'Trầu Bà Đế Vương Xanh (Philodendron Imperial Green) là một giống cây rất ưu chuộng để trồng với ý nghĩa phong thủy mà nó mang lại. Nên đặt cây tại các vị trí như trong phòng khách, phòng làm việc, văn phòng hoặc sảnh ra vào cơ quan.', 185000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.470' AS DateTime), CAST(N'2024-11-20T14:49:06.470' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0713', 1, N'', N'Ngũ gia bì cẩm thạch', N'Cây ngũ gia bì xanh mini chậu ươm SCHE001', N'Ngũ gia bì là loại cây mang lại tài vận, thịnh vượng và may mắn, trồng trong nhà sẽ mang đến một không gian thư thái, trong lành cho gia đình.', 90000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.470' AS DateTime), CAST(N'2024-11-20T14:49:06.470' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0714', 1, N'LYRA001', N'Cây bàng Singapore mini', N'Cây bàng Singapore mini chậu ươm LYRA001', N'Cây bàng Singapore mini là dòng cây cảnh mini có những chiếc lá nhỏ cừng cáp đẹp mắt, rất phù hợp để trồng trên bàn làm việc, kệ sách hoặc trang trí tiểu cảnh. Cây bàng Singapore cũng được trồng với tác dụng phong thủy như là sự may mắn cho gia chủ.', 90000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.473' AS DateTime), CAST(N'2024-11-20T14:49:06.473' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0715', 1, N'TBDB', N'Cây Trầu Bà', N'Cây Trầu Bà Để Bàn TBDB', N'Cây trầu bà có ý nghĩa phong thủy mang lại những điều may mắn, hạnh phúc và ấm êm cho gia chủ. Bên cạnh đó cây trầu bà cũng là loại cây vô cùng dễ dàng chăm sóc và phát triển. Rất thích hợp được trang trí trên bàn làm việc, treo cửa sổ, bancony, góc phòng…', 120000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.473' AS DateTime), CAST(N'2024-11-20T14:49:06.473' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0716', 1, N'LYRA010', N'Cây bàng Singapore', N'Cây bàng Singapore mini để bàn chậu sứ LYRA010', N'Bàng Singapore đang loại cây trong nhà được nhiều người ưu chuộng. Với bộ lá màu xanh lá mượt mà, dáng thẳng đứng thanh lịch và sang trọng giúp cho không gian nhà bạn thêm phần sinh động.', 160000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.473' AS DateTime), CAST(N'2024-11-20T14:49:06.473' AS DateTime))
GO
INSERT [dbo].[Products] ([product_id], [type], [code], [name], [short_description], [detailed_description], [price], [total_orders], [total_ratings], [overall_stars], [is_returnable], [created_at], [updated_at]) VALUES (N'CCNPLT0717', 1, N'ZAMI003', N'Cây kim tiền / Cây kim phát tài', N'Cây kim tiền kích thước lớn chậu ươm ZAMI003', N'Cây kim tiền được đánh giá rất cao là loại cây phong thủy đem đến tài lộc, thịnh vượng, giàu sang, sức khỏe cho gia chủ.Đặc biệt khi kim tiền nở hoa gia chủ càng đắc lộc.', 420000, NULL, NULL, NULL, 1, CAST(N'2024-11-20T14:49:06.477' AS DateTime), CAST(N'2024-11-20T14:49:06.477' AS DateTime))
GO
